/**
 * Onboarding-майстер.
 *
 * Створює стейт, прокидає його між кроками, рендерить stepper-індикатор
 * + поточний крок + панель навігації.
 *
 * Кроки:
 *   1. api-creds         — api_id + api_hash з my.telegram.org
 *   2. phone             — номер телефону
 *   3. code              — код підтвердження
 *   4. two-factor        — пароль cloud-password (якщо вимагає Telegram)
 *   5. channels          — вибір каналів для моніторингу
 *   6. finish            — короткий summary
 */

import { html, raw, mount } from '../shared/dom';
import { icons } from '../shared/icons';
import { toast } from '../shared/toast';
import { AuthFlow, listDialogs, type DialogItem, type TgUser } from '../../core/telegram';
import { requireVault } from '../../core/storage/current-vault';
import { buildApiCredsStep } from './steps/api-credentials';
import { buildPhoneStep } from './steps/phone';
import { buildCodeStep } from './steps/code';
import { buildTwoFactorStep } from './steps/two-factor';
import { buildChannelsStep } from './steps/channels-picker';
import { buildFinishStep } from './steps/finish';

export interface WizardState {
  authFlow: AuthFlow;
  apiId?: number;
  apiHash?: string;
  phone?: string;
  user?: TgUser;
  dialogs?: DialogItem[];
  selectedChannelIds?: Set<string>;
  /** Куди Telegram надіслав код останнього разу (для UI повідомлення) */
  lastCodeDestination?: string;
  /** Чи можливе повторне надсилання коду (Telegram дав наступний канал) */
  lastCanResend?: boolean;
  /** className наступного каналу доставки коду (SMS/дзвінок), або null */
  lastNextType?: string | null;
}

export interface WizardApi {
  el: HTMLElement;
  onFinished(handler: () => void): void;
}

type StepId = 'api' | 'phone' | 'code' | 'twofa' | 'channels' | 'finish';

const STEPS: { id: StepId; label: string }[] = [
  { id: 'api',      label: 'API' },
  { id: 'phone',    label: 'Телефон' },
  { id: 'code',     label: 'Код' },
  { id: 'twofa',    label: '2FA' },
  { id: 'channels', label: 'Канали' },
  { id: 'finish',   label: 'Готово' }
];

export function buildOnboardingWizard(): WizardApi {
  const state: WizardState = {
    authFlow: new AuthFlow()
  };

  const finishedHandlers: Array<() => void> = [];

  const root = html`
    <div class="app-main">
      <section class="page" style="max-width: 720px;">
        <header class="page-header" style="border: none; padding-bottom: 0;">
          <div>
            <div class="page-eyebrow">onboarding · підключення</div>
            <h1 class="page-title">Налаштування акаунту</h1>
          </div>
          <div style="color: var(--accent);">${raw(icons.power(28).value)}</div>
        </header>

        <nav class="wizard-stepper" data-vm-stepper></nav>

        <div data-vm-step-slot></div>
      </section>
    </div>
  `;

  // Stepper styling — inline, бо це разовий компонент
  injectStepperStyles();

  const stepperEl = root.querySelector<HTMLElement>('[data-vm-stepper]')!;
  const slotEl    = root.querySelector<HTMLElement>('[data-vm-step-slot]')!;

  const renderStepper = (current: StepId, skipTwoFa: boolean) => {
    stepperEl.replaceChildren();
    const visibleSteps = skipTwoFa ? STEPS.filter(s => s.id !== 'twofa') : STEPS;
    const currentIdx = visibleSteps.findIndex(s => s.id === current);
    visibleSteps.forEach((s, i) => {
      const isCurrent = i === currentIdx;
      const isDone = i < currentIdx;
      const stepEl = html`
        <div class="wizard-step ${isCurrent ? 'current' : ''} ${isDone ? 'done' : ''}">
          <div class="wizard-step-num">
            ${isDone ? raw(icons.check(12).value) : String(i + 1)}
          </div>
          <div class="wizard-step-label">${s.label}</div>
        </div>
      `;
      stepperEl.appendChild(stepEl);
      if (i < visibleSteps.length - 1) {
        stepperEl.appendChild(html`<div class="wizard-step-divider ${isDone ? 'done' : ''}"></div>`);
      }
    });
  };

  let skipTwoFa = true;     // позначаємо true → 2FA не потрібен; перемкнемо при потребі

  const go = async (step: StepId) => {
    renderStepper(step, step === 'twofa' ? false : skipTwoFa);

    let stepEl: HTMLElement;
    switch (step) {
      case 'api': {
        const s = buildApiCredsStep(state);
        s.onNext(({ apiId, apiHash }) => {
          state.apiId = apiId;
          state.apiHash = apiHash;
          go('phone');
        });
        stepEl = s.el;
        break;
      }
      case 'phone': {
        const s = buildPhoneStep(state);
        s.onBack(() => go('api'));
        s.onNext(({ phone }) => {
          state.phone = phone;
          go('code');
        });
        stepEl = s.el;
        break;
      }
      case 'code': {
        const s = buildCodeStep(state);
        s.onBack(() => go('phone'));
        s.onTwoFactorRequired(() => {
          skipTwoFa = false;
          go('twofa');
        });
        s.onSignedIn((user) => {
          state.user = user;
          skipTwoFa = true;
          go('channels');
        });
        stepEl = s.el;
        break;
      }
      case 'twofa': {
        const s = buildTwoFactorStep(state);
        s.onBack(() => go('code'));
        s.onSignedIn((user) => {
          state.user = user;
          go('channels');
        });
        stepEl = s.el;
        break;
      }
      case 'channels': {
        // Підтягуємо діалоги один раз
        if (!state.dialogs) {
          slotEl.replaceChildren(html`
            <div class="panel center" style="min-height: 240px;">
              <div class="col gap-2" style="align-items: center;">
                <div class="led led-warning" style="width: 12px; height: 12px;"></div>
                <div class="text-secondary">Завантажуємо список каналів акаунту…</div>
              </div>
            </div>
          `);
          try {
            state.dialogs = await listDialogs();
          } catch (err) {
            toast.error(`Не вдалося завантажити канали: ${(err as Error).message}`);
            state.dialogs = [];
          }
        }
        const s = buildChannelsStep(state);
        s.onBack(() => go('code'));
        s.onNext(async (selected) => {
          state.selectedChannelIds = selected;
          await persistSelectedChannels(state);
          go('finish');
        });
        stepEl = s.el;
        break;
      }
      case 'finish': {
        const s = buildFinishStep(state);
        s.onDone(() => {
          finishedHandlers.forEach(h => h());
        });
        stepEl = s.el;
        break;
      }
    }
    mount(slotEl, stepEl);
  };

  void go('api');

  return {
    el: root,
    onFinished(handler) { finishedHandlers.push(handler); }
  };
}

async function persistSelectedChannels(state: WizardState): Promise<void> {
  if (!state.dialogs || !state.selectedChannelIds) return;
  const vault = requireVault();
  const selected = state.dialogs.filter(d => state.selectedChannelIds!.has(d.id));
  await vault.channels.setMany(selected);
}

// ────────────────────  inline stepper styles  ────────────────────
let stylesInjected = false;
function injectStepperStyles(): void {
  if (stylesInjected) return;
  stylesInjected = true;
  const style = document.createElement('style');
  style.textContent = `
    .wizard-stepper {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 16px 0;
    }
    .wizard-step {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 6px;
      min-width: 60px;
    }
    .wizard-step-num {
      width: 28px;
      height: 28px;
      border-radius: 50%;
      display: grid;
      place-items: center;
      background: var(--bg-elevated);
      border: 1.5px solid var(--border-base);
      color: var(--fg-muted);
      font-family: var(--font-mono);
      font-size: var(--fs-sm);
      font-weight: 600;
      transition: all var(--t-base);
    }
    .wizard-step.current .wizard-step-num {
      background: var(--accent);
      border-color: var(--accent);
      color: var(--fg-inverse);
      box-shadow: 0 0 0 3px var(--accent-soft);
    }
    .wizard-step.done .wizard-step-num {
      background: var(--success-soft);
      border-color: var(--success);
      color: var(--success);
    }
    .wizard-step-label {
      font-family: var(--font-mono);
      font-size: var(--fs-xs);
      letter-spacing: var(--tracking-wide);
      text-transform: uppercase;
      color: var(--fg-muted);
    }
    .wizard-step.current .wizard-step-label { color: var(--accent); }
    .wizard-step.done .wizard-step-label    { color: var(--success); }
    .wizard-step-divider {
      flex: 1;
      height: 1.5px;
      background: var(--border-base);
      margin-bottom: 18px;
      transition: background var(--t-base);
    }
    .wizard-step-divider.done { background: var(--success); }
  `;
  document.head.appendChild(style);
}
