/**
 * Grid-sweep по порогах на основі мічених entries.
 *
 * Для topic/words рахуємо TP/FP/FN/TN на діапазоні порогів і повертаємо
 * threshold, який максимізує F1 (або precision при заданому recall — за вибором).
 */

import { listEntries, type LabelEntry, type LabelTask } from './labelling-store';

export interface SweepPoint {
  threshold: number;
  tp: number; fp: number; fn: number; tn: number;
  precision: number;
  recall: number;
  f1: number;
  accuracy: number;
}

export interface SweepResult {
  /** Усі точки гриду — для відображення кривої */
  points: SweepPoint[];
  /** Поріг із найвищим F1 */
  bestF1: SweepPoint;
  /** Поріг із найвищим precision (за умови recall ≥ targetRecall) */
  bestPrecisionGivenRecall?: SweepPoint;
  /** Скільки entries реально брало участь */
  sampleSize: number;
  /** Параметри запуску */
  meta: {
    task: LabelTask;
    mode: 'hybrid' | 'qwen';
    accuracy: 1 | 2 | 3;
    min: number; max: number; step: number;
  };
}

export interface SweepOptions {
  task: LabelTask;
  mode: 'hybrid' | 'qwen';
  accuracy: 1 | 2 | 3;
  min?: number;
  max?: number;
  step?: number;
  /** Якщо вказано — шукаємо threshold з максимальним precision при recall ≥ цього. */
  targetRecall?: number;
}

const DEFAULTS_BY_TASK = {
  topic:  { min: 0.20, max: 0.55, step: 0.01 },
  words:  { min: 0.60, max: 0.90, step: 0.01 },
  stance: { min: 0.30, max: 0.60, step: 0.01 } // тут — для intermediate ambiguity threshold
};

export async function sweep(opts: SweepOptions): Promise<SweepResult> {
  const d = DEFAULTS_BY_TASK[opts.task];
  const min  = opts.min  ?? d.min;
  const max  = opts.max  ?? d.max;
  const step = opts.step ?? d.step;

  // Беремо лише мічені entries у потрібній комбінації
  const all = await listEntries({ task: opts.task, onlyLabelled: true });
  const subset = all.filter(e => e.mode === opts.mode && e.accuracy === opts.accuracy);

  const points: SweepPoint[] = [];
  for (let th = min; th <= max + 1e-9; th += step) {
    const th2 = Math.round(th * 100) / 100;
    const p = evaluate(subset, th2);
    points.push(p);
  }

  // F1 max
  const bestF1 = points.reduce((best, p) => (p.f1 > best.f1 ? p : best), points[0]);

  // Precision max при recall ≥ target
  let bestPrecisionGivenRecall: SweepPoint | undefined;
  if (opts.targetRecall !== undefined) {
    const filtered = points.filter(p => p.recall >= opts.targetRecall!);
    if (filtered.length) {
      bestPrecisionGivenRecall = filtered.reduce(
        (best, p) => (p.precision > best.precision ? p : best),
        filtered[0]
      );
    }
  }

  return {
    points,
    bestF1,
    bestPrecisionGivenRecall,
    sampleSize: subset.length,
    meta: { task: opts.task, mode: opts.mode, accuracy: opts.accuracy, min, max, step }
  };
}

function evaluate(entries: LabelEntry[], threshold: number): SweepPoint {
  let tp = 0, fp = 0, fn = 0, tn = 0;
  for (const e of entries) {
    const pred = e.score >= threshold;
    // actualPositive: користувач підтвердив, що текст СПРАВДІ про тему
    // (TP — модель сказала так і правильно; FN — модель сказала ні, а мала).
    // Ми оцінюємо ГІПОТЕТИЧНИЙ поріг, тому predicted рахується через score,
    // незалежно від того що було оригінальне рішення моделі.
    const actualPositive = e.userVerdict === 'tp' || e.userVerdict === 'fn';
    if (pred && actualPositive)      tp++;
    else if (pred && !actualPositive) fp++;
    else if (!pred && actualPositive) fn++;
    else                              tn++;
  }
  const precision = tp + fp === 0 ? 0 : tp / (tp + fp);
  const recall    = tp + fn === 0 ? 0 : tp / (tp + fn);
  const f1 = (precision + recall) === 0 ? 0 : (2 * precision * recall) / (precision + recall);
  const total = tp + fp + fn + tn;
  const accuracy = total === 0 ? 0 : (tp + tn) / total;
  return { threshold, tp, fp, fn, tn, precision, recall, f1, accuracy };
}

/**
 * Sweep по всіх 6 конфігураціях (hybrid×{1,2,3} та qwen×{1,2,3}).
 * Зручно викликати з UI Settings для запису рекомендованих порогів.
 */
export async function sweepAll(task: LabelTask = 'topic'): Promise<SweepResult[]> {
  const modes: ('hybrid' | 'qwen')[] = ['hybrid', 'qwen'];
  const levels: (1 | 2 | 3)[] = [1, 2, 3];
  const out: SweepResult[] = [];
  for (const m of modes) {
    for (const a of levels) {
      const r = await sweep({ task, mode: m, accuracy: a });
      out.push(r);
    }
  }
  return out;
}

/**
 * Формує текстовий звіт по sweep (для копіювання в чат / для коміту в код).
 */
export function formatSweepReport(results: SweepResult[]): string {
  const lines: string[] = [];
  lines.push('=== CALIBRATION SWEEP REPORT ===');
  for (const r of results) {
    lines.push('');
    lines.push(`[${r.meta.task} | ${r.meta.mode} | accuracy=${r.meta.accuracy}]  N=${r.sampleSize}`);
    if (r.sampleSize < 5) {
      lines.push('  (sample size < 5 — недостатньо для висновку)');
      continue;
    }
    const b = r.bestF1;
    lines.push(`  best F1 = ${b.f1.toFixed(3)} @ threshold ${b.threshold.toFixed(2)} (P=${b.precision.toFixed(2)}, R=${b.recall.toFixed(2)}, TP=${b.tp}, FP=${b.fp}, FN=${b.fn})`);
    if (r.bestPrecisionGivenRecall) {
      const p = r.bestPrecisionGivenRecall;
      lines.push(`  best precision (R≥${0.7}) = ${p.precision.toFixed(3)} @ threshold ${p.threshold.toFixed(2)}`);
    }
  }
  return lines.join('\n');
}
