/**
 * Orchestrator аналізу коментарів під постом.
 *
 * Послідовність:
 *   1. parseTelegramUrl(input)
 *   2. fetchPostAndComments(ref)  — з прогресом
 *   3. classifyStance для кожного коментаря — з прогресом
 *   4. порахувати відсотки + зберегти звіт
 */

import {
  parseTelegramUrl,
  fetchPostAndComments,
  type RawComment
} from '../telegram';
import { getAiRouter } from '../ai';
import { requireVault } from '../storage/current-vault';
import { addEntry as addLabelEntry, isLabellingEnabled } from '../calibration';
import type {
  StanceReport,
  ClassifiedComment,
  Stance,
  AiMode
} from '../../types';

export interface AnalysisProgress {
  phase: 'parsing' | 'fetching-post' | 'fetching-comments' | 'classifying' | 'done';
  fetchedComments?: number;
  classifiedComments?: number;
  totalComments?: number;
}

export interface AnalyzePostOptions {
  url: string;
  /** Викликається з прогресом для UI */
  onProgress?: (p: AnalysisProgress) => void;
  /** Для скасування */
  signal?: AbortSignal;
}

export async function analyzePost(opts: AnalyzePostOptions): Promise<StanceReport> {
  const { url, onProgress, signal } = opts;

  onProgress?.({ phase: 'parsing' });
  const ref = parseTelegramUrl(url);
  if (!ref) throw new Error('Не вдалося розпарсити посилання');

  onProgress?.({ phase: 'fetching-post' });
  const bundle = await fetchPostAndComments(
    ref,
    (p) => onProgress?.({ phase: 'fetching-comments', fetchedComments: p.fetched }),
    signal
  );

  if (signal?.aborted) throw new Error('Скасовано');

  // Класифікація
  const router = await getAiRouter();
  await router.preload();

  const classified: ClassifiedComment[] = [];
  const total = bundle.comments.length;

  const accuracyLvl = (await requireVault().settings.get().catch(() => null))?.accuracy ?? 2;

  for (let i = 0; i < bundle.comments.length; i++) {
    if (signal?.aborted) break;
    const c = bundle.comments[i];
    try {
      const r = await router.classifyStance(bundle.postText, c.text);
      classified.push(mapToClassified(c, r.stance, r.scores));

      // Labelling: лог stance-рішення (для калібровки stanceEnsemble/recheck)
      if (isLabellingEnabled()) {
        try {
          await addLabelEntry({
            task: 'stance',
            mode: router.effectiveMode,
            accuracy: accuracyLvl as 1 | 2 | 3,
            threshold: 0, // stance — поріг неоднозначності закодований у profile.stanceRecheck
            text: c.text.slice(0, 800),
            postText: bundle.postText.slice(0, 400),
            score: Math.max(r.scores.support, r.scores.oppose, r.scores.unrelated),
            scores: r.scores,
            modelDecision: r.stance,
            channelId: String(c.id),
            messageId: c.id,
            url: opts.url
          });
        } catch (err) {
          // eslint-disable-next-line no-console
          console.warn('[labelling] stance addEntry failed:', err);
        }
      }
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn('[analyze] stance failed for comment', c.id, err);
      classified.push(mapToClassified(c, 'unrelated', { support: 0, oppose: 0, unrelated: 1 }));
    }
    if ((i + 1) % 5 === 0 || i === bundle.comments.length - 1) {
      onProgress?.({ phase: 'classifying', classifiedComments: i + 1, totalComments: total });
    }
  }

  const percentages = computePercentages(classified);
  const aiMode: AiMode = router.effectiveMode;

  const report: StanceReport = {
    postUrl: url,
    postText: bundle.postText,
    totalComments: classified.length,
    comments: classified,
    percentages,
    analyzedAt: Date.now(),
    aiMode
  };

  // Зберегти
  try {
    await requireVault().reports.save(report);
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn('[analyze] save report failed:', err);
  }

  onProgress?.({ phase: 'done', classifiedComments: classified.length, totalComments: total });
  return report;
}

function mapToClassified(
  raw: RawComment,
  stance: Stance,
  scores: { support: number; oppose: number; unrelated: number }
): ClassifiedComment {
  return {
    id: raw.id,
    authorId: raw.authorId,
    authorName: raw.authorName,
    text: raw.text,
    postedAt: raw.postedAt,
    stance,
    scores
  };
}

function computePercentages(items: ClassifiedComment[]): StanceReport['percentages'] {
  if (items.length === 0) return { support: 0, oppose: 0, unrelated: 0 };
  let s = 0, o = 0, u = 0;
  for (const c of items) {
    if (c.stance === 'support')   s++;
    else if (c.stance === 'oppose')  o++;
    else                              u++;
  }
  const total = items.length;
  // Метод найбільшого залишку — щоб сума завжди давала рівно 100%.
  const raw = [
    { key: 'support'   as const, exact: (s / total) * 100 },
    { key: 'oppose'    as const, exact: (o / total) * 100 },
    { key: 'unrelated' as const, exact: (u / total) * 100 }
  ];
  const result = { support: 0, oppose: 0, unrelated: 0 };
  for (const r of raw) result[r.key] = Math.floor(r.exact);
  const remainder = 100 - (result.support + result.oppose + result.unrelated);
  const byFraction = [...raw].sort(
    (a, b) => (b.exact - Math.floor(b.exact)) - (a.exact - Math.floor(a.exact))
  );
  for (let i = 0; i < remainder; i++) result[byFraction[i % 3].key]++;
  return result;
}

/** Допоміжне — побудувати HTML-звіт для експорту. */
export function buildHtmlReport(report: StanceReport): string {
  const date = new Date(report.analyzedAt).toLocaleString('uk-UA');
  const stanceLabels = { support: 'Підтримує', oppose: 'Не підтримує', unrelated: 'Інше' } as const;
  const esc = (s: string) => s.replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch] as string));

  const rows = report.comments.map((c, i) => `
    <tr>
      <td style="color:#666;">${i + 1}</td>
      <td><span style="color:${stanceColor(c.stance)}; font-weight:600;">${stanceLabels[c.stance]}</span></td>
      <td>${esc(c.authorName ?? '—')}</td>
      <td>${esc(c.text)}</td>
    </tr>
  `).join('');

  return `<!doctype html>
<html lang="uk"><head>
  <meta charset="utf-8" />
  <title>Veles Monitor — звіт аналізу коментарів</title>
  <style>
    body { font-family: system-ui, sans-serif; max-width: 980px; margin: 32px auto; padding: 0 16px; color: #111; }
    h1 { font-size: 22px; }
    .meta { color: #555; font-size: 14px; margin-bottom: 20px; }
    .bar { display: flex; height: 36px; border-radius: 4px; overflow: hidden; margin: 16px 0; }
    .bar > div { display: flex; align-items: center; justify-content: center; color: #fff; font-weight: 600; font-size: 13px; min-width: 4%; }
    table { width: 100%; border-collapse: collapse; margin-top: 24px; font-size: 13px; }
    th, td { padding: 8px 10px; border-bottom: 1px solid #eee; text-align: left; vertical-align: top; }
    th { background: #f6f6f6; font-weight: 600; }
    .post { background: #f6f6f6; border-left: 3px solid #38BDF8; padding: 12px; margin-bottom: 20px; white-space: pre-wrap; }
  </style>
</head><body>
  <h1>Аналіз коментарів</h1>
  <div class="meta">
    <div><strong>Пост:</strong> <a href="${esc(report.postUrl)}">${esc(report.postUrl)}</a></div>
    <div><strong>Проаналізовано коментарів:</strong> ${report.totalComments}</div>
    <div><strong>Дата:</strong> ${date}</div>
    <div><strong>AI режим:</strong> ${report.aiMode}</div>
  </div>
  <div class="post">${esc(report.postText)}</div>
  <h2>Розподіл</h2>
  <div class="bar">
    <div style="width:${report.percentages.support}%; background:#34D399;">Підтримує ${report.percentages.support}%</div>
    <div style="width:${report.percentages.oppose}%; background:#F87171;">Не підтримує ${report.percentages.oppose}%</div>
    <div style="width:${report.percentages.unrelated}%; background:#9AB0C8;">Інше ${report.percentages.unrelated}%</div>
  </div>
  <h2>Деталі (${report.comments.length})</h2>
  <table>
    <thead><tr><th>#</th><th>Категорія</th><th>Автор</th><th>Коментар</th></tr></thead>
    <tbody>${rows}</tbody>
  </table>
  <p style="color:#888; margin-top:32px; font-size:12px;">Згенеровано Veles Monitor Web</p>
</body></html>`;
}

function stanceColor(s: Stance): string {
  return s === 'support' ? '#1B8F5B' : s === 'oppose' ? '#C4504F' : '#5B6E83';
}
