/**
 * Сторінка налаштувань. Чотири секції:
 *   1. Акаунт (logout, інфа про юзера, канали)
 *   2. ШІ-режим + завантаження Qwen
 *   3. Сповіщення (browser permission + favicon badge)
 *   4. Дані (медіа-папка, очищення, розмір сховища)
 */

import { html, raw, mount } from '../shared/dom';
import { icons } from '../shared/icons';
import { toast } from '../shared/toast';
import { confirm } from '../shared/modal';
import { strings } from '../../i18n/uk';
import { requireVault } from '../../core/storage/current-vault';
import { wipeVault } from '../../core/storage/vault';
import { logout, getMe } from '../../core/telegram';
import { loadQwen, QWEN_MODEL_ID, checkWebGpu, resetAiRouter } from '../../core/ai';
import { isSupported as fsSupported, pickFolder, getSavedFolder, forgetFolder } from '../../core/storage/filesystem';
import type { AppSettings } from '../../types';

export function buildSettingsPage(): HTMLElement {
  injectStyles();

  const root = html`
    <section class="page" id="page-settings" role="tabpanel">
      <header class="page-header">
        <div>
          <div class="page-eyebrow">${strings.settings.eyebrow}</div>
          <h1 class="page-title">${strings.settings.pageTitle}</h1>
        </div>
      </header>

      <div class="vm-settings-grid">
        <section class="panel" data-vm-section="account"></section>
        <section class="panel" data-vm-section="ai"></section>
        <section class="panel" data-vm-section="notifications"></section>
        <section class="panel" data-vm-section="data"></section>
      </div>
    </section>
  `;

  void renderAll(root);
  return root;
}

async function renderAll(root: HTMLElement): Promise<void> {
  const vault = requireVault();
  const settings = await vault.settings.get();

  mount(root.querySelector<HTMLElement>('[data-vm-section="account"]')!, await renderAccount(vault, settings));
  mount(root.querySelector<HTMLElement>('[data-vm-section="ai"]')!,      await renderAi(vault, settings, () => renderAll(root)));
  mount(root.querySelector<HTMLElement>('[data-vm-section="notifications"]')!, renderNotifications(vault, settings));
  mount(root.querySelector<HTMLElement>('[data-vm-section="data"]')!,   await renderData());
}

// ───────────────────────  Section: ACCOUNT  ──────────────────────────────
async function renderAccount(
  vault: ReturnType<typeof requireVault>,
  _settings: AppSettings
): Promise<HTMLElement> {
  const channels = await vault.channels.list().catch(() => []);
  const me = await getMe().catch(() => null);
  const userName = me ? [me.firstName, me.lastName].filter(Boolean).join(' ') || me.username || '—' : '—';

  const el = html`
    <div>
      <div class="vm-section-head">
        <div>
          <div class="text-eyebrow">Акаунт Telegram</div>
          <h3>${userName}</h3>
        </div>
        <span style="color: var(--accent);">${raw(icons.user(24).value)}</span>
      </div>

      <div class="vm-kv">
        <span>Телефон</span><span class="text-mono">${me?.phone ?? '—'}</span>
        <span>Username</span><span class="text-mono">${me?.username ? '@' + me.username : '—'}</span>
        <span>Каналів моніторингу</span><span class="text-mono text-accent">${channels.length}</span>
      </div>

      <div class="row gap-2" style="margin-top: 16px;">
        <button class="btn btn-secondary" data-vm-relogin>
          ${raw(icons.refresh(14).value)}
          <span>Перевибрати канали</span>
        </button>
        <button class="btn btn-danger" data-vm-logout>
          ${raw(icons.logout(14).value)}
          <span>Logout</span>
        </button>
      </div>
    </div>
  `;

  el.querySelector('[data-vm-logout]')?.addEventListener('click', async () => {
    const ok = await confirm({
      title: 'Вийти з акаунту?',
      body: 'Telegram-сесія, api_id/api_hash і список обраних каналів будуть видалені. Налаштування і історія залишаться. Доведеться пройти onboarding заново.',
      danger: true,
      confirmLabel: 'Так, вийти'
    });
    if (!ok) return;
    try {
      await logout();
      await vault.channels.setMany([]);
      toast.success('Вийшли з акаунту');
      // перезавантажуємо застосунок щоб запустився onboarding-флоу
      setTimeout(() => location.reload(), 500);
    } catch (err) {
      toast.error((err as Error).message);
    }
  });

  el.querySelector('[data-vm-relogin]')?.addEventListener('click', () => {
    toast.info('Re-вибір каналів — фіча Phase 10');
  });

  return el;
}

// ───────────────────────  Section: AI  ───────────────────────────────────
async function renderAi(
  vault: ReturnType<typeof requireVault>,
  settings: AppSettings,
  rerender: () => void
): Promise<HTMLElement> {
  const gpu = await checkWebGpu();

  const el = html`
    <div>
      <div class="vm-section-head">
        <div>
          <div class="text-eyebrow">Режим ШІ</div>
          <h3>${settings.aiMode === 'qwen' ? 'Qwen 2.5 (experimental)' : 'Hybrid'}</h3>
        </div>
        <span style="color: var(--accent);">${raw(icons.brain(24).value)}</span>
      </div>

      <div class="vm-ai-options">
        <label class="vm-ai-option ${settings.aiMode === 'hybrid' ? 'selected' : ''}">
          <input type="radio" name="vm-ai" value="hybrid" ${settings.aiMode === 'hybrid' ? 'checked' : ''} />
          <div>
            <div class="vm-ai-title">Hybrid</div>
            <div class="vm-ai-sub">e5-small + mDeBERTa-NLI · ~400 МБ · CPU</div>
          </div>
        </label>
        <label class="vm-ai-option ${settings.aiMode === 'qwen' ? 'selected' : ''} ${gpu.available ? '' : 'disabled'}">
          <input type="radio" name="vm-ai" value="qwen" ${settings.aiMode === 'qwen' ? 'checked' : ''} ${gpu.available ? '' : 'disabled'} />
          <div>
            <div class="vm-ai-title">
              Qwen 2.5-1.5B
              <span class="badge badge-warning" style="margin-left: 6px;">experimental</span>
            </div>
            <div class="vm-ai-sub">~1 ГБ · потребує WebGPU</div>
          </div>
        </label>
      </div>

      <div class="vm-gpu-info">
        <div class="row gap-2">
          <span class="led ${gpu.available ? 'led-success' : 'led-danger'}" style="width: 10px; height: 10px;"></span>
          <span class="text-mono" style="font-size: var(--fs-xs); letter-spacing: var(--tracking-wide); text-transform: uppercase;">
            WebGPU: ${gpu.available ? 'доступний' : 'недоступний'}
          </span>
          ${gpu.adapter ? raw(`<span class="text-muted" style="font-size: var(--fs-xs);">· ${gpu.adapter.vendor} ${gpu.adapter.description ?? ''}</span>`) : ''}
        </div>
        ${!gpu.available
          ? raw(`<div class="text-muted" style="font-size: var(--fs-xs); margin-top: 4px;">${gpu.reason ?? ''} · <a href="https://webgpureport.org/" target="_blank" rel="noreferrer">перевірити</a></div>`)
          : ''
        }
      </div>

      ${settings.aiMode === 'qwen' && gpu.available
        ? raw(`<div class="row gap-2" style="margin-top: 16px;">
            <button class="btn btn-secondary" data-vm-download-qwen>
              ${icons.download(14).value}
              <span>Завантажити / переперевірити Qwen</span>
            </button>
          </div>`)
        : ''
      }
    </div>
  `;

  el.querySelectorAll<HTMLInputElement>('input[name="vm-ai"]').forEach(r => {
    r.addEventListener('change', async () => {
      if (!r.checked) return;
      const newMode = r.value as 'hybrid' | 'qwen';
      if (newMode === 'qwen' && !gpu.available) {
        toast.warning('WebGPU недоступний — Qwen вибрати не можна');
        r.checked = false;
        return;
      }
      await vault.settings.update({ aiMode: newMode });
      resetAiRouter();
      toast.success(`Активний режим: ${newMode === 'qwen' ? 'Qwen' : 'Hybrid'}`);
      rerender();
    });
  });

  el.querySelector('[data-vm-download-qwen]')?.addEventListener('click', async () => {
    const ok = await confirm({
      title: 'Завантажити Qwen 2.5?',
      body: 'Це одноразове завантаження ~1 ГБ у кеш браузера. Подальші запуски будуть миттєвими.',
      confirmLabel: 'Завантажити'
    });
    if (!ok) return;

    let progressEl: HTMLElement | null = null;
    try {
      const wrap = document.createElement('div');
      wrap.className = 'panel';
      wrap.style.marginTop = '12px';
      el.appendChild(wrap);
      progressEl = wrap;

      const update = (pct: number, text: string) => {
        wrap.innerHTML = `
          <div class="text-eyebrow" style="margin-bottom: 8px;">Завантаження Qwen</div>
          <div class="text-secondary" style="font-size: var(--fs-sm); margin-bottom: 8px;">${text}</div>
          <div class="vm-progressbar"><div class="vm-progressbar-fill" style="width: ${pct}%;"></div></div>
        `;
      };
      update(0, 'Підготовка…');

      await loadQwen((p) => {
        update(p.progress ?? 0, p.file ?? p.status);
      });
      update(100, 'Готово');
      toast.success(`${QWEN_MODEL_ID} завантажено`);
    } catch (err) {
      toast.error(`Не вдалося: ${(err as Error).message}`);
      progressEl?.remove();
    }
  });

  return el;
}

// ───────────────────────  Section: NOTIFICATIONS  ────────────────────────
function renderNotifications(
  vault: ReturnType<typeof requireVault>,
  settings: AppSettings
): HTMLElement {
  const permission: NotificationPermission = typeof Notification !== 'undefined' ? Notification.permission : 'denied';
  const browserStatus = permission === 'granted' ? 'success' : permission === 'denied' ? 'danger' : 'warning';

  const el = html`
    <div>
      <div class="vm-section-head">
        <div>
          <div class="text-eyebrow">Сповіщення</div>
          <h3>Push + Badge</h3>
        </div>
        <span style="color: var(--accent);">${raw(icons.bell(24).value)}</span>
      </div>

      <div class="col gap-3" style="margin-top: 12px;">
        <div class="vm-toggle-row">
          <div>
            <div>Системні нотифікації браузера</div>
            <div class="text-muted" style="font-size: var(--fs-xs);">
              Статус: <span class="text-${browserStatus}">${permission}</span>
            </div>
          </div>
          <label class="vm-switch">
            <input type="checkbox" data-vm-browser ${settings.notifications.browser ? 'checked' : ''} />
            <span class="vm-switch-track"><span class="vm-switch-thumb"></span></span>
          </label>
        </div>

        <div class="vm-toggle-row">
          <div>
            <div>Лічильник у favicon / title</div>
            <div class="text-muted" style="font-size: var(--fs-xs);">Кількість нових збігів</div>
          </div>
          <label class="vm-switch">
            <input type="checkbox" data-vm-favicon ${settings.notifications.faviconBadge ? 'checked' : ''} />
            <span class="vm-switch-track"><span class="vm-switch-thumb"></span></span>
          </label>
        </div>

        ${permission !== 'granted' ? raw(`
          <button class="btn btn-secondary btn-sm" data-vm-request-permission style="align-self: flex-start;">
            <span>Запитати дозвіл браузера</span>
          </button>
        `) : ''}
      </div>
    </div>
  `;

  el.querySelector<HTMLInputElement>('[data-vm-browser]')?.addEventListener('change', async (e) => {
    const on = (e.target as HTMLInputElement).checked;
    await vault.settings.update({ notifications: { ...settings.notifications, browser: on } });
    toast.success(strings.toast.settingsSaved);
  });
  el.querySelector<HTMLInputElement>('[data-vm-favicon]')?.addEventListener('change', async (e) => {
    const on = (e.target as HTMLInputElement).checked;
    await vault.settings.update({ notifications: { ...settings.notifications, faviconBadge: on } });
    toast.success(strings.toast.settingsSaved);
  });
  el.querySelector('[data-vm-request-permission]')?.addEventListener('click', async () => {
    try {
      const result = await Notification.requestPermission();
      toast.info(`Permission: ${result}`);
      setTimeout(() => location.reload(), 600);
    } catch (err) {
      toast.error((err as Error).message);
    }
  });

  return el;
}

// ───────────────────────  Section: DATA  ─────────────────────────────────
async function renderData(): Promise<HTMLElement> {
  let storageInfo = '—';
  try {
    if (navigator.storage?.estimate) {
      const est = await navigator.storage.estimate();
      const used = (est.usage ?? 0) / (1024 * 1024);
      const quota = (est.quota ?? 0) / (1024 * 1024);
      storageInfo = `${used.toFixed(1)} МБ з ${quota.toFixed(0)} МБ`;
    }
  } catch { /* ignore */ }

  const folderHandle = await getSavedFolder().catch(() => null);
  const folderLabel = folderHandle ? (folderHandle.name ?? 'обрано') : 'не задано';

  const el = html`
    <div>
      <div class="vm-section-head">
        <div>
          <div class="text-eyebrow">Дані</div>
          <h3>Зберігання та папки</h3>
        </div>
        <span style="color: var(--accent);">${raw(icons.folder(24).value)}</span>
      </div>

      <div class="vm-kv">
        <span>Зайнято в браузері</span><span class="text-mono">${storageInfo}</span>
        <span>Папка для медіа</span><span class="text-mono ${folderHandle ? 'text-accent' : 'text-muted'}">${folderLabel}</span>
        <span>File System API</span><span class="text-mono ${fsSupported() ? 'text-success' : 'text-warning'}">${fsSupported() ? 'доступний' : 'недоступний (буде fallback на завантаження)'}</span>
      </div>

      <div class="row gap-2" style="margin-top: 16px; flex-wrap: wrap;">
        ${fsSupported() ? raw(`
          <button class="btn btn-secondary" data-vm-pick-folder>
            ${icons.folder(14).value}
            <span>${folderHandle ? 'Змінити папку медіа' : 'Обрати папку медіа'}</span>
          </button>
          ${folderHandle ? `<button class="btn btn-ghost" data-vm-forget-folder>${icons.x(14).value}<span>Забути папку</span></button>` : ''}
        `) : ''}
        <button class="btn btn-secondary" data-vm-clear-history>
          ${raw(icons.trash(14).value)}
          <span>Очистити історію знахідок</span>
        </button>
        <button class="btn btn-secondary" data-vm-clear-reports>
          ${raw(icons.trash(14).value)}
          <span>Очистити збережені звіти</span>
        </button>
        <button class="btn btn-danger" data-vm-wipe-all>
          ${raw(icons.alert(14).value)}
          <span>Видалити ВСЕ і пройти onboarding заново</span>
        </button>
      </div>
    </div>
  `;

  el.querySelector('[data-vm-pick-folder]')?.addEventListener('click', async () => {
    try {
      const h = await pickFolder();
      if (h) {
        toast.success(`Обрано папку: ${h.name ?? '—'}`);
        await requireVault().settings.update({ media: { folderHandleSaved: true } });
      }
    } catch (err) {
      toast.error((err as Error).message);
    }
  });
  el.querySelector('[data-vm-forget-folder]')?.addEventListener('click', async () => {
    await forgetFolder();
    await requireVault().settings.update({ media: { folderHandleSaved: false } });
    toast.success('Папку забуто');
  });

  el.querySelector('[data-vm-clear-history]')?.addEventListener('click', async () => {
    const ok = await confirm({ title: 'Очистити історію?', body: 'Видалити всі збережені знайдені публікації?', confirmLabel: 'Так', danger: true });
    if (!ok) return;
    try {
      await requireVault().history.clear();
      toast.success('Історію видалено');
    } catch (err) { toast.error((err as Error).message); }
  });

  el.querySelector('[data-vm-clear-reports]')?.addEventListener('click', async () => {
    const ok = await confirm({ title: 'Очистити звіти?', body: 'Видалити всі збережені звіти аналізу коментарів?', confirmLabel: 'Так', danger: true });
    if (!ok) return;
    try {
      await requireVault().reports.clear();
      toast.success('Звіти видалено');
    } catch (err) { toast.error((err as Error).message); }
  });

  el.querySelector('[data-vm-wipe-all]')?.addEventListener('click', async () => {
    const ok = await confirm({
      title: 'Видалити ВСІ дані?',
      body: 'Vault, налаштування, історія, звіти, сесія Telegram — все буде стерто. Доведеться пройти onboarding з нуля.',
      confirmLabel: 'Так, видалити',
      danger: true
    });
    if (!ok) return;
    try {
      await wipeVault();
      toast.success('Очищено');
      setTimeout(() => location.reload(), 500);
    } catch (err) { toast.error((err as Error).message); }
  });

  return el;
}

// ───────────────────────  styles  ──────────────────────────────────────
let stylesInjected = false;
function injectStyles(): void {
  if (stylesInjected) return;
  stylesInjected = true;
  const s = document.createElement('style');
  s.textContent = `
    .vm-settings-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: var(--space-4);
    }
    @media (max-width: 900px) {
      .vm-settings-grid { grid-template-columns: 1fr; }
    }

    .vm-section-head {
      display: flex; align-items: flex-start; justify-content: space-between;
      gap: var(--space-3);
      margin-bottom: 16px;
    }
    .vm-section-head h3 { margin: 4px 0 0; font-size: var(--fs-lg); }

    .vm-kv {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 6px 16px;
      font-size: var(--fs-sm);
    }
    .vm-kv > span:nth-child(odd) { color: var(--fg-muted); }

    .vm-ai-options {
      display: flex; flex-direction: column; gap: 8px;
      margin-bottom: 12px;
    }
    .vm-ai-option {
      display: flex; align-items: center; gap: 12px;
      padding: 12px;
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-sm);
      cursor: pointer;
      transition: all var(--t-fast);
    }
    .vm-ai-option:hover { background: var(--bg-elevated); }
    .vm-ai-option.selected {
      border-color: var(--accent);
      background: var(--accent-soft);
    }
    .vm-ai-option.disabled {
      opacity: 0.5; cursor: not-allowed;
    }
    .vm-ai-title { font-weight: 600; }
    .vm-ai-sub {
      font-family: var(--font-mono);
      font-size: var(--fs-xs);
      color: var(--fg-muted);
      letter-spacing: var(--tracking-wide);
    }
    .vm-ai-option input { margin: 0; }

    .vm-gpu-info {
      padding: 8px 12px;
      background: var(--bg-base);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-sm);
    }

    .vm-toggle-row {
      display: flex; align-items: center; justify-content: space-between;
      gap: 12px;
      padding: 8px 0;
    }

    .vm-switch {
      position: relative;
      width: 40px; height: 22px;
      flex-shrink: 0;
    }
    .vm-switch input { position: absolute; opacity: 0; pointer-events: none; }
    .vm-switch-track {
      position: absolute; inset: 0;
      background: var(--bg-elevated);
      border: 1px solid var(--border-base);
      border-radius: var(--radius-pill);
      cursor: pointer;
      transition: background var(--t-fast), border-color var(--t-fast);
    }
    .vm-switch-thumb {
      position: absolute;
      top: 2px; left: 2px;
      width: 16px; height: 16px;
      background: var(--fg-muted);
      border-radius: 50%;
      transition: left var(--t-fast), background var(--t-fast);
    }
    .vm-switch input:checked ~ .vm-switch-track {
      background: var(--accent-soft);
      border-color: var(--accent);
    }
    .vm-switch input:checked ~ .vm-switch-track .vm-switch-thumb {
      left: 20px;
      background: var(--accent);
    }
  `;
  document.head.appendChild(s);
}
