/**
 * Topic / Word matching для режиму моніторингу.
 *
 *   Mode A («Співпадіння слів з відмінюванням») — embedding-based:
 *     - беремо унікальні слова з тексту, embed-имо
 *     - embed-имо кожне ключове слово
 *     - для кожного ключового слова: max cosine між ним і словами тексту
 *     - збіг = score >= threshold (за замовчуванням 0.78)
 *
 *   Mode B («Тема») — NLI zero-shot:
 *     - premise = весь текст (з чанкінгом для довгих)
 *     - hypothesis = 'Цей текст про {topic}.'
 *     - збіг = score >= threshold (за замовчуванням 0.6)
 */

import { cleanText, chunkText, extractUniqueWords } from '../text-utils';
import { loadEmbeddings, cosineSimilarity, type EmbeddingsApi } from './embeddings';
import { loadNli, type NliApi } from './nli';
import type { ProgressCallback } from '../progress';
import { getActiveProfile, type AccuracyProfile } from '../accuracy';

// Категорії-конкуренти для softmax-класифікації теми.
//
// CALIBRATION NOTE (Jun 9): спершу розширили з 4 до 8 в надії краще покривати
// FP-патерни. Виміряли на реальних даних — softmax по 9 мітках дав середній
// score 0.10 (≈ 1/N), пороги 0.30-0.34 стали недосяжними, 0 матчів з 50.
//
// Повертаємо до 4-х "буденних" категорій, які зберігають softmax-мас на
// топ-мітці. Додаємо ОДНУ політичну категорію — найбільш частий FP-патерн
// "нейтральні новини про дії влади". 5 контрастів дають баланс: достатньо
// конкуренції, але softmax не розмазується.
const CONTRAST_LABELS = [
  'повсякденні новини, побут і життя міста',
  'розваги, спорт, дозвілля, їжа',
  'реклама, акції та оголошення',
  'погода, дороги і транспорт',
  'нейтральні новини про дії влади або офіційні події'
];

export interface WordsMatchResult {
  matched: boolean;
  maxScore: number;
  perKeyword: { keyword: string; score: number; matchedWord?: string }[];
}

export interface TopicMatchResult {
  matched: boolean;
  score: number;
  /** Score по кожному чанку — для дебагу */
  chunkScores: number[];
}

/**
 * Mode A — embedding-based word/keyword matching з толерантністю до відмінювання.
 */
export async function matchByWords(
  rawText: string,
  keywords: string[],
  threshold?: number,
  requireAll = false,
  embeddings?: EmbeddingsApi,
  onProgress?: ProgressCallback,
  profile: AccuracyProfile = getActiveProfile()
): Promise<WordsMatchResult> {
  const th = threshold ?? profile.wordsThreshold;
  const text = cleanText(rawText);
  if (!text || keywords.length === 0) {
    return { matched: false, maxScore: 0, perKeyword: [] };
  }
  const emb = embeddings ?? await loadEmbeddings(onProgress);

  const textWords = extractUniqueWords(text, 3);
  if (textWords.length === 0) {
    return { matched: false, maxScore: 0, perKeyword: [] };
  }

  // Embed-имо слова тексту + ключові слова разом, щоб не дьоргати модель двічі
  const allInputs = [...textWords, ...keywords.map(k => k.toLowerCase().trim()).filter(Boolean)];
  const allVecs = await emb.embed(allInputs);
  const textVecs = allVecs.slice(0, textWords.length);
  const kwVecs   = allVecs.slice(textWords.length);

  const perKeyword: WordsMatchResult['perKeyword'] = [];
  let maxScore = 0;

  for (let i = 0; i < keywords.length; i++) {
    const kw = keywords[i];
    const kwVec = kwVecs[i];
    let bestScore = -1;
    let bestWord: string | undefined;
    for (let j = 0; j < textWords.length; j++) {
      const s = cosineSimilarity(kwVec, textVecs[j]);
      if (s > bestScore) { bestScore = s; bestWord = textWords[j]; }
    }
    perKeyword.push({ keyword: kw, score: bestScore, matchedWord: bestWord });
    if (bestScore > maxScore) maxScore = bestScore;
  }

  const passes = perKeyword.map(p => p.score >= th);
  const matched = requireAll ? passes.every(Boolean) : passes.some(Boolean);
  return { matched, maxScore, perKeyword };
}

/**
 * Mode B — NLI zero-shot topic match.
 *
 * Враховує всі параметри AccuracyProfile:
 *   - topicChunkSize / topicMaxChunks — чанкінг тексту
 *   - topicEnsemble — додатковий прохід з альтернативним формулюванням гіпотези
 *   - topicRecheck — контрольна перевірка з "інверсним" формулюванням
 *
 * Ensemble + recheck активуються в режимі "Максимальна точність" і додатково
 * валідують неоднозначні випадки, ціною ~2-3x проходів NLI на чанк.
 */
const HYPOTHESIS_TEMPLATES = [
  'Ця публікація про {}.',
  'Цей текст стосується теми «{}».'
];

export async function matchByTopic(
  rawText: string,
  topic: string,
  threshold?: number,
  nli?: NliApi,
  onProgress?: ProgressCallback,
  profile: AccuracyProfile = getActiveProfile()
): Promise<TopicMatchResult> {
  const text = cleanText(rawText);
  if (!text || !topic.trim()) {
    return { matched: false, score: 0, chunkScores: [] };
  }
  const model = nli ?? await loadNli(onProgress);
  const th = threshold ?? profile.topicThreshold;

  // Софтмакс-конкуренція (multiLabel: false): тема змагається з кількома
  // конкурентами. Якщо текст про щось буденне/нейтральне — ймовірність
  // забирає конкурент, а не тема. Це прибирає компресію балів, коли одиночна
  // гіпотеза слабо відрізняла релевантне від нерелевантного.
  const labels = [topic, ...CONTRAST_LABELS];
  const chunks = chunkText(text, profile.topicChunkSize).slice(0, profile.topicMaxChunks);

  const templates = profile.topicEnsemble ? HYPOTHESIS_TEMPLATES : [HYPOTHESIS_TEMPLATES[0]];

  const chunkScores: number[] = [];
  for (const chunk of chunks) {
    // Ensemble — усереднюємо за кількома формулюваннями гіпотези
    let sumScore = 0;
    for (const tmpl of templates) {
      const res = await model.classify(chunk, labels, {
        hypothesisTemplate: tmpl,
        multiLabel: false
      });
      const i = res.labels.findIndex(l => l === topic);
      sumScore += i >= 0 ? res.scores[i] : 0;
    }
    chunkScores.push(sumScore / templates.length);
  }

  let score = chunkScores.length ? Math.max(...chunkScores) : 0;

  // Recheck — контроль через "інверсне" формулювання. Якщо інверсний score
  // вищий за прямий, тема НЕ підтверджена. Зменшує FP при граничних балах.
  if (profile.topicRecheck && score >= th && chunks.length > 0) {
    const bestChunk = chunks[chunkScores.indexOf(score)];
    const inverseRes = await model.classify(bestChunk, labels, {
      hypothesisTemplate: 'Цей текст НЕ стосується теми «{}».',
      multiLabel: false
    });
    const i = inverseRes.labels.findIndex(l => l === topic);
    const inverseScore = i >= 0 ? inverseRes.scores[i] : 0;
    // Якщо інверсна гіпотеза перемагає — знижуємо ефективний score.
    if (inverseScore > score) {
      score = Math.min(score, 1 - inverseScore);
    }
  }

  return { matched: score >= th, score, chunkScores };
}

/**
 * Pre-filter: чи варто взагалі рахувати NLI?
 * Швидке embedding-порівняння тексту з темою. Якщо повністю не пов'язано — false.
 * Використовується в throttle-mode 'prefilter'.
 */
export async function quickTopicPrefilter(
  rawText: string,
  topic: string,
  cosineThreshold = 0.35,
  embeddings?: EmbeddingsApi
): Promise<{ passes: boolean; cosine: number }> {
  const text = cleanText(rawText);
  if (!text || !topic) return { passes: false, cosine: 0 };
  const emb = embeddings ?? await loadEmbeddings();
  const [textVec, topicVec] = await emb.embed([text.slice(0, 1000), topic]);
  const c = cosineSimilarity(textVec, topicVec);
  return { passes: c >= cosineThreshold, cosine: c };
}
