/**
 * Перевірка наявності та готовності WebGPU.
 * Кешуємо результат, щоб не дьоргати API багато разів.
 */

export interface WebGpuInfo {
  available: boolean;
  reason?: string;
  adapter?: {
    vendor: string;
    architecture?: string;
    description?: string;
  };
}

let cached: WebGpuInfo | null = null;
let inflightCheck: Promise<WebGpuInfo> | null = null;

export async function checkWebGpu(): Promise<WebGpuInfo> {
  if (cached) return cached;
  if (inflightCheck) return inflightCheck;

  inflightCheck = (async (): Promise<WebGpuInfo> => {
    if (typeof navigator === 'undefined' || !('gpu' in navigator)) {
      cached = { available: false, reason: 'navigator.gpu відсутній — браузер не підтримує WebGPU' };
      return cached;
    }
    try {
      const adapter = await (navigator as any).gpu.requestAdapter();
      if (!adapter) {
        cached = { available: false, reason: 'GPU адаптер недоступний (можливо, відключений в браузері)' };
        return cached;
      }
      const info: any = await adapter.requestAdapterInfo?.().catch(() => null) ?? {};
      cached = {
        available: true,
        adapter: {
          vendor: info.vendor ?? 'unknown',
          architecture: info.architecture,
          description: info.description
        }
      };
      return cached;
    } catch (err) {
      cached = { available: false, reason: `WebGPU помилка: ${(err as Error).message}` };
      return cached;
    } finally {
      inflightCheck = null;
    }
  })();

  return inflightCheck;
}

/**
 * Скинути кеш — корисно після зміни налаштувань браузера.
 */
export function resetWebGpuCheck(): void {
  cached = null;
  inflightCheck = null;
}
