/**
 * Простий toast-нотифікатор.
 *
 * Використання:
 *   toast.info('Готово');
 *   toast.success('Налаштування збережено');
 *   toast.warning('WebGPU недоступний…');
 *   toast.error('Помилка', { duration: 6000 });
 */

import { html, raw } from './dom';
import { icons } from './icons';

type ToastKind = 'info' | 'success' | 'warning' | 'danger';

interface ToastOptions {
  duration?: number;        // ms; 0 = без авто-скриття
}

const DEFAULT_DURATION = 3500;

let containerEl: HTMLElement | null = null;

function ensureContainer(): HTMLElement {
  if (containerEl) return containerEl;
  containerEl = document.createElement('div');
  containerEl.className = 'toast-container';
  document.body.appendChild(containerEl);
  return containerEl;
}

function iconFor(kind: ToastKind) {
  switch (kind) {
    case 'success': return icons.check(16);
    case 'warning': return icons.alert(16);
    case 'danger':  return icons.alert(16);
    default:        return icons.info(16);
  }
}

function show(kind: ToastKind, message: string, opts: ToastOptions = {}): void {
  const container = ensureContainer();
  const node = html`
    <div class="toast toast-${kind}" role="status">
      <span style="color: var(--${kind === 'info' ? 'accent' : kind})">${iconFor(kind)}</span>
      <span style="flex:1;">${message}</span>
      <button class="btn-ghost btn-sm" data-vm-dismiss aria-label="Закрити">
        ${icons.x(14)}
      </button>
    </div>
  `;
  container.appendChild(node);

  const dismiss = (): void => {
    if (!node.isConnected) return;
    node.style.opacity = '0';
    node.style.transform = 'translateY(4px)';
    node.style.transition = 'opacity 160ms, transform 160ms';
    window.setTimeout(() => node.remove(), 200);
  };

  node.querySelector('[data-vm-dismiss]')?.addEventListener('click', dismiss);

  const duration = opts.duration ?? DEFAULT_DURATION;
  if (duration > 0) {
    window.setTimeout(dismiss, duration);
  }
}

export const toast = {
  info:    (msg: string, opts?: ToastOptions) => show('info',    msg, opts),
  success: (msg: string, opts?: ToastOptions) => show('success', msg, opts),
  warning: (msg: string, opts?: ToastOptions) => show('warning', msg, opts),
  error:   (msg: string, opts?: ToastOptions) => show('danger',  msg, opts)
};

// Допоміжне для лінкання — щоб TS не сваривсь за невикористаний raw.
void raw;
