/**
 * STUB onboarding-сторінки. Повноцінний майстер — у Phase 4.
 */

import { html, raw } from '../shared/dom';
import { icons } from '../shared/icons';
import { strings } from '../../i18n/uk';

export interface WelcomeApi {
  el: HTMLElement;
  /** Викликається, коли користувач завершив onboarding. */
  onComplete(handler: () => void): void;
}

export function buildWelcomePage(): WelcomeApi {
  const root = html`
    <div class="app-main">
      <section class="page" style="max-width: 720px;">
        <header class="page-header">
          <div>
            <div class="page-eyebrow">${strings.onboarding.placeholderTitle}</div>
            <h1 class="page-title">${strings.onboarding.welcomeTitle}</h1>
          </div>
        </header>

        <div class="panel">
          <div class="row gap-4" style="align-items: flex-start;">
            <div style="color: var(--accent); flex-shrink: 0;">${raw(icons.shield(28).value)}</div>
            <div>
              <p class="text-secondary" style="margin-bottom: 16px;">${strings.onboarding.welcomeBody}</p>
              <p class="text-muted" style="font-size: var(--fs-sm);">${strings.onboarding.placeholderBody}</p>
            </div>
          </div>
        </div>

        <div class="row end">
          <button class="btn btn-primary" data-vm-start-onboarding>
            ${raw(icons.power(14).value)}
            <span>Підключити Telegram</span>
          </button>
        </div>
      </section>
    </div>
  `;

  const handlers: Array<() => void> = [];
  root.querySelector('[data-vm-start-onboarding]')?.addEventListener('click', () => {
    handlers.forEach(h => h());
  });

  return {
    el: root,
    onComplete(handler) { handlers.push(handler); }
  };
}
