/**
 * AI Router — єдиний інтерфейс для пошуку та класифікації, незалежно від режиму.
 *
 *   Hybrid: e5-small + mDeBERTa-NLI
 *   Qwen:   Qwen2.5-1.5B через WebLLM — fallback на hybrid при відсутності WebGPU
 *           (Mode A / matchByWords завжди йде через embeddings навіть в qwen-режимі,
 *            бо word-matching швидше та якісніше через cosine.)
 *
 * Викликаючий код:
 *
 *   const router = await getAiRouter();
 *   await router.matchByTopic(text, 'дискредитація влади');
 *   await router.classifyStance(post, comment);
 */

import { getVault, onVaultChange } from '../storage/current-vault';
import { checkWebGpu } from './webgpu-check';
import * as hybrid from './hybrid';
import * as qwen from './qwen';
import { setActiveAccuracy } from './accuracy';
import type { AiMode, Stance } from '../../types';
import type { ProgressCallback } from './progress';
import { toast } from '../../ui/shared/toast';
import { strings } from '../../i18n/uk';

export interface AiRouterApi {
  readonly mode: AiMode;
  readonly effectiveMode: AiMode;   // 'qwen' тільки якщо реально доступний WebGPU
  matchByWords(text: string, keywords: string[], opts?: { threshold?: number; requireAll?: boolean }): Promise<hybrid.WordsMatchResult>;
  matchByTopic(text: string, topic: string, opts?: { threshold?: number }): Promise<hybrid.TopicMatchResult>;
  classifyStance(postText: string, commentText: string): Promise<{ stance: Stance; scores: { support: number; oppose: number; unrelated: number } }>;
  preload(onProgress?: ProgressCallback): Promise<void>;
}

let routerInstance: AiRouterApi | null = null;
let routerForMode: AiMode | null = null;

onVaultChange(() => {
  routerInstance = null;
  routerForMode = null;
});

export async function getAiRouter(): Promise<AiRouterApi> {
  const vault = getVault();
  const settings = vault ? await vault.settings.get() : null;
  const mode: AiMode = settings?.aiMode ?? 'hybrid';
  // Активуємо обраний рівень "Точність визначення" — його читають гібридні функції.
  if (settings?.accuracy) setActiveAccuracy(settings.accuracy);

  if (routerInstance && routerForMode === mode) return routerInstance;

  let effective: AiMode = mode;
  if (mode === 'qwen') {
    const gpu = await checkWebGpu();
    if (!gpu.available) {
      effective = 'hybrid';
      toast.warning(strings.toast.webgpuMissing);
    }
  }

  routerForMode = mode;
  routerInstance = effective === 'qwen' ? buildQwenRouter(mode) : buildHybridRouter(mode, effective);
  return routerInstance;
}

// ───────────────────────────  HYBRID router  ──────────────────────────────
function buildHybridRouter(mode: AiMode, effective: AiMode): AiRouterApi {
  let embeddings: hybrid.EmbeddingsApi | null = null;
  let nli: hybrid.NliApi | null = null;

  const ensureEmb = async (cb?: ProgressCallback) => {
    if (!embeddings) embeddings = await hybrid.loadEmbeddings(cb);
    return embeddings;
  };
  const ensureNli = async (cb?: ProgressCallback) => {
    if (!nli) nli = await hybrid.loadNli(cb);
    return nli;
  };

  return {
    mode,
    effectiveMode: effective,

    async matchByWords(text, keywords, opts = {}) {
      const emb = await ensureEmb();
      return hybrid.matchByWords(text, keywords, opts.threshold, opts.requireAll, emb);
    },

    async matchByTopic(text, topic, opts = {}) {
      const model = await ensureNli();
      return hybrid.matchByTopic(text, topic, opts.threshold, model);
    },

    async classifyStance(postText, commentText) {
      const model = await ensureNli();
      const r = await hybrid.classifyStance(postText, commentText, model);
      return { stance: r.stance, scores: r.scores };
    },

    async preload(cb) {
      await Promise.all([ensureEmb(cb), ensureNli(cb)]);
    }
  };
}

// ───────────────────────────  QWEN router  ────────────────────────────────
function buildQwenRouter(mode: AiMode): AiRouterApi {
  // Для word-matching у qwen-режимі все одно використовуємо embeddings (швидше + точніше)
  let embeddings: hybrid.EmbeddingsApi | null = null;
  let qwenEngine: qwen.QwenEngineApi | null = null;

  const ensureEmb = async (cb?: ProgressCallback) => {
    if (!embeddings) embeddings = await hybrid.loadEmbeddings(cb);
    return embeddings;
  };
  const ensureQwen = async (cb?: ProgressCallback) => {
    if (!qwenEngine) qwenEngine = await qwen.loadQwen(cb);
    return qwenEngine;
  };

  return {
    mode,
    effectiveMode: 'qwen',

    async matchByWords(text, keywords, opts = {}) {
      const emb = await ensureEmb();
      return hybrid.matchByWords(text, keywords, opts.threshold, opts.requireAll, emb);
    },

    async matchByTopic(text, topic, opts = {}) {
      const engine = await ensureQwen();
      // НЕ підставляємо 0.55 по дефолту — даємо qwenMatchByTopic вибрати
      // з активного профілю (рівень 1/2/3 → різні пороги).
      return qwen.qwenMatchByTopic(text, topic, opts.threshold, engine);
    },

    async classifyStance(postText, commentText) {
      const engine = await ensureQwen();
      const r = await qwen.qwenClassifyStance(postText, commentText, engine);
      return { stance: r.stance, scores: r.scores };
    },

    async preload(cb) {
      // Тільки Qwen грузимо проактивно; embeddings — за потребою
      await ensureQwen(cb);
    }
  };
}

/**
 * Примусово скинути instance — викликати з UI Settings після зміни режиму.
 */
export function resetAiRouter(): void {
  routerInstance = null;
  routerForMode = null;
}
