/**
 * Splash-екран з радар-світінням.
 */

import { html } from './dom';
import { strings } from '../../i18n/uk';

export interface SplashApi {
  el: HTMLElement;
  setStatus(text: string): void;
  hide(): Promise<void>;
}

export function buildSplash(): SplashApi {
  const root = html`
    <div class="splash">
      <div class="splash-content">
        <div class="splash-logo">
          <img src="./icons/wolf-scope.svg" width="160" height="160" alt="Veles" />
        </div>
        <div class="splash-text">
          <h1>${strings.app.name}</h1>
          <p data-vm-splash-status>v${strings.app.version} · ${strings.app.tagline}</p>
        </div>
      </div>
    </div>
  `;

  const status = root.querySelector<HTMLElement>('[data-vm-splash-status]')!;

  return {
    el: root,
    setStatus(text) {
      status.textContent = text;
    },
    hide() {
      return new Promise<void>((resolve) => {
        root.style.transition = 'opacity 220ms';
        root.style.opacity = '0';
        window.setTimeout(() => {
          root.remove();
          resolve();
        }, 240);
      });
    }
  };
}
