/**
 * Сторінка аналізу коментарів під постом.
 *
 * Структура:
 *   - URL-форма
 *   - блок прогресу (під час фетчу + класифікації)
 *   - блок результату: пост + донат + легенда + фільтрований список коментарів
 *   - кнопка експорту HTML-звіту
 */

import { html, raw, mount } from '../shared/dom';
import { icons } from '../shared/icons';
import { toast } from '../shared/toast';
import { strings } from '../../i18n/uk';
import { analyzePost, buildHtmlReport, type AnalysisProgress } from '../../core/comments-analysis/analyzer';
import { buildStanceChart } from './stance-chart';
import type { Stance, StanceReport } from '../../types';

export function buildCommentsPage(): HTMLElement {
  injectStyles();
  const root = html`
    <section class="page" id="page-comments" role="tabpanel">
      <header class="page-header">
        <div>
          <div class="page-eyebrow">${strings.comments.eyebrow}</div>
          <h1 class="page-title">${strings.comments.pageTitle}</h1>
        </div>
        <div class="row gap-2">
          ${raw(`<span class="badge">${icons.comments(12).value}<span>stance · 3 buckets</span></span>`)}
        </div>
      </header>

      <div class="panel">
        <form class="row gap-3" data-vm-form style="align-items: flex-end;">
          <div class="field" style="flex: 1;">
            <label class="field-label" for="vm-post-url">URL поста</label>
            <input
              type="url"
              id="vm-post-url"
              class="input input-mono"
              placeholder="https://t.me/channel/123"
              required
            />
          </div>
          <button type="submit" class="btn btn-primary btn-lg" data-vm-analyze>
            ${raw(icons.brain(16).value)}
            <span>Аналізувати</span>
          </button>
        </form>
      </div>

      <div data-vm-progress style="display:none;"></div>
      <div data-vm-result style="display:none;"></div>
    </section>
  `;

  const form        = root.querySelector<HTMLFormElement>('[data-vm-form]')!;
  const urlInput    = root.querySelector<HTMLInputElement>('#vm-post-url')!;
  const analyzeBtn  = root.querySelector<HTMLButtonElement>('[data-vm-analyze]')!;
  const progressEl  = root.querySelector<HTMLElement>('[data-vm-progress]')!;
  const resultEl    = root.querySelector<HTMLElement>('[data-vm-result]')!;

  let currentAbort: AbortController | null = null;

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const url = urlInput.value.trim();
    if (!url) return;

    currentAbort?.abort();
    currentAbort = new AbortController();

    analyzeBtn.disabled = true;
    analyzeBtn.querySelector('span')!.textContent = 'Працюємо…';
    progressEl.style.display = '';
    resultEl.style.display = 'none';

    const renderProgress = (p: AnalysisProgress) => {
      let label = '';
      let percent: number | null = null;
      switch (p.phase) {
        case 'parsing':            label = 'Розбираємо посилання…'; break;
        case 'fetching-post':      label = 'Завантажуємо пост…';    break;
        case 'fetching-comments':  label = `Тягнемо коментарі: ${p.fetchedComments ?? 0}`; break;
        case 'classifying': {
          const done  = p.classifiedComments ?? 0;
          const total = p.totalComments ?? 0;
          label = `Класифікуємо: ${done}/${total}`;
          if (total > 0) percent = Math.round((done / total) * 100);
          break;
        }
        case 'done':               label = 'Готово'; percent = 100; break;
      }
      progressEl.replaceChildren(html`
        <div class="panel">
          <div class="row gap-3">
            <span class="led led-warning" style="width: 12px; height: 12px;"></span>
            <span class="text-mono" style="font-size: var(--fs-sm); letter-spacing: var(--tracking-wide);">${label}</span>
            <div class="grow"></div>
            <button class="btn btn-ghost btn-sm" data-vm-cancel>${raw(icons.x(14).value)}<span>Скасувати</span></button>
          </div>
          ${percent !== null
            ? raw(`<div class="vm-progressbar" style="margin-top: 12px;"><div class="vm-progressbar-fill" style="width: ${percent}%"></div></div>`)
            : ''
          }
        </div>
      `);
      progressEl.querySelector('[data-vm-cancel]')?.addEventListener('click', () => currentAbort?.abort());
    };

    try {
      const report = await analyzePost({
        url,
        signal: currentAbort.signal,
        onProgress: renderProgress
      });
      progressEl.style.display = 'none';
      resultEl.style.display = '';
      mount(resultEl, renderReport(report));
    } catch (err) {
      progressEl.style.display = 'none';
      toast.error(`Аналіз перервано: ${(err as Error).message}`);
    } finally {
      analyzeBtn.disabled = false;
      analyzeBtn.querySelector('span')!.textContent = 'Аналізувати';
    }
  });

  return root;
}

// ─────────────────────────  Result rendering  ─────────────────────────
function renderReport(report: StanceReport): HTMLElement {
  const total = report.totalComments;
  const wrapper = html`
    <div class="col gap-4">
      <div class="panel">
        <div class="text-eyebrow" style="margin-bottom: 8px;">Оригінальний пост</div>
        <div class="vm-post-text">${report.postText}</div>
        <div class="text-muted" style="font-size: var(--fs-xs); margin-top: 8px;">
          <a href="${report.postUrl}" target="_blank" rel="noreferrer" class="text-accent">${report.postUrl}</a>
        </div>
      </div>

      <div class="vm-result-grid">
        <div class="panel center">
          ${buildStanceChart(report, { size: 220, strokeWidth: 28 })}
        </div>

        <div class="panel">
          <div class="text-eyebrow" style="margin-bottom: 12px;">Результати</div>
          <div class="col gap-3">
            ${legendRow('support',   'Підтримує',    report.percentages.support,   countByStance(report, 'support'),   total)}
            ${legendRow('oppose',    'Не підтримує', report.percentages.oppose,    countByStance(report, 'oppose'),    total)}
            ${legendRow('unrelated', 'Інше',         report.percentages.unrelated, countByStance(report, 'unrelated'), total)}
          </div>
          <div class="row" style="margin-top: 20px; gap: 8px;">
            <button class="btn btn-secondary btn-sm" data-vm-export>
              ${raw(icons.download(14).value)}
              <span>Завантажити HTML-звіт</span>
            </button>
          </div>
        </div>
      </div>

      <div class="panel" style="padding: 0;">
        <div class="vm-results-header">
          <div class="text-eyebrow">Коментарі (${total})</div>
          <div class="row gap-1">
            <button class="btn btn-ghost btn-sm vm-filter active" data-vm-filter="all">Усі</button>
            <button class="btn btn-ghost btn-sm vm-filter" data-vm-filter="support">Підтримує</button>
            <button class="btn btn-ghost btn-sm vm-filter" data-vm-filter="oppose">Проти</button>
            <button class="btn btn-ghost btn-sm vm-filter" data-vm-filter="unrelated">Інше</button>
          </div>
        </div>
        <div data-vm-comments-list></div>
      </div>
    </div>
  `;

  const list = wrapper.querySelector<HTMLElement>('[data-vm-comments-list]')!;
  let filter: Stance | 'all' = 'all';

  const renderList = () => {
    const items = filter === 'all' ? report.comments : report.comments.filter(c => c.stance === filter);
    list.replaceChildren();
    if (items.length === 0) {
      list.appendChild(html`<div class="text-muted center" style="padding: 32px;">Немає коментарів цієї категорії.</div>`);
      return;
    }
    for (const c of items) {
      list.appendChild(renderComment(c));
    }
  };
  renderList();

  wrapper.querySelectorAll<HTMLButtonElement>('[data-vm-filter]').forEach(btn => {
    btn.addEventListener('click', () => {
      filter = btn.dataset.vmFilter as any;
      wrapper.querySelectorAll('.vm-filter').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      renderList();
    });
  });

  wrapper.querySelector('[data-vm-export]')?.addEventListener('click', () => {
    const blob = new Blob([buildHtmlReport(report)], { type: 'text/html;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `veles-stance-report-${new Date(report.analyzedAt).toISOString().slice(0, 19).replace(/:/g, '-')}.html`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  });

  return wrapper;
}

function legendRow(stance: Stance, label: string, pct: number, count: number, total: number) {
  const color = stance === 'support' ? 'var(--stance-support)' : stance === 'oppose' ? 'var(--stance-oppose)' : 'var(--stance-unrelated)';
  return html`
    <div class="vm-legend-row">
      <span class="vm-legend-dot" style="background:${color};"></span>
      <span class="text-secondary">${label}</span>
      <span class="grow"></span>
      <span class="text-mono text-primary" style="font-size: var(--fs-lg); font-weight: 600;">${pct}%</span>
      <span class="text-muted text-mono" style="font-size: var(--fs-xs);">${count}/${total}</span>
    </div>
  `;
}

function countByStance(report: StanceReport, s: Stance): number {
  return report.comments.filter(c => c.stance === s).length;
}

function renderComment(c: Parameters<typeof renderCommentTyped>[0]): HTMLElement {
  return renderCommentTyped(c);
}
function renderCommentTyped(c: import('../../types').ClassifiedComment): HTMLElement {
  const time = new Date(c.postedAt).toLocaleString('uk-UA');
  const stanceColor = c.stance === 'support' ? 'var(--stance-support)' : c.stance === 'oppose' ? 'var(--stance-oppose)' : 'var(--stance-unrelated)';
  const stanceLabel = c.stance === 'support' ? 'Підтримує' : c.stance === 'oppose' ? 'Не підтримує' : 'Інше';
  return html`
    <article class="vm-comment-row">
      <div class="vm-comment-stance" style="background:${stanceColor};" title="${stanceLabel}"></div>
      <div class="vm-comment-body">
        <div class="row gap-2" style="margin-bottom: 4px;">
          <span class="text-secondary" style="font-weight: 600; font-size: var(--fs-sm);">${c.authorName ?? '—'}</span>
          <span class="text-muted text-mono" style="font-size: var(--fs-xs);">${time}</span>
          <span class="grow"></span>
          <span class="badge" style="color:${stanceColor}; border-color:transparent; background: ${stanceColor.replace('var(--', 'var(--').replace(')', '-soft)')};">${stanceLabel}</span>
        </div>
        <div class="text-primary" style="font-size: var(--fs-base); white-space: pre-wrap; word-break: break-word;">${c.text}</div>
      </div>
    </article>
  `;
}

let stylesInjected = false;
function injectStyles(): void {
  if (stylesInjected) return;
  stylesInjected = true;
  const s = document.createElement('style');
  s.textContent = `
    .vm-result-grid {
      display: grid;
      grid-template-columns: 240px 1fr;
      gap: var(--space-4);
    }
    .vm-post-text {
      white-space: pre-wrap;
      word-break: break-word;
      line-height: var(--lh-relaxed);
      color: var(--fg-primary);
    }

    .vm-legend-row {
      display: flex; align-items: center; gap: var(--space-2);
    }
    .vm-legend-dot {
      width: 14px; height: 14px; border-radius: 50%;
    }

    .vm-filter.active {
      background: var(--accent-soft) !important;
      color: var(--accent) !important;
    }

    .vm-progressbar {
      width: 100%; height: 6px;
      background: var(--bg-elevated);
      border-radius: var(--radius-pill);
      overflow: hidden;
    }
    .vm-progressbar-fill {
      height: 100%;
      background: linear-gradient(90deg, var(--accent), var(--accent-hover));
      transition: width var(--t-base);
    }

    .vm-comment-row {
      display: flex; gap: 0;
      border-top: 1px solid var(--border-subtle);
      padding: var(--space-3) var(--space-4);
    }
    .vm-comment-stance {
      width: 3px; flex-shrink: 0;
      margin-right: var(--space-3);
      border-radius: var(--radius-pill);
    }
    .vm-comment-body { flex: 1; min-width: 0; }

    @media (max-width: 900px) {
      .vm-result-grid { grid-template-columns: 1fr; }
    }
  `;
  document.head.appendChild(s);
}
