/**
 * Крок 3: код підтвердження.
 */

import { html, raw } from '../../shared/dom';
import { icons } from '../../shared/icons';
import { toast } from '../../shared/toast';
import type { WizardState } from '../wizard';
import type { TgUser } from '../../../core/telegram';

export interface CodeStepApi {
  el: HTMLElement;
  onBack(handler: () => void): void;
  onSignedIn(handler: (user: TgUser) => void): void;
  onTwoFactorRequired(handler: () => void): void;
}

export function buildCodeStep(state: WizardState): CodeStepApi {
  const destination = state.lastCodeDestination ?? 'у Telegram-додатку або SMS';
  const canResend = state.lastCanResend !== false;
  const resendLabel = resendButtonLabel(state.lastNextType, canResend);
  const root = html`
    <div class="panel">
      <h3 style="margin-bottom: 12px;">Код підтвердження</h3>
      <div class="row gap-3" style="background: var(--info-soft); border-left: 3px solid var(--info); padding: 12px; border-radius: var(--radius-sm); margin-bottom: 16px; align-items: flex-start;">
        <span style="color: var(--info); flex-shrink: 0; margin-top: 2px;">${raw(icons.info(16).value)}</span>
        <div>
          <div style="margin-bottom: 4px;"><strong>Код прийшов ${destination}</strong></div>
          <div class="text-secondary" style="font-size: var(--fs-sm);">
            На номер <span class="text-mono">${state.phone ?? '—'}</span>.
            Якщо це Telegram-додаток — відкрийте чат з <span class="text-mono">@Telegram</span> (службовий акаунт).
          </div>
        </div>
      </div>
      <form class="col gap-4" data-vm-form>
        <div class="field">
          <label class="field-label" for="vm-code">Код (5-7 цифр)</label>
          <input
            type="text"
            id="vm-code"
            class="input input-mono"
            placeholder="12345"
            inputmode="numeric"
            autocomplete="one-time-code"
            maxlength="7"
            required
            autofocus
          />
          <div class="field-error hidden" data-vm-error></div>
        </div>
        <div class="row between">
          <button type="button" class="btn btn-ghost" data-vm-back>
            ${raw(icons.chevronLeft(14).value)}
            <span>Інший номер</span>
          </button>
          <button type="button" class="btn btn-secondary" data-vm-resend>
            ${raw(icons.refresh(14).value)}
            <span>${resendLabel}</span>
          </button>
          <button type="submit" class="btn btn-primary btn-lg" data-vm-submit>
            <span>Підтвердити</span>
            ${raw(icons.chevronRight(16).value)}
          </button>
        </div>
      </form>
    </div>
  `;

  const signedHandlers: Array<(u: TgUser) => void> = [];
  const twofaHandlers: Array<() => void> = [];
  const backHandlers: Array<() => void> = [];

  const form     = root.querySelector<HTMLFormElement>('[data-vm-form]')!;
  const errEl    = root.querySelector<HTMLElement>('[data-vm-error]')!;
  const submitEl = root.querySelector<HTMLButtonElement>('[data-vm-submit]')!;
  const backEl   = root.querySelector<HTMLButtonElement>('[data-vm-back]')!;
  const resendEl = root.querySelector<HTMLButtonElement>('[data-vm-resend]')!;

  resendEl.addEventListener('click', async () => {
    if (state.lastCanResend === false) {
      toast.warning(
        'Telegram надіслав код у застосунок Telegram (службовий чат «Telegram») на пристрої, ' +
        'де ти вже залогінений. Іншим каналом, зокрема SMS, код зараз недоступний.',
        { duration: 9000 }
      );
      return;
    }
    const labelEl = resendEl.querySelector('span')!;
    resendEl.disabled = true;
    labelEl.textContent = 'Надсилаємо…';
    try {
      const res = await state.authFlow.resendCode();
      state.lastCodeDestination = res.destination;
      state.lastCanResend = res.canResend;
      state.lastNextType = res.nextType;
      toast.success(`Новий код надіслано ${res.destination}`, { duration: 7000 });
    } catch (err) {
      toast.error(`Не вдалося: ${(err as Error).message}`, { duration: 9000 });
    } finally {
      resendEl.disabled = false;
      labelEl.textContent = resendButtonLabel(state.lastNextType, state.lastCanResend !== false);
    }
  });

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    errEl.classList.add('hidden');
    const code = form.querySelector<HTMLInputElement>('#vm-code')!.value.trim();

    submitEl.disabled = true;
    submitEl.querySelector('span')!.textContent = 'Перевіряємо…';
    try {
      const res = await state.authFlow.submitLoginCode(code);
      if (res === 'two-factor-needed') {
        twofaHandlers.forEach(h => h());
      } else {
        signedHandlers.forEach(h => h(res));
      }
    } catch (err) {
      const msg = (err as Error).message;
      if (/PHONE_CODE_INVALID/i.test(msg)) {
        errEl.textContent = 'Невірний код';
      } else if (/PHONE_CODE_EXPIRED/i.test(msg)) {
        errEl.textContent = 'Код протух. Поверніться на крок «Телефон» і запросіть новий.';
      } else {
        errEl.textContent = msg;
      }
      errEl.classList.remove('hidden');
    } finally {
      submitEl.disabled = false;
      submitEl.querySelector('span')!.textContent = 'Підтвердити';
    }
  });

  backEl.addEventListener('click', () => backHandlers.forEach(h => h()));

  return {
    el: root,
    onBack(h)              { backHandlers.push(h); },
    onSignedIn(h)          { signedHandlers.push(h); },
    onTwoFactorRequired(h) { twofaHandlers.push(h); }
  };
}

function resendButtonLabel(nextType: string | null | undefined, canResend: boolean): string {
  if (!canResend) return 'Код у застосунку Telegram';
  if (!nextType)  return 'Надіслати код знову';
  if (/Sms/i.test(nextType))        return 'Надіслати код у SMS';
  if (/MissedCall/i.test(nextType)) return 'Код пропущеним дзвінком';
  if (/Call/i.test(nextType))       return 'Подзвонити з кодом';
  return 'Надіслати код знову';
}
