/**
 * Глобальний холдер відкритого vault-у.
 *
 * App.ts при unlock зберігає сюди OpenVault, інші модулі (telegram, monitoring,
 * comments-analysis…) дістають його через requireVault(). Якщо vault закритий —
 * requireVault() кидає виняток (нічого не повинно викликати його до unlock-у).
 */

import type { OpenVault } from './vault';

let current: OpenVault | null = null;
const listeners = new Set<(v: OpenVault | null) => void>();

export function setVault(v: OpenVault | null): void {
  current = v;
  for (const l of listeners) l(v);
}

export function getVault(): OpenVault | null {
  return current;
}

export function requireVault(): OpenVault {
  if (!current) {
    throw new Error('Vault не відкритий — користувач не авторизований');
  }
  return current;
}

export function onVaultChange(handler: (v: OpenVault | null) => void): () => void {
  listeners.add(handler);
  return () => listeners.delete(handler);
}
