/**
 * Крок 4: cloud-password (2FA).
 * Показується лише якщо submitLoginCode повернув 'two-factor-needed'.
 */

import { html, raw } from '../../shared/dom';
import { icons } from '../../shared/icons';
import type { WizardState } from '../wizard';
import type { TgUser } from '../../../core/telegram';

export interface TwoFactorStepApi {
  el: HTMLElement;
  onBack(handler: () => void): void;
  onSignedIn(handler: (user: TgUser) => void): void;
}

export function buildTwoFactorStep(state: WizardState): TwoFactorStepApi {
  const root = html`
    <div class="panel">
      <h3 style="margin-bottom: 12px;">Cloud password (2FA)</h3>
      <p class="text-secondary" style="margin-bottom: 16px;">
        Ваш Telegram-акаунт захищений двоетапною перевіркою. Введіть пароль, що ви використовуєте
        для входу в Telegram (це <strong>не</strong> код з SMS).
      </p>
      <form class="col gap-4" data-vm-form>
        <div class="field">
          <label class="field-label" for="vm-2fa">Cloud password</label>
          <input
            type="password"
            id="vm-2fa"
            class="input input-mono"
            placeholder="••••••••"
            autocomplete="current-password"
            required
            autofocus
          />
          <div class="field-error hidden" data-vm-error></div>
        </div>
        <div class="row between">
          <button type="button" class="btn btn-ghost" data-vm-back>
            ${raw(icons.chevronLeft(14).value)}
            <span>Назад</span>
          </button>
          <button type="submit" class="btn btn-primary btn-lg" data-vm-submit>
            <span>Підтвердити</span>
            ${raw(icons.chevronRight(16).value)}
          </button>
        </div>
      </form>
    </div>
  `;

  const signedHandlers: Array<(u: TgUser) => void> = [];
  const backHandlers: Array<() => void> = [];

  const form     = root.querySelector<HTMLFormElement>('[data-vm-form]')!;
  const errEl    = root.querySelector<HTMLElement>('[data-vm-error]')!;
  const submitEl = root.querySelector<HTMLButtonElement>('[data-vm-submit]')!;
  const backEl   = root.querySelector<HTMLButtonElement>('[data-vm-back]')!;

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    errEl.classList.add('hidden');
    const pw = form.querySelector<HTMLInputElement>('#vm-2fa')!.value;

    submitEl.disabled = true;
    submitEl.querySelector('span')!.textContent = 'Перевіряємо…';
    try {
      const user = await state.authFlow.submitTwoFactorPassword(pw);
      signedHandlers.forEach(h => h(user));
    } catch (err) {
      const msg = (err as Error).message;
      if (/PASSWORD_HASH_INVALID/i.test(msg) || /password_invalid/i.test(msg)) {
        errEl.textContent = 'Невірний пароль';
      } else {
        errEl.textContent = msg;
      }
      errEl.classList.remove('hidden');
    } finally {
      submitEl.disabled = false;
      submitEl.querySelector('span')!.textContent = 'Підтвердити';
    }
  });

  backEl.addEventListener('click', () => backHandlers.forEach(h => h()));

  return {
    el: root,
    onBack(h)     { backHandlers.push(h); },
    onSignedIn(h) { signedHandlers.push(h); }
  };
}
