/**
 * Крок 2: номер телефону.
 */

import { html, raw } from '../../shared/dom';
import { icons } from '../../shared/icons';
import { toast } from '../../shared/toast';
import type { WizardState } from '../wizard';

export interface PhoneStepApi {
  el: HTMLElement;
  onBack(handler: () => void): void;
  onNext(handler: (data: { phone: string }) => void): void;
}

export function buildPhoneStep(state: WizardState): PhoneStepApi {
  const root = html`
    <div class="panel">
      <h3 style="margin-bottom: 12px;">Номер телефону</h3>
      <p class="text-secondary" style="margin-bottom: 16px;">
        Введіть номер, до якого привʼязано Telegram-акаунт. Telegram надішле код підтвердження
        в офіційний додаток (або SMS, якщо ви давно не заходили).
      </p>
      <form class="col gap-4" data-vm-form>
        <div class="field">
          <label class="field-label" for="vm-phone">Телефон</label>
          <input
            type="tel"
            id="vm-phone"
            class="input input-mono"
            placeholder="+380501234567"
            autocomplete="tel"
            inputmode="tel"
            value="${state.phone ?? ''}"
            required
          />
          <div class="field-error hidden" data-vm-error></div>
        </div>
        <div class="row between">
          <button type="button" class="btn btn-ghost" data-vm-back>
            ${raw(icons.chevronLeft(14).value)}
            <span>Назад</span>
          </button>
          <button type="submit" class="btn btn-primary btn-lg" data-vm-submit>
            <span>Надіслати код</span>
            ${raw(icons.chevronRight(16).value)}
          </button>
        </div>
      </form>
    </div>
  `;

  const nextHandlers: Array<(d: { phone: string }) => void> = [];
  const backHandlers: Array<() => void> = [];

  const form     = root.querySelector<HTMLFormElement>('[data-vm-form]')!;
  const errEl    = root.querySelector<HTMLElement>('[data-vm-error]')!;
  const submitEl = root.querySelector<HTMLButtonElement>('[data-vm-submit]')!;
  const backEl   = root.querySelector<HTMLButtonElement>('[data-vm-back]')!;

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    errEl.classList.add('hidden');
    const phone = form.querySelector<HTMLInputElement>('#vm-phone')!.value.trim();

    submitEl.disabled = true;
    submitEl.querySelector('span')!.textContent = 'Надсилаємо…';
    try {
      const res = await state.authFlow.sendLoginCode(phone);
      state.lastCodeDestination = res.destination;
      state.lastCanResend = res.canResend;
      state.lastNextType = res.nextType;
      toast.success(`Код надіслано ${res.destination}`, { duration: 7000 });
      nextHandlers.forEach(h => h({ phone }));
    } catch (err) {
      errEl.textContent = (err as Error).message;
      errEl.classList.remove('hidden');
    } finally {
      submitEl.disabled = false;
      submitEl.querySelector('span')!.textContent = 'Надіслати код';
    }
  });

  backEl.addEventListener('click', () => backHandlers.forEach(h => h()));

  return {
    el: root,
    onBack(h) { backHandlers.push(h); },
    onNext(h) { nextHandlers.push(h); }
  };
}
