/**
 * Setup-екран пароля: перше встановлення головного пароля для шифрування vault-у.
 *
 * Використовується як крок onboarding-у. Після успішного init — повертає
 * відкритий vault у callback onCreated.
 */

import { html, raw } from '../shared/dom';
import { icons } from '../shared/icons';
import { toast } from '../shared/toast';
import { initVault, type OpenVault } from '../../core/storage/vault';

export interface SetPasswordApi {
  el: HTMLElement;
  onCreated(handler: (vault: OpenVault) => void): void;
  onBack(handler: () => void): void;
}

export function buildSetPasswordScreen(): SetPasswordApi {
  const root = html`
    <div class="app-main">
      <section class="page" style="max-width: 520px;">
        <header class="page-header" style="border: none; padding-bottom: 0;">
          <div>
            <div class="page-eyebrow">vault · setup</div>
            <h1 class="page-title">Захист даних</h1>
          </div>
          <div style="color: var(--accent);">${raw(icons.shield(28).value)}</div>
        </header>

        <div class="panel">
          <p class="text-secondary" style="margin-bottom: 20px;">
            Придумайте пароль — він шифрує Telegram-сесію та налаштування. Кожного разу при відкритті
            застосунку доведеться вводити його заново. <strong style="color: var(--warning);">Пароль ніде не зберігається
            і не відновлюється</strong> — якщо забудете, доведеться чистити дані й логінитись з нуля.
          </p>

          <form data-vm-setpw class="col gap-4">
            <div class="field">
              <label class="field-label" for="vm-pw1">Новий пароль</label>
              <input
                type="password"
                id="vm-pw1"
                class="input input-mono"
                placeholder="Не менше 6 символів"
                autocomplete="new-password"
                required
                minlength="6"
                autofocus
              />
            </div>
            <div class="field">
              <label class="field-label" for="vm-pw2">Підтвердження</label>
              <input
                type="password"
                id="vm-pw2"
                class="input input-mono"
                placeholder="Введіть пароль ще раз"
                autocomplete="new-password"
                required
                minlength="6"
              />
              <div class="field-error hidden" data-vm-error></div>
            </div>

            <div class="row gap-3">
              <button type="button" class="btn btn-ghost" data-vm-back>
                ${raw(icons.chevronLeft(14).value)}
                <span>Назад</span>
              </button>
              <div class="grow"></div>
              <button type="submit" class="btn btn-primary btn-lg" data-vm-submit>
                <span>Створити та продовжити</span>
                ${raw(icons.chevronRight(16).value)}
              </button>
            </div>
          </form>
        </div>

        <div class="text-muted" style="font-size: var(--fs-xs); line-height: 1.6;">
          Шифрування: <span class="text-mono">AES-GCM 256</span>,
          ключ виводиться з пароля через <span class="text-mono">PBKDF2-HMAC-SHA256, 250 000 ітерацій</span>.
          Сіль зберігається локально, ключ — лише в памʼяті до закриття вкладки.
        </div>
      </section>
    </div>
  `;

  const form    = root.querySelector<HTMLFormElement>('[data-vm-setpw]')!;
  const pw1     = root.querySelector<HTMLInputElement>('#vm-pw1')!;
  const pw2     = root.querySelector<HTMLInputElement>('#vm-pw2')!;
  const errEl   = root.querySelector<HTMLElement>('[data-vm-error]')!;
  const submit  = root.querySelector<HTMLButtonElement>('[data-vm-submit]')!;
  const backBtn = root.querySelector<HTMLButtonElement>('[data-vm-back]')!;

  const createdHandlers: Array<(v: OpenVault) => void> = [];
  const backHandlers: Array<() => void> = [];

  const showError = (msg: string | null) => {
    if (msg) { errEl.textContent = msg; errEl.classList.remove('hidden'); }
    else     { errEl.classList.add('hidden'); }
  };

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    showError(null);
    if (pw1.value !== pw2.value) {
      showError('Паролі не співпадають');
      pw2.select();
      return;
    }
    if (pw1.value.length < 6) {
      showError('Мінімальна довжина — 6 символів');
      return;
    }

    submit.disabled = true;
    submit.querySelector('span')!.textContent = 'Створюємо ключ…';
    try {
      const vault = await initVault(pw1.value);
      toast.success('Vault створено');
      createdHandlers.forEach(h => h(vault));
    } catch (err) {
      showError(`Не вдалося створити vault: ${(err as Error).message}`);
    } finally {
      submit.disabled = false;
      submit.querySelector('span')!.textContent = 'Створити та продовжити';
    }
  });

  backBtn.addEventListener('click', () => {
    backHandlers.forEach(h => h());
  });

  return {
    el: root,
    onCreated(h) { createdHandlers.push(h); },
    onBack(h)    { backHandlers.push(h); }
  };
}
