/**
 * Обгортка над Notifications API.
 */

import type { FoundPost } from '../../types';

export type Permission = NotificationPermission | 'unsupported';

export function getPermission(): Permission {
  if (typeof Notification === 'undefined') return 'unsupported';
  return Notification.permission;
}

export async function requestPermission(): Promise<Permission> {
  if (typeof Notification === 'undefined') return 'unsupported';
  try {
    return await Notification.requestPermission();
  } catch {
    return Notification.permission;
  }
}

/**
 * Показати нотифікацію по знайденій публікації.
 * Тиха обробка: якщо немає дозволу або вкладка активна — не показуємо.
 */
export function notifyFoundPost(post: FoundPost, opts?: { onlyWhenHidden?: boolean }): void {
  if (typeof Notification === 'undefined') return;
  if (Notification.permission !== 'granted') return;
  if (opts?.onlyWhenHidden && document.visibilityState === 'visible') return;

  try {
    const preview = post.rawText.length > 140 ? post.rawText.slice(0, 137) + '…' : post.rawText;
    const n = new Notification(`Veles · ${post.channelTitle}`, {
      body: preview,
      tag: `vm-post-${post.channelId}-${post.messageId}`,
      icon: './favicon.svg',
      requireInteraction: false,
      silent: true
    } as NotificationOptions);
    n.onclick = () => {
      window.focus();
      if (post.url && post.url.startsWith('https://')) {
        window.open(post.url, '_blank', 'noreferrer');
      }
      n.close();
    };
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn('[notif] failed:', err);
  }
}
