/**
 * Крок 5: вибір каналів для моніторингу.
 *
 * UI:
 *   - пошук по назві/username
 *   - select all / clear / invert
 *   - чекбокси з мета-інфою
 *   - кнопка «Додати вручну» @username
 */

import { html, raw } from '../../shared/dom';
import { icons } from '../../shared/icons';
import { toast } from '../../shared/toast';
import { confirm, openModal } from '../../shared/modal';
import { resolveByUsername } from '../../../core/telegram';
import type { WizardState } from '../wizard';
import type { DialogItem } from '../../../core/telegram';

export interface ChannelsStepApi {
  el: HTMLElement;
  onBack(handler: () => void): void;
  onNext(handler: (selected: Set<string>) => void): void;
}

export function buildChannelsStep(state: WizardState): ChannelsStepApi {
  const selected = new Set<string>(state.selectedChannelIds ?? []);
  const dialogs: DialogItem[] = state.dialogs ?? [];

  const root = html`
    <div class="col gap-4">
      <div class="panel">
        <div class="row between" style="margin-bottom: 12px; flex-wrap: wrap; gap: 8px;">
          <h3 style="margin: 0;">Канали для моніторингу</h3>
          <div class="row gap-2">
            <button type="button" class="btn btn-secondary btn-sm" data-vm-add-manual>
              ${raw(icons.plus(14).value)}
              <span>Додати @username</span>
            </button>
          </div>
        </div>

        <div class="row gap-2" style="margin-bottom: 12px;">
          <div style="flex: 1; position: relative;">
            <input
              type="search"
              class="input"
              placeholder="Пошук за назвою або @username…"
              data-vm-search
              style="padding-left: 36px;"
            />
            <span style="position: absolute; left: 12px; top: 50%; transform: translateY(-50%); color: var(--fg-muted);">
              ${raw(icons.search(16).value)}
            </span>
          </div>
          <button type="button" class="btn btn-ghost btn-sm" data-vm-select-all>Усі</button>
          <button type="button" class="btn btn-ghost btn-sm" data-vm-clear>Скинути</button>
          <button type="button" class="btn btn-ghost btn-sm" data-vm-invert>Інвертувати</button>
        </div>

        <div class="text-secondary" style="font-size: var(--fs-sm); margin-bottom: 8px;">
          Знайдено: <span data-vm-total>${dialogs.length}</span> ·
          Обрано: <span class="text-accent" data-vm-selected-count>${selected.size}</span>
        </div>

        <div class="vm-channels-list" data-vm-list></div>
      </div>

      <div class="row between">
        <button type="button" class="btn btn-ghost" data-vm-back>
          ${raw(icons.chevronLeft(14).value)}
          <span>Назад</span>
        </button>
        <button type="button" class="btn btn-primary btn-lg" data-vm-next>
          <span>Зберегти і продовжити</span>
          ${raw(icons.chevronRight(16).value)}
        </button>
      </div>
    </div>
  `;

  injectListStyles();

  const listEl       = root.querySelector<HTMLElement>('[data-vm-list]')!;
  const searchEl     = root.querySelector<HTMLInputElement>('[data-vm-search]')!;
  const totalEl      = root.querySelector<HTMLElement>('[data-vm-total]')!;
  const countEl      = root.querySelector<HTMLElement>('[data-vm-selected-count]')!;
  const selectAllBtn = root.querySelector<HTMLButtonElement>('[data-vm-select-all]')!;
  const clearBtn     = root.querySelector<HTMLButtonElement>('[data-vm-clear]')!;
  const invertBtn    = root.querySelector<HTMLButtonElement>('[data-vm-invert]')!;
  const addManualBtn = root.querySelector<HTMLButtonElement>('[data-vm-add-manual]')!;
  const nextBtn      = root.querySelector<HTMLButtonElement>('[data-vm-next]')!;
  const backBtn      = root.querySelector<HTMLButtonElement>('[data-vm-back]')!;

  let filtered: DialogItem[] = [...dialogs];

  const refreshCount = () => {
    countEl.textContent = String(selected.size);
  };

  const renderList = () => {
    if (filtered.length === 0) {
      listEl.replaceChildren(html`
        <div class="text-muted center" style="min-height: 100px; padding: 16px; text-align: center;">
          Каналів не знайдено. Спробуйте інший пошук або додайте вручну через @username.
        </div>
      `);
      return;
    }
    listEl.replaceChildren();
    for (const ch of filtered) {
      const row = html`
        <label class="vm-channel-row" data-vm-row="${ch.id}">
          <input type="checkbox" data-vm-cb ${selected.has(ch.id) ? 'checked' : ''} />
          <div class="vm-channel-avatar">${initials(ch.title)}</div>
          <div class="vm-channel-info">
            <div class="vm-channel-title">${ch.title}</div>
            <div class="vm-channel-sub">
              ${ch.username ? '@' + ch.username : (ch.isPrivate ? 'приватний' : 'без username')}
              ${ch.participantsCount ? ' · ' + formatCount(ch.participantsCount) + ' учасників' : ''}
            </div>
          </div>
          <div class="vm-channel-tag">
            ${ch.isChannel ? 'канал' : 'група'}
          </div>
        </label>
      `;
      const cb = row.querySelector<HTMLInputElement>('[data-vm-cb]')!;
      cb.addEventListener('change', () => {
        if (cb.checked) selected.add(ch.id);
        else selected.delete(ch.id);
        refreshCount();
      });
      listEl.appendChild(row);
    }
  };

  const applyFilter = (query: string) => {
    const q = query.trim().toLowerCase();
    if (!q) {
      filtered = [...dialogs];
    } else {
      filtered = dialogs.filter(d =>
        d.title.toLowerCase().includes(q) ||
        (d.username ?? '').toLowerCase().includes(q)
      );
    }
    totalEl.textContent = String(filtered.length);
    renderList();
  };

  searchEl.addEventListener('input', () => applyFilter(searchEl.value));
  selectAllBtn.addEventListener('click', () => {
    filtered.forEach(d => selected.add(d.id));
    refreshCount();
    renderList();
  });
  clearBtn.addEventListener('click', async () => {
    if (selected.size === 0) return;
    const ok = await confirm({
      title: 'Скинути вибір?',
      body: `Зняти позначки з усіх обраних каналів (${selected.size})?`,
      confirmLabel: 'Так',
      cancelLabel: 'Скасувати'
    });
    if (!ok) return;
    selected.clear();
    refreshCount();
    renderList();
  });
  invertBtn.addEventListener('click', () => {
    for (const d of filtered) {
      if (selected.has(d.id)) selected.delete(d.id);
      else selected.add(d.id);
    }
    refreshCount();
    renderList();
  });

  addManualBtn.addEventListener('click', () => {
    const usernameField = html`
      <div class="field">
        <label class="field-label" for="vm-add-username">@username або посилання</label>
        <input
          type="text"
          id="vm-add-username"
          class="input input-mono"
          placeholder="@channelname або https://t.me/channelname"
          autofocus
        />
      </div>
    ` as HTMLElement;

    openModal({
      title: 'Додати канал вручну',
      body: usernameField,
      actions: [
        { label: 'Скасувати', kind: 'ghost' },
        {
          label: 'Додати',
          kind: 'primary',
          closeOnClick: false,
          onClick: async () => {
            const input = usernameField.querySelector<HTMLInputElement>('#vm-add-username')!;
            const value = input.value.trim();
            if (!value) return;
            try {
              const ch = await resolveByUsername(value);
              if (!dialogs.find(d => d.id === ch.id)) {
                dialogs.push(ch);
                applyFilter(searchEl.value);
              }
              selected.add(ch.id);
              refreshCount();
              renderList();
              toast.success(`Додано: ${ch.title}`);
              // closeModal через кнопку
              (input.closest('.modal-scrim') as HTMLElement | null)?.remove();
              document.body.style.overflow = '';
            } catch (err) {
              toast.error((err as Error).message);
            }
          }
        }
      ]
    });
  });

  backBtn.addEventListener('click', () => onBackHandlers.forEach(h => h()));
  nextBtn.addEventListener('click', () => {
    if (selected.size === 0) {
      void confirm({
        title: 'Без обраних каналів',
        body: 'Жоден канал не вибрано. Без них моніторинг не запрацює. Все одно продовжити? Канали можна додати пізніше в Налаштуваннях.',
        confirmLabel: 'Продовжити',
        cancelLabel: 'Повернутися'
      }).then(ok => {
        if (ok) onNextHandlers.forEach(h => h(selected));
      });
      return;
    }
    onNextHandlers.forEach(h => h(selected));
  });

  // початковий рендер
  totalEl.textContent = String(dialogs.length);
  renderList();

  const onBackHandlers: Array<() => void> = [];
  const onNextHandlers: Array<(s: Set<string>) => void> = [];

  return {
    el: root,
    onBack(h) { onBackHandlers.push(h); },
    onNext(h) { onNextHandlers.push(h); }
  };
}

// ────────────────────  utility  ────────────────────
function initials(title: string): string {
  return title.split(/\s+/).slice(0, 2).map(w => w[0] ?? '').join('').toUpperCase() || '·';
}
function formatCount(n: number): string {
  if (n >= 1_000_000) return (n / 1_000_000).toFixed(1) + 'M';
  if (n >= 1_000)     return (n / 1_000).toFixed(1) + 'K';
  return String(n);
}

let listStylesInjected = false;
function injectListStyles(): void {
  if (listStylesInjected) return;
  listStylesInjected = true;
  const style = document.createElement('style');
  style.textContent = `
    .vm-channels-list {
      display: flex;
      flex-direction: column;
      gap: 4px;
      max-height: 420px;
      overflow-y: auto;
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-sm);
      padding: 6px;
      background: var(--bg-base);
    }
    .vm-channel-row {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 8px 10px;
      border-radius: var(--radius-xs);
      cursor: pointer;
      transition: background var(--t-fast);
    }
    .vm-channel-row:hover { background: var(--bg-elevated); }
    .vm-channel-row input[type="checkbox"] {
      appearance: none;
      width: 18px; height: 18px;
      border: 1.5px solid var(--border-base);
      border-radius: var(--radius-xs);
      background: var(--bg-surface);
      display: grid; place-content: center;
      flex-shrink: 0;
    }
    .vm-channel-row input[type="checkbox"]:checked {
      background: var(--accent); border-color: var(--accent);
    }
    .vm-channel-row input[type="checkbox"]:checked::after {
      content: ''; width: 10px; height: 6px;
      border-left: 2px solid var(--fg-inverse); border-bottom: 2px solid var(--fg-inverse);
      transform: rotate(-45deg) translate(1px, -1px);
    }
    .vm-channel-avatar {
      width: 36px; height: 36px;
      border-radius: var(--radius-sm);
      background: var(--bg-elevated);
      border: 1px solid var(--border-subtle);
      display: grid; place-items: center;
      font-family: var(--font-mono);
      font-size: var(--fs-sm);
      font-weight: 600;
      color: var(--accent);
      flex-shrink: 0;
    }
    .vm-channel-info { flex: 1; min-width: 0; }
    .vm-channel-title {
      font-size: var(--fs-base);
      color: var(--fg-primary);
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .vm-channel-sub {
      font-family: var(--font-mono);
      font-size: var(--fs-xs);
      color: var(--fg-muted);
      letter-spacing: var(--tracking-wide);
    }
    .vm-channel-tag {
      font-family: var(--font-mono);
      font-size: var(--fs-xs);
      letter-spacing: var(--tracking-wide);
      text-transform: uppercase;
      color: var(--fg-muted);
      padding: 2px 8px;
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-xs);
    }
  `;
  document.head.appendChild(style);
}
