/**
 * SVG-іконки в стилі Lucide/Heroicons, але дібрані під tactical theme.
 * Усі іконки повертають TrustedHtml — їх можна підставляти в html``.
 *
 * Розмір за замовчуванням 16x16; через параметр size — змінюємо.
 */

import { raw, type TrustedHtml } from './dom';

function svg(d: string, size = 16, viewBox = '0 0 24 24'): TrustedHtml {
  return raw(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="${viewBox}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`
  );
}

