/**
 * Утиліти для підготовки тексту перед AI-обробкою.
 */

const URL_RE   = /https?:\/\/\S+/g;
const EMOJI_RE = /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]+/gu;
const MENTION_RE = /@[A-Za-z0-9_]{3,32}/g;
const HASHTAG_RE = /#[\p{L}0-9_]+/gu;

export interface CleanOptions {
  keepMentions?: boolean;
  keepHashtags?: boolean;
}

/**
 * Прибрати URL-и, емодзі, зайві пробіли. Опціонально — згадки і хештеги.
 */
export function cleanText(text: string, opts: CleanOptions = {}): string {
  let out = text;
  out = out.replace(URL_RE, ' ');
  out = out.replace(EMOJI_RE, ' ');
  if (!opts.keepMentions) out = out.replace(MENTION_RE, ' ');
  if (!opts.keepHashtags) out = out.replace(HASHTAG_RE, ' ');
  out = out.replace(/\s+/g, ' ').trim();
  return out;
}

/**
 * Розбити довгий текст на чанки приблизно по {maxWords} слів,
 * щоб поміститися в контекст моделі. Зберігає межі речень де можливо.
 */
export function chunkText(text: string, maxWords = 256): string[] {
  const words = text.split(/\s+/);
  if (words.length <= maxWords) return [text];

  // Спершу пробуємо ділити по реченнях
  const sentences = text.split(/(?<=[.!?…])\s+/);
  const chunks: string[] = [];
  let current = '';
  let currentWordCount = 0;

  for (const s of sentences) {
    const sWords = s.split(/\s+/).length;
    if (currentWordCount + sWords > maxWords && current) {
      chunks.push(current.trim());
      current = '';
      currentWordCount = 0;
    }
    if (sWords > maxWords) {
      // дуже довге речення — рубаємо тупо по слову
      const ws = s.split(/\s+/);
      for (let i = 0; i < ws.length; i += maxWords) {
        chunks.push(ws.slice(i, i + maxWords).join(' '));
      }
      continue;
    }
    current += (current ? ' ' : '') + s;
    currentWordCount += sWords;
  }
  if (current.trim()) chunks.push(current.trim());
  return chunks;
}

/**
 * Витягнути унікальні «слова» (мінімум 3 літери), приведені до lowercase.
 * Використовується для word-level embeddings матчингу.
 */
export function extractUniqueWords(text: string, minLen = 3): string[] {
  const out = new Set<string>();
  const tokens = text.toLowerCase().match(/\p{L}{1,}/gu) ?? [];
  for (const w of tokens) {
    if (w.length >= minLen) out.add(w);
  }
  return [...out];
}

/**
 * Розпарсити поле «ключових слів» з UI: через кому, з лапками для фраз.
 *   `владу, "погана дорога", корупція`
 *   → words: ['владу', 'корупція'], phrases: ['погана дорога']
 */
export function parseKeywordsInput(raw: string): { words: string[]; phrases: string[] } {
  const phrases: string[] = [];
  const noPhrases = raw.replace(/"([^"]+)"/g, (_, m) => { phrases.push(m.trim()); return ''; });
  const words = noPhrases.split(',').map(s => s.trim()).filter(Boolean);
  return { words, phrases };
}
