/**
 * Vault — типобезпечний фасад над IndexedDB + Web Crypto.
 *
 * Життєвий цикл:
 *   1. App.start() → vaultStatus() →
 *        'empty'   — перший запуск, треба onboarding + setPassword()
 *        'locked'  — є дані, треба unlock(password)
 *   2. Після успішного unlock() — отримуємо OpenVault, що дає типовані аксессори.
 *   3. closeVault() — забуваємо ключ із пам'яті (на logout).
 */

import {
  openDB,
  deleteDB,
  type VelesDB
} from './idb';
import {
  deriveKey,
  generateSalt,
  encryptJson,
  decryptJson,
  isAuthError
} from './crypto';
import type {
  AppSettings,
  MonitoringConfig,
  MonitoredChannel,
  FoundPost,
  StanceReport
} from '../../types';

// ─────────────────────────────────  Meta keys  ─────────────────────────────
const META_SALT     = 'salt';
const META_VERSION  = 'schemaVersion';
const META_CREATED  = 'createdAt';
const META_KDF_INFO = 'kdf';

// ─────────────────────────────────  Secure keys  ───────────────────────────
const SECURE_SESSION  = 'telegramSession';
const SECURE_API_CREDS = 'apiCreds';

// ─────────────────────────────────  Settings keys  ────────────────────────
const SETTINGS_APP = 'app';

// ─────────────────────────────────  Public types  ─────────────────────────
export type VaultStatus = 'empty' | 'locked' | 'open';

export interface ApiCreds {
  apiId: number;
  apiHash: string;
}

export const DEFAULT_SETTINGS: AppSettings = {
  aiMode: 'hybrid',
  accuracy: 2,
  threshold: 0.5,
  notifications: {
    browser: true,
    faviconBadge: true
  },
  monitoring: {
    throttleMode: 'queue'
  },
  ui: {
    theme: 'dark',
    locale: 'uk'
  },
  media: {
    folderHandleSaved: false
  },
  labelling: {
    enabled: false
  }
};

// ─────────────────────────────────  Status check  ─────────────────────────
export async function vaultStatus(): Promise<VaultStatus> {
  const db = await openDB();
  const salt = await db.get('meta', META_SALT);
  if (!salt) return 'empty';
  // Якщо є salt — vault існує, але ми поки що locked, бо ключа в пам'яті немає.
  return 'locked';
}

// ─────────────────────────────────  Initialize  ───────────────────────────
/**
 * Перший запуск: створити сіль, зберегти metadata, повернути OpenVault.
 */
export async function initVault(password: string): Promise<OpenVault> {
  if (password.length < 6) {
    throw new Error('Пароль має містити щонайменше 6 символів');
  }
  const db = await openDB();
  const existing = await db.get('meta', META_SALT);
  if (existing) {
    throw new Error('Vault уже ініціалізовано — використайте unlockVault()');
  }
  const salt = generateSalt();
  const key = await deriveKey(password, salt);

  const tx = db.transaction('meta', 'readwrite');
  await tx.store.put(salt, META_SALT);
  await tx.store.put(1, META_VERSION);
  await tx.store.put(Date.now(), META_CREATED);
  await tx.store.put({ kdf: 'PBKDF2', iterations: 250000, hash: 'SHA-256' }, META_KDF_INFO);
  await tx.done;

  const vault = new OpenVault(db, key);
  // Записуємо налаштування за замовчуванням
  await vault.settings.set(DEFAULT_SETTINGS);
  return vault;
}

// ─────────────────────────────────  Unlock  ───────────────────────────────
/**
 * Розблокувати існуючий vault. Повертає null, якщо пароль невірний.
 */
export async function unlockVault(password: string): Promise<OpenVault | null> {
  const db = await openDB();
  const salt = await db.get('meta', META_SALT) as Uint8Array | undefined;
  if (!salt) {
    throw new Error('Vault не ініціалізовано — викликайте initVault()');
  }
  const key = await deriveKey(password, salt);

  // Перевіряємо ключ: пробуємо розшифрувати settings (вони мають існувати після init).
  // Якщо settings ще немає — пробуємо session; якщо й її немає — приймаємо ключ як валідний.
  try {
    const settings = await db.get('settings', SETTINGS_APP);
    if (settings) {
      await decryptJson<AppSettings>(key, settings);
    } else {
      // edge-case: salt є, але settings не записалися — приймаємо ключ
    }
  } catch (err) {
    if (isAuthError(err)) return null;
    throw err;
  }

  return new OpenVault(db, key);
}

// ─────────────────────────────────  Wipe  ─────────────────────────────────
/**
 * Повне очищення всіх даних. Незворотньо.
 */
export async function wipeVault(): Promise<void> {
  await deleteDB();
}

// ─────────────────────────────────  OpenVault (instance API)  ─────────────
export class OpenVault {
  readonly secure:   SecureStore;
  readonly settings: SettingsStore;
  readonly configs:  ConfigsStore;
  readonly channels: ChannelsStore;
  readonly history:  HistoryStore;
  readonly reports:  ReportsStore;

  constructor(db: VelesDB, key: CryptoKey) {
    // db і key зберігаються лише в підстворах — OpenVault їх більше не використовує
    this.secure   = new SecureStore(db, key);
    this.settings = new SettingsStore(db, key);
    this.configs  = new ConfigsStore(db, key);
    this.channels = new ChannelsStore(db, key);
    this.history  = new HistoryStore(db, key);
    this.reports  = new ReportsStore(db, key);
  }

  /** Очистити лише сесію (logout без видалення налаштувань/історії). */
  async logout(): Promise<void> {
    await this.secure.clearSession();
    await this.secure.clearApiCreds();
  }
}

// ─────────────────────────────────  SecureStore  ──────────────────────────
class SecureStore {
  constructor(private db: VelesDB, private key: CryptoKey) {}

  async getSession(): Promise<string | null> {
    const blob = await this.db.get('secure', SECURE_SESSION);
    if (!blob) return null;
    return decryptJson<string>(this.key, blob);
  }

  async setSession(session: string): Promise<void> {
    const blob = await encryptJson(this.key, session);
    await this.db.put('secure', blob, SECURE_SESSION);
  }

  async clearSession(): Promise<void> {
    await this.db.delete('secure', SECURE_SESSION);
  }

  async getApiCreds(): Promise<ApiCreds | null> {
    const blob = await this.db.get('secure', SECURE_API_CREDS);
    if (!blob) return null;
    return decryptJson<ApiCreds>(this.key, blob);
  }

  async setApiCreds(creds: ApiCreds): Promise<void> {
    const blob = await encryptJson(this.key, creds);
    await this.db.put('secure', blob, SECURE_API_CREDS);
  }

  async clearApiCreds(): Promise<void> {
    await this.db.delete('secure', SECURE_API_CREDS);
  }
}

// ─────────────────────────────────  SettingsStore  ────────────────────────
class SettingsStore {
  constructor(private db: VelesDB, private key: CryptoKey) {}

  async get(): Promise<AppSettings> {
    const blob = await this.db.get('settings', SETTINGS_APP);
    if (!blob) return DEFAULT_SETTINGS;
    const stored = await decryptJson<AppSettings>(this.key, blob);
    // Зливаємо з дефолтами, щоб нові поля (напр. accuracy) мали значення
    // навіть для збережених раніше налаштувань.
    return { ...DEFAULT_SETTINGS, ...stored };
  }

  async set(settings: AppSettings): Promise<void> {
    const blob = await encryptJson(this.key, settings);
    await this.db.put('settings', blob, SETTINGS_APP);
  }

  async update(patch: Partial<AppSettings>): Promise<AppSettings> {
    const current = await this.get();
    const next: AppSettings = {
      ...current,
      ...patch,
      notifications: { ...current.notifications, ...(patch.notifications ?? {}) },
      monitoring:    { ...current.monitoring,    ...(patch.monitoring ?? {}) },
      ui:            { ...current.ui,            ...(patch.ui ?? {}) },
      media:         { ...current.media,         ...(patch.media ?? {}) },
      labelling:     { ...(current.labelling ?? { enabled: false }), ...(patch.labelling ?? {}) }
    };
    await this.set(next);
    return next;
  }
}

// ─────────────────────────────────  ConfigsStore  ─────────────────────────
class ConfigsStore {
  constructor(private db: VelesDB, private key: CryptoKey) {}

  async list(): Promise<MonitoringConfig[]> {
    const blobs = await this.db.getAll('configs');
    const out: MonitoringConfig[] = [];
    for (const b of blobs) {
      out.push(await decryptJson<MonitoringConfig>(this.key, b));
    }
    return out.sort((a, b) => b.updatedAt - a.updatedAt);
  }

  async get(id: string): Promise<MonitoringConfig | null> {
    const blob = await this.db.get('configs', id);
    return blob ? decryptJson<MonitoringConfig>(this.key, blob) : null;
  }

  async upsert(cfg: MonitoringConfig): Promise<void> {
    const blob = await encryptJson(this.key, cfg);
    await this.db.put('configs', blob, cfg.id);
  }

  async delete(id: string): Promise<void> {
    await this.db.delete('configs', id);
  }
}

// ─────────────────────────────────  ChannelsStore  ────────────────────────
class ChannelsStore {
  constructor(private db: VelesDB, private key: CryptoKey) {}

  async list(): Promise<MonitoredChannel[]> {
    const blobs = await this.db.getAll('channels');
    const out: MonitoredChannel[] = [];
    for (const b of blobs) {
      out.push(await decryptJson<MonitoredChannel>(this.key, b));
    }
    return out.sort((a, b) => a.title.localeCompare(b.title, 'uk'));
  }

  async upsert(ch: MonitoredChannel): Promise<void> {
    const blob = await encryptJson(this.key, ch);
    await this.db.put('channels', blob, ch.id);
  }

  async delete(id: string): Promise<void> {
    await this.db.delete('channels', id);
  }

  async setMany(items: MonitoredChannel[]): Promise<void> {
    const tx = this.db.transaction('channels', 'readwrite');
    await tx.store.clear();
    for (const ch of items) {
      const blob = await encryptJson(this.key, ch);
      await tx.store.put(blob, ch.id);
    }
    await tx.done;
  }
}

// ─────────────────────────────────  HistoryStore  ─────────────────────────
const HISTORY_LIMIT = 500;

class HistoryStore {
  constructor(private db: VelesDB, private key: CryptoKey) {}

  async append(post: FoundPost): Promise<void> {
    const id = `${post.postedAt}_${post.channelId}_${post.messageId}`;
    const blob = await encryptJson(this.key, post);
    await this.db.put('history', blob, id);

    // Тримаємо ліміт: видаляємо найдавніші, якщо перевищили
    const keys = await this.db.getAllKeys('history');
    if (keys.length > HISTORY_LIMIT) {
      const sorted = (keys as string[]).sort();
      const toRemove = sorted.slice(0, keys.length - HISTORY_LIMIT);
      const tx = this.db.transaction('history', 'readwrite');
      for (const k of toRemove) await tx.store.delete(k);
      await tx.done;
    }
  }

  async list(): Promise<FoundPost[]> {
    const blobs = await this.db.getAll('history');
    const out: FoundPost[] = [];
    for (const b of blobs) {
      out.push(await decryptJson<FoundPost>(this.key, b));
    }
    return out.sort((a, b) => b.postedAt - a.postedAt);
  }

  async clear(): Promise<void> {
    const tx = this.db.transaction('history', 'readwrite');
    await tx.store.clear();
    await tx.done;
  }
}

// ─────────────────────────────────  ReportsStore  ─────────────────────────
class ReportsStore {
  constructor(private db: VelesDB, private key: CryptoKey) {}

  async save(report: StanceReport): Promise<string> {
    const id = `${report.analyzedAt}_${btoa(report.postUrl).slice(0, 16)}`;
    const blob = await encryptJson(this.key, report);
    await this.db.put('reports', blob, id);
    return id;
  }

  async list(): Promise<StanceReport[]> {
    const blobs = await this.db.getAll('reports');
    const out: StanceReport[] = [];
    for (const b of blobs) {
      out.push(await decryptJson<StanceReport>(this.key, b));
    }
    return out.sort((a, b) => b.analyzedAt - a.analyzedAt);
  }

  async get(id: string): Promise<StanceReport | null> {
    const blob = await this.db.get('reports', id);
    return blob ? decryptJson<StanceReport>(this.key, blob) : null;
  }

  async delete(id: string): Promise<void> {
    await this.db.delete('reports', id);
  }

  async clear(): Promise<void> {
    const tx = this.db.transaction('reports', 'readwrite');
    await tx.store.clear();
    await tx.done;
  }
}
