/**
 * IndexedDB-схема Veles Monitor.
 *
 * База:    veles-monitor
 * Версія:  1
 *
 * Stores:
 *   meta       — несекретні службові поля (salt, kdf-параметри, версія схеми)
 *   secure     — Telegram-сесія + api_id/api_hash (зашифровано)
 *   settings   — налаштування користувача (зашифровано)
 *   configs    — збережені конфігурації моніторингу (зашифровано, key = id)
 *   channels   — обрані для моніторингу канали (зашифровано, key = id)
 *   history    — історія знайдених публікацій (зашифровано, key = generated id)
 *   reports    — звіти аналізу коментарів (зашифровано, key = generated id)
 */

import { openDB as openIdb, type IDBPDatabase, type DBSchema } from 'idb';

export const DB_NAME = 'veles-monitor';
export const DB_VERSION = 1;

export interface VelesDBSchema extends DBSchema {
  meta: {
    key: string;
    value: unknown;
  };
  secure: {
    key: string;
    value: Uint8Array;
  };
  settings: {
    key: string;
    value: Uint8Array;
  };
  configs: {
    key: string;
    value: Uint8Array;
  };
  channels: {
    key: string;
    value: Uint8Array;
  };
  history: {
    key: string;
    value: Uint8Array;
  };
  reports: {
    key: string;
    value: Uint8Array;
  };
}

export type VelesDB = IDBPDatabase<VelesDBSchema>;

let dbPromise: Promise<VelesDB> | null = null;

/**
 * Відкрити (або створити) базу. Кешується глобально.
 */
export function openDB(): Promise<VelesDB> {
  if (dbPromise) return dbPromise;
  dbPromise = openIdb<VelesDBSchema>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('meta'))     db.createObjectStore('meta');
      if (!db.objectStoreNames.contains('secure'))   db.createObjectStore('secure');
      if (!db.objectStoreNames.contains('settings')) db.createObjectStore('settings');
      if (!db.objectStoreNames.contains('configs'))  db.createObjectStore('configs');
      if (!db.objectStoreNames.contains('channels')) db.createObjectStore('channels');
      if (!db.objectStoreNames.contains('history'))  db.createObjectStore('history');
      if (!db.objectStoreNames.contains('reports'))  db.createObjectStore('reports');
    },
    blocked() {
      // eslint-disable-next-line no-console
      console.warn('[IDB] DB blocked — інша вкладка тримає стару версію');
    },
    blocking() {
      // Закриваємо своє з'єднання, щоб інша вкладка могла оновитись
      void closeDB();
    },
    terminated() {
      // eslint-disable-next-line no-console
      console.warn('[IDB] DB connection terminated unexpectedly');
      dbPromise = null;
    }
  });
  return dbPromise;
}

/**
 * Закрити та забути з'єднання (для wipe чи перевідкриття).
 */
export async function closeDB(): Promise<void> {
  if (!dbPromise) return;
  const db = await dbPromise;
  db.close();
  dbPromise = null;
}

/**
 * Повне знесення бази (для «Очистити все»/«Забув пароль»).
 */
export async function deleteDB(): Promise<void> {
  await closeDB();
  await new Promise<void>((resolve, reject) => {
    const req = indexedDB.deleteDatabase(DB_NAME);
    req.onsuccess = () => resolve();
    req.onerror   = () => reject(req.error);
    req.onblocked = () => {
      // eslint-disable-next-line no-console
      console.warn('[IDB] deleteDB blocked');
    };
  });
}
