/**
 * Витяг коментарів під постом каналу.
 *
 * У Telegram коментарі живуть у привʼязаній discussion-групі.
 * gram.js обгортка iterMessages(channel, {replyTo: msgId}) робить це автоматично.
 */

import { getTelegramClient } from './client';
import { resolvePostPeer } from './channels';
import type { TelegramPostRef } from './url-parser';

export interface RawComment {
  id: number;
  authorId?: number;
  authorName?: string;
  text: string;
  postedAt: number;       // unix ms
  hasMedia: boolean;
}

export interface FetchedPostBundle {
  postText: string;
  postAuthor: string;     // назва каналу
  comments: RawComment[];
}

export interface CommentFetchProgress {
  fetched: number;
  estimated?: number;
}

/**
 * Витягнути пост і всі його коментарі.
 *
 * @param ref      — посилання на пост
 * @param onChunk  — викликається з пакетом нових коментарів (по 100) для прогресу
 * @param signal   — для скасування
 */
export async function fetchPostAndComments(
  ref: TelegramPostRef,
  onChunk?: (progress: CommentFetchProgress) => void,
  signal?: AbortSignal
): Promise<FetchedPostBundle> {
  const client = await getTelegramClient();
  const peer = await resolvePostPeer(ref);

  // 1) Отримати сам пост
  const postMessages = await client.getMessages(peer, { ids: [ref.messageId] });
  const post = postMessages?.[0];
  if (!post) {
    throw new Error('Пост не знайдено або він видалений');
  }

  const postAuthor = peer.title ?? peer.username ?? '(без назви)';
  const postText = post.message ?? post.text ?? '';

  // 2) Перевірити чи є коментарі взагалі (linked discussion group)
  // iterMessages з replyTo=ref.messageId автоматично перейде в discussion group.
  const comments: RawComment[] = [];
  let count = 0;
  let lastReported = 0;

  try {
    for await (const c of client.iterMessages(peer, {
      replyTo: ref.messageId,
      reverse: true,           // спочатку найстаріші
      limit: undefined         // без ліміту, користувач хоче «брати все»
    })) {
      if (signal?.aborted) break;
      if (!c) continue;
      const text = c.message ?? c.text ?? '';
      if (!text && !c.media) continue;     // порожнє (службове) повідомлення — скіп

      comments.push({
        id: c.id,
        authorId: c.fromId?.userId ? Number(c.fromId.userId.toString?.()) : undefined,
        authorName: extractAuthorName(c),
        text,
        postedAt: (c.date ?? 0) * 1000,
        hasMedia: !!c.media
      });
      count++;
      if (count - lastReported >= 50) {
        lastReported = count;
        onChunk?.({ fetched: count });
      }
    }
  } catch (err: any) {
    const msg = String(err?.message ?? err);
    // У Telegram канал може не мати linked discussion — у такому разі ловимо специфічну помилку.
    if (/MSG_ID_INVALID|CHAT_INVALID|PEER_ID_INVALID|no discussion/i.test(msg)) {
      // повертаємо порожній список — не помилка, просто немає коментарів
    } else {
      throw err;
    }
  }

  onChunk?.({ fetched: comments.length });
  return { postText, postAuthor, comments };
}

function extractAuthorName(msg: any): string | undefined {
  const sender = msg.sender;
  if (!sender) return undefined;
  if (sender.firstName || sender.lastName) {
    return [sender.firstName, sender.lastName].filter(Boolean).join(' ');
  }
  return sender.title ?? sender.username;
}
