/**
 * Stance-класифікація коментарів.
 *
 *   premise   = текст оригінального поста
 *   labels    = [support, oppose, unrelated]
 *   hypothesis-template = 'Автор коментаря {} з позицією поста.'
 *
 * Для довгих постів — використовуємо першу частину (до 256 слів),
 * бо premise має поміщатися в контекст моделі.
 */

import { cleanText, chunkText } from '../text-utils';
import { loadNli, type NliApi } from './nli';
import type { Stance } from '../../../types';
import type { ProgressCallback } from '../progress';
import { getActiveProfile, type AccuracyProfile } from '../accuracy';

export interface StanceResult {
  stance: Stance;
  scores: { support: number; oppose: number; unrelated: number };
}

// Лейбли, які подаються в NLI; ключі мапаються на внутрішній Stance.
const STANCE_LABELS = {
  support:   'погоджується',
  oppose:    'спростовує або критикує',
  unrelated: 'не стосується теми'
} as const;

const HYPOTHESIS_TEMPLATE = 'Автор коментаря {} з позицією, висловленою в публікації.';
const HYPOTHESIS_TEMPLATE_ALT = 'Щодо думки в публікації, автор коментаря {}.';

export async function classifyStance(
  postText: string,
  commentText: string,
  nli?: NliApi,
  onProgress?: ProgressCallback,
  profile: AccuracyProfile = getActiveProfile()
): Promise<StanceResult> {
  const post = cleanText(postText);
  const comment = cleanText(commentText);
  const model = nli ?? await loadNli(onProgress);

  // Premise містить і пост, і коментар (для контексту), розділені сепаратором.
  const postShort = chunkText(post, 220)[0] ?? '';
  const premise = `Публікація: ${postShort}\nКоментар: ${comment}`;
  const labelList = [STANCE_LABELS.support, STANCE_LABELS.oppose, STANCE_LABELS.unrelated];

  const runOnce = async (tmpl: string) => {
    const res = await model.classify(premise, labelList, { hypothesisTemplate: tmpl, multiLabel: false });
    const pick = (label: string): number => {
      const i = res.labels.findIndex(l => l === label);
      return i >= 0 ? res.scores[i] : 0;
    };
    return {
      support:   pick(STANCE_LABELS.support),
      oppose:    pick(STANCE_LABELS.oppose),
      unrelated: pick(STANCE_LABELS.unrelated)
    };
  };

  let scores = await runOnce(HYPOTHESIS_TEMPLATE);

  // Повторна перевірка: якщо дві верхні мітки близькі (неоднозначно) — або завжди
  // в ensemble-режимі — додаємо прохід з іншим формулюванням і усереднюємо.
  const ranked = [scores.support, scores.oppose, scores.unrelated].sort((a, b) => b - a);
  const ambiguous = ranked[0] - ranked[1] < 0.15;
  if (profile.stanceEnsemble || (profile.stanceRecheck && ambiguous)) {
    const alt = await runOnce(HYPOTHESIS_TEMPLATE_ALT);
    scores = {
      support:   (scores.support + alt.support) / 2,
      oppose:    (scores.oppose + alt.oppose) / 2,
      unrelated: (scores.unrelated + alt.unrelated) / 2
    };
  }

  // Stance = мітка з найвищим score
  let stance: Stance = 'unrelated';
  if (scores.support > scores.oppose && scores.support > scores.unrelated)      stance = 'support';
  else if (scores.oppose > scores.support && scores.oppose > scores.unrelated)  stance = 'oppose';

  return { stance, scores };
}

/**
 * Batch-варіант — обробити багато коментарів послідовно з прогресом.
 */
export async function classifyStanceBatch(
  postText: string,
  comments: { id: number; text: string }[],
  onProgress?: (done: number, total: number) => void,
  signal?: AbortSignal,
  nli?: NliApi
): Promise<Map<number, StanceResult>> {
  const model = nli ?? await loadNli();
  const out = new Map<number, StanceResult>();
  let i = 0;
  for (const c of comments) {
    if (signal?.aborted) break;
    const r = await classifyStance(postText, c.text, model);
    out.set(c.id, r);
    i++;
    onProgress?.(i, comments.length);
  }
  return out;
}
