/**
 * Lock-screen — показується при кожному відкритті, якщо vault уже існує.
 *
 * Користувач:
 *  - вводить пароль → unlock → перехід у основний застосунок
 *  - або тисне «Забув пароль» → confirm → wipeVault → onboarding з нуля
 */

import { html, raw } from '../shared/dom';
import { icons } from '../shared/icons';
import { confirm } from '../shared/modal';
import { toast } from '../shared/toast';
import { unlockVault, wipeVault } from '../../core/storage/vault';
import { strings } from '../../i18n/uk';
import type { OpenVault } from '../../core/storage/vault';

export interface LockScreenApi {
  el: HTMLElement;
  onUnlocked(handler: (vault: OpenVault) => void): void;
  onWiped(handler: () => void): void;
}

export function buildLockScreen(): LockScreenApi {
  const root = html`
    <div class="app-main">
      <section class="page" style="max-width: 460px;">
        <header class="page-header" style="border: none; padding-bottom: 0;">
          <div>
            <div class="page-eyebrow">vault · locked</div>
            <h1 class="page-title">Розблокування</h1>
          </div>
          <div style="color: var(--accent);">${raw(icons.lock(28).value)}</div>
        </header>

        <div class="panel">
          <div class="text-secondary" style="margin-bottom: 20px;">
            Введіть пароль для розшифрування Telegram-сесії та налаштувань. Пароль не зберігається —
            при закритті вкладки потрібно буде ввести знову.
          </div>

          <form data-vm-unlock class="col gap-4">
            <div class="field">
              <label class="field-label" for="vm-password">Пароль</label>
              <input
                type="password"
                id="vm-password"
                class="input input-mono"
                placeholder="••••••••"
                autocomplete="current-password"
                autofocus
                required
                minlength="6"
              />
              <div class="field-error hidden" data-vm-error></div>
            </div>

            <button type="submit" class="btn btn-primary btn-lg btn-block" data-vm-submit>
              ${raw(icons.power(16).value)}
              <span>Розблокувати</span>
            </button>
          </form>
        </div>

        <div class="row between" style="font-size: var(--fs-sm);">
          <button class="btn btn-ghost btn-sm" data-vm-forgot>
            Забули пароль?
          </button>
          <span class="text-muted text-mono" style="font-size: var(--fs-xs); letter-spacing: var(--tracking-widest); text-transform: uppercase;">
            AES-GCM 256 · PBKDF2
          </span>
        </div>
      </section>
    </div>
  `;

  const form     = root.querySelector<HTMLFormElement>('[data-vm-unlock]')!;
  const passEl   = root.querySelector<HTMLInputElement>('#vm-password')!;
  const errEl    = root.querySelector<HTMLElement>('[data-vm-error]')!;
  const submitEl = root.querySelector<HTMLButtonElement>('[data-vm-submit]')!;
  const forgotEl = root.querySelector<HTMLButtonElement>('[data-vm-forgot]')!;

  const unlockedHandlers: Array<(v: OpenVault) => void> = [];
  const wipedHandlers: Array<() => void> = [];

  const showError = (msg: string | null) => {
    if (msg) {
      errEl.textContent = msg;
      errEl.classList.remove('hidden');
    } else {
      errEl.classList.add('hidden');
    }
  };

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    showError(null);
    const password = passEl.value;
    if (!password) return;

    submitEl.disabled = true;
    submitEl.querySelector('span')!.textContent = 'Розшифровуємо…';

    try {
      const vault = await unlockVault(password);
      if (!vault) {
        showError('Невірний пароль');
        passEl.select();
        return;
      }
      unlockedHandlers.forEach(h => h(vault));
    } catch (err) {
      // eslint-disable-next-line no-console
      console.error('[unlock] failed:', err);
      showError(`Помилка: ${(err as Error).message}`);
    } finally {
      submitEl.disabled = false;
      submitEl.querySelector('span')!.textContent = 'Розблокувати';
    }
  });

  forgotEl.addEventListener('click', async () => {
    const ok = await confirm({
      title: 'Очистити всі дані?',
      body: 'Telegram-сесія, налаштування, історія і збережені звіти — все буде безповоротно видалено. Після цього доведеться пройти onboarding з нуля. Продовжити?',
      confirmLabel: 'Так, очистити все',
      cancelLabel: 'Скасувати',
      danger: true
    });
    if (!ok) return;
    try {
      await wipeVault();
      toast.success(strings.toast.sessionCleared);
      wipedHandlers.forEach(h => h());
    } catch (err) {
      toast.error(`Не вдалося очистити: ${(err as Error).message}`);
    }
  });

  return {
    el: root,
    onUnlocked(h) { unlockedHandlers.push(h); },
    onWiped(h)    { wipedHandlers.push(h); }
  };
}
