/**
 * Кореневий компонент застосунку.
 *
 * Boot-флоу:
 *   1. Показуємо splash на ~650 мс (брендинг)
 *   2. Запитуємо vaultStatus():
 *        'empty'  → Welcome → SetPassword → demo-session → Main shell
 *        'locked' → LockScreen → Main shell
 *   3. Main shell: header + tabs + переключення між Моніторинг / Коментарі / Налаштування
 *
 * У Phase 2 реальний onboarding (api_id/телефон/код/2FA/канали) ще не написаний,
 * але vault + lock-screen уже працюють — після першого встановлення пароля
 * vault зберігає демо-рядок «session», далі lock-screen вимагатиме пароль для входу.
 */

import { html, mount } from './ui/shared/dom';
import { buildHeader, type HeaderApi } from './ui/shared/header';
import { buildTabs, type TabsApi } from './ui/shared/tabs';
import { buildSplash } from './ui/shared/splash';
import { buildWelcomePage } from './ui/onboarding/welcome';
import { buildSetPasswordScreen } from './ui/onboarding/set-password';
import { buildLockScreen } from './ui/onboarding/lock-screen';
import { buildOnboardingWizard } from './ui/onboarding/wizard';
import { getMe } from './core/telegram';
import { buildMonitoringPage } from './ui/monitoring/monitoring-page';
import { buildCommentsPage } from './ui/comments/comments-page';
import { buildCalibrationPage } from './ui/calibration/calibration-page';
import { buildSettingsPage } from './ui/settings/settings-page';
import { toast } from './ui/shared/toast';
import { vaultStatus, type OpenVault } from './core/storage/vault';
import { setVault } from './core/storage/current-vault';
import { setupNotificationsBridge } from './core/monitoring/notifications-bridge';
import { setLabellingEnabled } from './core/calibration';
import { strings } from './i18n/uk';
import type { PageName } from './types';

interface AppState {
  page: PageName;
}

class App {
  private root: HTMLElement;
  private state: AppState = { page: 'monitoring' };

  private header?: HeaderApi;
  private tabs?: TabsApi;
  private shellEl?: HTMLElement;
  private mainEl?: HTMLElement;

  constructor(root: HTMLElement) {
    this.root = root;
  }

  async start(): Promise<void> {
    const splash = buildSplash();
    mount(this.root, splash.el);
    await new Promise(r => setTimeout(r, 650));
    await splash.hide();

    try {
      const status = await vaultStatus();
      if (status === 'empty') {
        this.renderWelcome();
      } else {
        this.renderLockScreen();
      }
    } catch (err) {
      toast.error(`Помилка ініціалізації: ${(err as Error).message}`);
      this.renderWelcome();
    }
  }

  // ───────────  Onboarding flow (Phase 2 + 4)  ─────────────
  private renderWelcome(): void {
    const welcome = buildWelcomePage();
    welcome.onComplete(() => this.renderSetPassword());
    mount(this.root, welcome.el);
  }

  private renderSetPassword(): void {
    const setpw = buildSetPasswordScreen();
    setpw.onBack(() => this.renderWelcome());
    setpw.onCreated((vault) => {
      setVault(vault);
      this.renderOnboardingWizard(vault);
    });
    mount(this.root, setpw.el);
  }

  private renderOnboardingWizard(vault: OpenVault): void {
    const wizard = buildOnboardingWizard();
    wizard.onFinished(() => {
      this.renderMain(vault);
    });
    mount(this.root, wizard.el);
  }

  private renderLockScreen(): void {
    const lock = buildLockScreen();
    lock.onUnlocked(async (vault) => {
      setVault(vault);
      // Якщо у vault уже є api-creds + сесія — одразу головний застосунок.
      // Якщо ні (наприклад, попередній onboarding обірвано) — повертаємо в wizard.
      const creds = await vault.secure.getApiCreds();
      const session = await vault.secure.getSession();
      if (creds && session) {
        this.renderMain(vault);
      } else {
        toast.warning('Onboarding не був завершений — продовжуємо налаштування');
        this.renderOnboardingWizard(vault);
      }
    });
    lock.onWiped(() => this.renderWelcome());
    mount(this.root, lock.el);
  }

  // ───────────  Main shell  ─────────────
  private renderMain(_vault: OpenVault): void {
    this.header = buildHeader();
    this.tabs = buildTabs();
    this.mainEl = html`<main class="app-main"></main>`;

    this.shellEl = html`<div style="display:flex; flex-direction:column; height:100%;"></div>`;
    this.shellEl.appendChild(this.header.el);
    this.shellEl.appendChild(this.tabs.el);
    this.shellEl.appendChild(this.mainEl);

    mount(this.root, this.shellEl);

    this.tabs.onChange((p) => this.goTo(p));
    this.header.setStatus('online');

    // Notifications bridge (browser notif + favicon badge)
    setupNotificationsBridge();

    // Calibration: підвантажуємо стан labelling-мод з settings (зберігається у vault)
    void _vault.settings.get().then((s) => {
      setLabellingEnabled(s.labelling?.enabled === true);
    }).catch(() => { /* silent */ });

    // Підтягуємо реальні дані поточного користувача
    void getMe().then((u) => {
      if (u) {
        const fullName = [u.firstName, u.lastName].filter(Boolean).join(' ') || (u.username ?? 'Operator');
        this.header?.setUser({ name: fullName, phone: u.phone });
      }
    }).catch(() => { /* silent — UI просто залишиться без user-блоку */ });

    this.goTo(this.state.page);
    toast.success(`${strings.app.name} ${strings.app.version} готовий`);
  }

  private goTo(page: PageName): void {
    if (!this.mainEl || !this.tabs) return;
    this.state.page = page;
    this.tabs.setActive(page);

    let pageEl: HTMLElement;
    switch (page) {
      case 'monitoring':  pageEl = buildMonitoringPage();  break;
      case 'comments':    pageEl = buildCommentsPage();    break;
      case 'calibration': pageEl = buildCalibrationPage(); break;
      case 'settings':    pageEl = buildSettingsPage();    break;
    }
    mount(this.mainEl, pageEl);
  }
}

export function startApp(root: HTMLElement): App {
  const app = new App(root);
  void app.start();
  return app;
}
