/**
 * Профілі "Точність визначення" для гібридного AI (e5-small + mDeBERTa-NLI).
 *
 * Три режими — компроміс швидкість ↔ точність:
 *   1 "Швидко"               — мінімум навантаження, один прохід;
 *   2 "Збалансовано"         — за замовчуванням;
 *   3 "Максимальна точність" — усі нюанси: фрагменти, ансамбль формулювань, перевірка.
 *
 * Гібридні функції зчитують активний профіль через getActiveProfile().
 */

import type { AccuracyLevel } from '../../types';

export interface AccuracyProfile {
  level: AccuracyLevel;
  label: string;
  description: string;

  // ── Тема (NLI zero-shot, multiLabel: true) ──
  /** Поріг абсолютної entailment-впевненості. */
  topicThreshold: number;
  /** Розмір фрагмента в словах. */
  topicChunkSize: number;
  /** Максимум фрагментів для аналізу. */
  topicMaxChunks: number;
  /** Ансамбль із кількох формулювань гіпотези (стабільніше, повільніше). */
  topicEnsemble: boolean;
  /** Контрастна перевірка ("НЕ про тему") для відсіву хибних спрацювань. */
  topicRecheck: boolean;

  // ── Слова (embeddings cosine) ──
  wordsThreshold: number;

  // ── Стенс коментарів ──
  /** Додатковий прохід при неоднозначності. */
  stanceRecheck: boolean;
  /** Завжди усереднювати два формулювання. */
  stanceEnsemble: boolean;
}

const PROFILES: Record<AccuracyLevel, AccuracyProfile> = {
  1: {
    level: 1,
    label: 'Швидко',
    description: 'Один швидкий прохід по початку тексту. Мінімум навантаження — для слабких пристроїв і великого потоку.',
    topicThreshold: 0.34,
    topicChunkSize: 384,
    topicMaxChunks: 1,
    topicEnsemble: false,
    topicRecheck: false,
    wordsThreshold: 0.79,
    stanceRecheck: false,
    stanceEnsemble: false
  },
  2: {
    level: 2,
    label: 'Збалансовано',
    description: 'За замовчуванням. Аналізує до двох фрагментів тексту і перевіряє неоднозначні коментарі.',
    topicThreshold: 0.32,
    topicChunkSize: 320,
    topicMaxChunks: 2,
    topicEnsemble: false,
    topicRecheck: false,
    wordsThreshold: 0.78,
    stanceRecheck: true,
    stanceEnsemble: false
  },
  3: {
    level: 3,
    label: 'Максимальна точність',
    description: 'Усі нюанси: багато фрагментів, ансамбль формулювань і контрольна перевірка. Найточніше, але повільніше й більше навантаження.',
    topicThreshold: 0.30,
    topicChunkSize: 224,
    topicMaxChunks: 4,
    topicEnsemble: true,
    topicRecheck: true,
    wordsThreshold: 0.76,
    stanceRecheck: true,
    stanceEnsemble: true
  }
};

/** Усі профілі по порядку — для рендеру повзунка. */
export const ACCURACY_PROFILES: AccuracyProfile[] = [
  PROFILES[1], PROFILES[2], PROFILES[3]
];

export function getAccuracyProfile(level: AccuracyLevel): AccuracyProfile {
  return PROFILES[level] ?? PROFILES[2];
}

let active: AccuracyProfile = PROFILES[2];

/** Встановити активний профіль (з налаштувань / при старті моніторингу). */
export function setActiveAccuracy(level: AccuracyLevel): void {
  active = getAccuracyProfile(level);
}

/** Поточний активний профіль — його читають гібридні функції. */
export function getActiveProfile(): AccuracyProfile {
  return active;
}
