/**
 * Tabs-навігація між головними сторінками.
 */

import { html } from './dom';
import { icons, type IconName } from './icons';
import { strings } from '../../i18n/uk';
import type { PageName } from '../../types';

export interface TabsApi {
  el: HTMLElement;
  setActive(page: PageName): void;
  onChange(handler: (page: PageName) => void): void;
}

interface TabDef {
  id: PageName;
  label: string;
  icon: IconName;
}

const TABS: TabDef[] = [
  { id: 'monitoring',  label: strings.tabs.monitoring,  icon: 'radar' },
  { id: 'comments',    label: strings.tabs.comments,    icon: 'comments' },
  { id: 'calibration', label: strings.tabs.calibration, icon: 'scope' },
  { id: 'settings',    label: strings.tabs.settings,    icon: 'settings' }
];

export function buildTabs(): TabsApi {
  const root = html`<nav class="app-tabs" role="tablist"></nav>`;
  const handlers: Array<(p: PageName) => void> = [];

  const buttons = new Map<PageName, HTMLElement>();

  for (const t of TABS) {
    const btn = html`
      <button class="app-tab" role="tab" data-vm-tab="${t.id}" aria-controls="page-${t.id}">
        <span>${icons[t.icon](14)}</span>
        <span>${t.label}</span>
      </button>
    `;
    btn.addEventListener('click', () => {
      handlers.forEach(h => h(t.id));
    });
    buttons.set(t.id, btn);
    root.appendChild(btn);
  }

  return {
    el: root,
    setActive(page) {
      for (const [id, btn] of buttons.entries()) {
        btn.classList.toggle('active', id === page);
        btn.setAttribute('aria-selected', String(id === page));
      }
    },
    onChange(handler) {
      handlers.push(handler);
    }
  };
}
