/**
 * Підсвічування знайдених збігів у тексті повідомлення.
 * Виводить HTML-рядок з <mark>...</mark> навколо знайдених слів/фраз.
 */

const SPECIAL = /[.*+?^${}()|[\]\\]/g;
function escapeRegex(s: string): string {
  return s.replace(SPECIAL, '\\$&');
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Підсвітити масив слів/фраз. Не дбає про лематизацію — лише точне співпадіння
 * (для embedding-режиму UI отримує matchedWord з matchByWords результату).
 */
export function highlightHtml(text: string, terms: string[]): string {
  if (!text) return '';
  if (terms.length === 0) return escapeHtml(text);

  // Сортуємо за спаданням довжини, щоб довші фрази мали пріоритет.
  const sorted = [...new Set(terms.filter(Boolean))].sort((a, b) => b.length - a.length);
  const pattern = new RegExp('(' + sorted.map(escapeRegex).join('|') + ')', 'gi');

  return escapeHtml(text).replace(pattern, '<mark class="vm-mark">$1</mark>');
}
