/**
 * Donut-діаграма розподілу stance, на чистому SVG.
 */

import { raw, type TrustedHtml } from '../shared/dom';
import type { StanceReport } from '../../types';

export interface ChartOptions {
  size?: number;
  strokeWidth?: number;
}

export function buildStanceChart(
  report: Pick<StanceReport, 'percentages' | 'totalComments'>,
  opts: ChartOptions = {}
): TrustedHtml {
  const size = opts.size ?? 220;
  const sw = opts.strokeWidth ?? 28;
  const r = (size - sw) / 2;
  const c = 2 * Math.PI * r;
  const cx = size / 2;
  const cy = size / 2;

  const { support, oppose, unrelated } = report.percentages;
  // нормалізація на випадок плаваючої арифметики
  const total = Math.max(1, support + oppose + unrelated);
  const s = (support   / total) * 100;
  const o = (oppose    / total) * 100;
  const u = (unrelated / total) * 100;

  const seg = (offsetPct: number, lenPct: number, color: string) => {
    const dash = (lenPct / 100) * c;
    const gap  = c - dash;
    const rot  = -90 + (offsetPct / 100) * 360;
    return `<circle
      cx="${cx}" cy="${cy}" r="${r}" fill="none"
      stroke="${color}" stroke-width="${sw}"
      stroke-dasharray="${dash} ${gap}"
      transform="rotate(${rot} ${cx} ${cy})"
    />`;
  };

  return raw(`
    <svg viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" aria-label="Stance розподіл">
      <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="var(--bg-elevated)" stroke-width="${sw}"/>
      ${seg(0,       s,     'var(--stance-support)')}
      ${seg(s,       o,     'var(--stance-oppose)')}
      ${seg(s + o,   u,     'var(--stance-unrelated)')}
      <text x="${cx}" y="${cy - 6}" text-anchor="middle" fill="var(--fg-primary)"
            font-family="var(--font-mono)" font-size="${size * 0.18}" font-weight="700">
        ${report.totalComments}
      </text>
      <text x="${cx}" y="${cy + size * 0.10}" text-anchor="middle" fill="var(--fg-muted)"
            font-family="var(--font-mono)" font-size="${size * 0.06}"
            letter-spacing="2" text-transform="uppercase">
        КОМЕНТАРІВ
      </text>
    </svg>
  `);
}
