/**
 * Маленький набір DOM-утиліт.
 * Не реактивний, не віртуальний DOM — пряме створення Element-вузлів.
 *
 * - `html\`<div>...\`` — швидко зробити DOM-елемент із літералу
 * - `raw(str)`         — позначити рядок як довірений HTML (для іконок тощо)
 * - `mount(parent, child)` — очистити батька і вставити нового
 * - `on(el, event, handler)` — додати слухача з cleanup-функцією
 */

const TRUSTED = Symbol('trusted-html');

export interface TrustedHtml {
  readonly [TRUSTED]: true;
  readonly value: string;
}

export function raw(value: string): TrustedHtml {
  return { [TRUSTED]: true, value };
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderValue(v: unknown): string {
  if (v == null || v === false || v === true) return '';
  if (typeof v === 'string' || typeof v === 'number') return escapeHtml(String(v));
  if (Array.isArray(v)) return v.map(renderValue).join('');
  if (typeof v === 'object' && TRUSTED in (v as object)) {
    return (v as TrustedHtml).value;
  }
  return escapeHtml(String(v));
}

/**
 * Tagged-template для створення DOM-елементу.
 * Інтерполяції автоматично екрануються; для довіреного HTML використовуйте raw().
 */
export function html(strings: TemplateStringsArray, ...values: unknown[]): HTMLElement {
  let out = '';
  strings.forEach((part, i) => {
    out += part;
    if (i < values.length) out += renderValue(values[i]);
  });
  const tpl = document.createElement('template');
  tpl.innerHTML = out.trim();
  const first = tpl.content.firstElementChild;
  if (!first) {
    throw new Error('html`` produced empty DOM');
  }
  return first as HTMLElement;
}

/**
 * Очистити батьківський контейнер і вставити нового дитину (або фрагмент).
 */
export function mount(parent: Element, child: Element | DocumentFragment | null): void {
  parent.replaceChildren();
  if (child) parent.appendChild(child);
}

/**
 * Додати слухача події; повертає функцію-anti-listener для cleanup.
 */
export function on<K extends keyof HTMLElementEventMap>(
  target: EventTarget,
  type: K,
  handler: (ev: HTMLElementEventMap[K]) => void,
  options?: AddEventListenerOptions
): () => void;
export function on(
  target: EventTarget,
  type: string,
  handler: EventListenerOrEventListenerObject,
  options?: AddEventListenerOptions
): () => void;
export function on(
  target: EventTarget,
  type: string,
  handler: EventListenerOrEventListenerObject,
  options?: AddEventListenerOptions
): () => void {
  target.addEventListener(type, handler, options);
  return () => target.removeEventListener(type, handler, options);
}

/**
 * querySelector з кидаючим типом — для коли точно знаємо, що елемент існує.
 */
export function $<E extends Element = HTMLElement>(
  selector: string,
  root: ParentNode = document
): E {
  const el = root.querySelector<E>(selector);
  if (!el) throw new Error(`Selector not found: ${selector}`);
  return el;
}

/**
 * querySelector, що повертає null при відсутності — для опціональних елементів.
 */
export function $$<E extends Element = HTMLElement>(
  selector: string,
  root: ParentNode = document
): E | null {
  return root.querySelector<E>(selector);
}
