/**
 * NLI / zero-shot classification: Xenova/mDeBERTa-v3-base-xnli-multilingual-nli-2mil7
 * (~280M, q8 ≈ 280 МБ).
 *
 * Використовується для:
 *   - Mode B (topic matching) у моніторингу
 *   - stance-класифікації коментарів (3 категорії: support / oppose / unrelated)
 */

import type { ProgressCallback } from '../progress';

const MODEL_ID = 'Xenova/mDeBERTa-v3-base-xnli-multilingual-nli-2mil7';

let classifierPromise: Promise<any> | null = null;
let classifierInstance: any | null = null;

export interface NliClassifyResult {
  /** Лейбли в порядку спадання score */
  labels: string[];
  scores: number[];
}

export interface NliApi {
  readonly modelId: string;
  classify(
    text: string,
    labels: string[],
    opts?: {
      hypothesisTemplate?: string;
      multiLabel?: boolean;
    }
  ): Promise<NliClassifyResult>;
}

export async function loadNli(onProgress?: ProgressCallback): Promise<NliApi> {
  if (classifierInstance) return wrap(classifierInstance);
  if (classifierPromise) return wrap(await classifierPromise);

  classifierPromise = (async () => {
    const { pipeline, env } = await import('@huggingface/transformers');
    env.allowLocalModels = false;
    env.useBrowserCache  = true;

    const classifier = await pipeline('zero-shot-classification', MODEL_ID, {
      dtype: 'q8' as any,
      progress_callback: (data: any) => {
        onProgress?.({
          model: MODEL_ID,
          file: data?.file,
          status: data?.status,
          progress: data?.progress,
          loaded: data?.loaded,
          total: data?.total
        });
      }
    });
    classifierInstance = classifier;
    onProgress?.({ model: MODEL_ID, status: 'ready' });
    return classifier;
  })();

  return wrap(await classifierPromise);
}

function wrap(classifier: any): NliApi {
  return {
    modelId: MODEL_ID,
    async classify(text, labels, opts = {}) {
      const result = await classifier(text, labels, {
        hypothesis_template: opts.hypothesisTemplate ?? 'Цей текст про {}.',
        multi_label: opts.multiLabel ?? false
      });
      return {
        labels: result.labels as string[],
        scores: result.scores as number[]
      };
    }
  };
}
