/**
 * Зв'язує MonitoringEngine з модулями нотифікацій + favicon badge.
 *
 * Стартує одноразово при boot'і. Підписується на engine.on('post', …) і
 * викликає відповідні нотифікаційні функції згідно з налаштуваннями.
 *
 * Скидає badge коли користувач переходить на вкладку моніторингу.
 */

import { getMonitoringEngine } from './engine';
import { getVault, onVaultChange } from '../storage/current-vault';
import { notifyFoundPost, incrementBadge, resetBadge } from '../notifications';

let initialized = false;

export function setupNotificationsBridge(): void {
  if (initialized) return;
  initialized = true;

  const engine = getMonitoringEngine();

  let settingsCache = {
    browser: true,
    faviconBadge: true
  };

  // Підвантажуємо налаштування з vault
  const reload = async () => {
    const v = getVault();
    if (!v) return;
    try {
      const s = await v.settings.get();
      settingsCache = {
        browser: s.notifications.browser,
        faviconBadge: s.notifications.faviconBadge
      };
    } catch { /* ignore */ }
  };
  void reload();
  onVaultChange(() => void reload());

  // Подія: знайдено пост
  engine.on('post', (post) => {
    if (settingsCache.browser) {
      notifyFoundPost(post, { onlyWhenHidden: true });
    }
    if (settingsCache.faviconBadge) {
      // Збільшуємо лічильник лише якщо вкладка прихована
      if (document.visibilityState !== 'visible') {
        incrementBadge(true);
      }
    }
  });

  // Скидаємо badge при поверненні на вкладку
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') {
      resetBadge();
    }
  });

  // Скидаємо badge при старті
  resetBadge();
}
