/**
 * Сторінка калібровки точності AI.
 *
 * Дозволяє:
 *   - увімкнути логування рішень моделі (labelling)
 *   - подивитися список зафіксованих рішень з deeplink на пост у Telegram
 *   - вручну поставити мітку TP/FP (для topic/words) або правильний стенс
 *   - відфільтрувати по task/mode/accuracy
 *   - експортувати JSONL
 *   - запустити grid-sweep по порогах і отримати рекомендації для accuracy.ts
 */

import { html, raw, mount } from '../shared/dom';
import { icons } from '../shared/icons';
import { toast } from '../shared/toast';
import { strings } from '../../i18n/uk';
import { requireVault } from '../../core/storage/current-vault';
import {
  setLabellingEnabled,
  isLabellingEnabled,
  listEntries,
  setVerdict,
  countEntries,
  clearAll,
  exportJsonl,
  deleteEntry,
  type LabelEntry,
  type LabelTask,
  type UserVerdict
} from '../../core/calibration';
import { sweepAll, formatSweepReport } from '../../core/calibration/sweep';

type FilterTask = LabelTask | 'all';

interface FilterState {
  task: FilterTask;
  mode: 'all' | 'hybrid' | 'qwen';
  accuracy: 'all' | 1 | 2 | 3;
  showOnlyUnlabelled: boolean;
}

export function buildCalibrationPage(): HTMLElement {
  injectStyles();

  const root = html`
    <section class="page" id="page-calibration" role="tabpanel">
      <header class="page-header">
        <div>
          <div class="page-eyebrow">${strings.calibration.eyebrow}</div>
          <h1 class="page-title">${strings.calibration.pageTitle}</h1>
        </div>
        <div class="row gap-2" data-vm-counts></div>
      </header>

      <div class="panel" data-vm-controls></div>
      <div class="panel" data-vm-sweep style="margin-top: var(--space-4); display:none;"></div>
      <div class="panel" data-vm-list style="margin-top: var(--space-4);"></div>
    </section>
  `;

  const filter: FilterState = {
    task: 'all',
    mode: 'all',
    accuracy: 'all',
    showOnlyUnlabelled: false
  };

  void renderControls(root, filter);
  void renderList(root, filter);
  void renderCounts(root);

  return root;
}

// ───────────────────────────  CONTROLS  ──────────────────────────────────
async function renderControls(root: HTMLElement, filter: FilterState): Promise<void> {
  const block = root.querySelector<HTMLElement>('[data-vm-controls]')!;
  const enabled = isLabellingEnabled();

  const el = html`
    <div class="col gap-4">
      <div class="vm-toggle-row">
        <div>
          <div class="text-eyebrow">Режим логування рішень моделі</div>
          <div class="text-muted" style="font-size: var(--fs-xs); margin-top: 4px;">
            Кожен виклик topic-/words-match і кожна stance-класифікація пишеться у локальну IDB.
            Вимикайте після збору даних — щоб не лити мегабайти у нормальному моніторингу.
          </div>
        </div>
        <label class="vm-switch">
          <input type="checkbox" data-vm-toggle ${enabled ? 'checked' : ''} />
          <span class="vm-switch-track"><span class="vm-switch-thumb"></span></span>
        </label>
      </div>

      <div class="vm-cal-filters">
        <label class="vm-cal-filter">
          <span>Задача</span>
          <select class="select select-sm" data-vm-flt-task>
            <option value="all">усі</option>
            <option value="topic">topic</option>
            <option value="words">words</option>
            <option value="stance">stance</option>
          </select>
        </label>
        <label class="vm-cal-filter">
          <span>Модель</span>
          <select class="select select-sm" data-vm-flt-mode>
            <option value="all">усі</option>
            <option value="hybrid">hybrid</option>
            <option value="qwen">qwen</option>
          </select>
        </label>
        <label class="vm-cal-filter">
          <span>Точність</span>
          <select class="select select-sm" data-vm-flt-acc>
            <option value="all">усі</option>
            <option value="1">1 — Швидко</option>
            <option value="2">2 — Збалансовано</option>
            <option value="3">3 — Максимальна</option>
          </select>
        </label>
        <label class="vm-cal-filter">
          <span>Тільки немічені</span>
          <input type="checkbox" data-vm-flt-unlab />
        </label>
      </div>

      <div class="row gap-2" style="flex-wrap: wrap;">
        <button class="btn btn-secondary btn-sm" data-vm-export>
          ${raw(icons.download(14).value)}
          <span>Експорт JSONL</span>
        </button>
        <button class="btn btn-secondary btn-sm" data-vm-sweep-btn>
          ${raw(icons.scope(14).value)}
          <span>Прогнати sweep</span>
        </button>
        <button class="btn btn-danger btn-sm" data-vm-clear>
          ${raw(icons.trash(14).value)}
          <span>Очистити всі мітки</span>
        </button>
      </div>
    </div>
  `;
  mount(block, el);

  // Toggle
  el.querySelector<HTMLInputElement>('[data-vm-toggle]')!.addEventListener('change', async (e) => {
    const on = (e.target as HTMLInputElement).checked;
    setLabellingEnabled(on);
    try {
      await requireVault().settings.update({ labelling: { enabled: on } });
      toast.success(on ? 'Logging увімкнено' : 'Logging вимкнено');
    } catch (err) {
      toast.error((err as Error).message);
    }
  });

  // Filters
  el.querySelector<HTMLSelectElement>('[data-vm-flt-task]')!.addEventListener('change', (e) => {
    filter.task = (e.target as HTMLSelectElement).value as FilterTask;
    void renderList(root, filter);
  });
  el.querySelector<HTMLSelectElement>('[data-vm-flt-mode]')!.addEventListener('change', (e) => {
    filter.mode = (e.target as HTMLSelectElement).value as FilterState['mode'];
    void renderList(root, filter);
  });
  el.querySelector<HTMLSelectElement>('[data-vm-flt-acc]')!.addEventListener('change', (e) => {
    const v = (e.target as HTMLSelectElement).value;
    filter.accuracy = v === 'all' ? 'all' : (parseInt(v, 10) as 1 | 2 | 3);
    void renderList(root, filter);
  });
  el.querySelector<HTMLInputElement>('[data-vm-flt-unlab]')!.addEventListener('change', (e) => {
    filter.showOnlyUnlabelled = (e.target as HTMLInputElement).checked;
    void renderList(root, filter);
  });

  // Buttons
  el.querySelector('[data-vm-export]')!.addEventListener('click', async () => {
    const data = await exportJsonl({ onlyLabelled: false });
    if (!data) {
      toast.info('Нема що експортувати');
      return;
    }
    downloadFile(`veles-labels-${Date.now()}.jsonl`, data, 'application/x-ndjson');
    toast.success('Експортовано');
  });

  el.querySelector('[data-vm-clear]')!.addEventListener('click', async () => {
    if (!window.confirm('Видалити ВСІ зафіксовані рішення моделі та мітки?')) return;
    await clearAll();
    toast.success('Очищено');
    await renderList(root, filter);
    await renderCounts(root);
  });

  el.querySelector('[data-vm-sweep-btn]')!.addEventListener('click', async () => {
    const sweepEl = root.querySelector<HTMLElement>('[data-vm-sweep]')!;
    sweepEl.style.display = '';
    sweepEl.innerHTML = `<div class="text-muted">Обчислення sweep…</div>`;
    try {
      const [topicResults, wordsResults] = await Promise.all([
        sweepAll('topic'),
        sweepAll('words')
      ]);
      const report = `# topic\n${formatSweepReport(topicResults)}\n\n# words\n${formatSweepReport(wordsResults)}`;
      sweepEl.innerHTML = `
        <div class="text-eyebrow" style="margin-bottom: 8px;">Sweep — рекомендовані пороги</div>
        <pre class="vm-sweep-out">${escapeHtml(report)}</pre>
        <div class="row gap-2" style="margin-top: 8px;">
          <button class="btn btn-secondary btn-sm" data-vm-copy-sweep>Скопіювати</button>
        </div>
      `;
      sweepEl.querySelector('[data-vm-copy-sweep]')!.addEventListener('click', () => {
        navigator.clipboard.writeText(report).then(() => toast.success('Скопійовано'));
      });
    } catch (err) {
      sweepEl.innerHTML = `<div class="text-danger">Sweep failed: ${escapeHtml((err as Error).message)}</div>`;
    }
  });
}

// ───────────────────────────  LIST  ──────────────────────────────────────
async function renderList(root: HTMLElement, filter: FilterState): Promise<void> {
  const block = root.querySelector<HTMLElement>('[data-vm-list]')!;
  block.innerHTML = `<div class="text-muted">Завантаження…</div>`;

  let entries = await listEntries({
    task: filter.task === 'all' ? undefined : filter.task,
    limit: 500
  });
  if (filter.mode !== 'all') entries = entries.filter(e => e.mode === filter.mode);
  if (filter.accuracy !== 'all') entries = entries.filter(e => e.accuracy === filter.accuracy);
  if (filter.showOnlyUnlabelled) entries = entries.filter(e => !e.userVerdict);

  if (entries.length === 0) {
    block.innerHTML = `
      <div class="text-muted center" style="padding: 24px;">
        Жодного рішення не зафіксовано за цими фільтрами. Увімкніть logging і запустіть моніторинг.
      </div>`;
    return;
  }

  block.innerHTML = '';
  block.appendChild(html`
    <div class="text-eyebrow" style="margin-bottom: 8px;">Рішення моделі (${entries.length})</div>
  `);

  for (const e of entries) {
    block.appendChild(renderEntry(e, () => {
      void renderList(root, filter);
      void renderCounts(root);
    }));
  }
}

function renderEntry(e: LabelEntry, onChange: () => void): HTMLElement {
  const time = new Date(e.ts).toLocaleString('uk-UA');
  const isStance = e.task === 'stance';

  const card = html`
    <article class="vm-cal-entry ${e.userVerdict ? 'is-labelled' : ''}">
      <div class="vm-cal-head">
        <span class="badge">${e.task}</span>
        <span class="badge badge-info">${e.mode}</span>
        <span class="badge">a=${e.accuracy}</span>
        <span class="text-mono text-muted" style="font-size: var(--fs-xs);">
          score=${(e.score ?? 0).toFixed(3)} ${e.threshold ? `· th=${e.threshold.toFixed(2)}` : ''}
        </span>
        <span class="text-mono badge ${decisionBadge(e.modelDecision)}">${e.modelDecision}</span>
        ${e.userVerdict ? raw(`<span class="badge badge-success">${e.userVerdict}</span>`) : ''}
        <span class="text-mono text-muted" style="margin-left: auto; font-size: var(--fs-xs);">${time}</span>
      </div>

      ${e.topic ? raw(`<div class="text-secondary" style="font-size: var(--fs-xs); margin-top: 4px;">topic: <span class="text-mono">${escapeHtml(e.topic)}</span></div>`) : ''}
      ${e.keywords ? raw(`<div class="text-secondary" style="font-size: var(--fs-xs);">keywords: <span class="text-mono">${escapeHtml(e.keywords.join(', '))}</span></div>`) : ''}

      ${isStance && e.postText ? raw(`<div class="vm-cal-snippet"><b>пост:</b> ${escapeHtml(e.postText)}</div>`) : ''}
      <div class="vm-cal-snippet"><b>${isStance ? 'коментар' : 'текст'}:</b> ${escapeHtml(e.text)}</div>

      <div class="row gap-2" style="margin-top: 8px; flex-wrap: wrap;">
        ${e.url ? raw(`<a class="btn btn-ghost btn-sm" href="${escapeHtml(e.url)}" target="_blank" rel="noreferrer">${icons.link(12).value}<span>відкрити</span></a>`) : ''}
        ${raw(isStance ? renderStanceButtons(e) : renderTpFpButtons(e))}
        <button class="btn btn-ghost btn-sm" data-vm-del title="Видалити запис">${raw(icons.trash(12).value)}</button>
      </div>
    </article>
  `;

  // Button handlers
  card.querySelectorAll<HTMLButtonElement>('[data-vm-verdict]').forEach(btn => {
    btn.addEventListener('click', async () => {
      const v = btn.dataset.vmVerdict as UserVerdict;
      await setVerdict(e.id, v);
      onChange();
    });
  });
  card.querySelector<HTMLButtonElement>('[data-vm-del]')?.addEventListener('click', async () => {
    await deleteEntry(e.id);
    onChange();
  });

  return card;
}

function renderTpFpButtons(e: LabelEntry): string {
  const active = e.userVerdict;
  const cls = (v: string) => active === v ? 'btn-primary' : 'btn-secondary';
  return `
    <button class="btn ${cls('tp')} btn-sm" data-vm-verdict="tp" title="справді про тему">${icons.check(12).value}<span>TP</span></button>
    <button class="btn ${cls('fp')} btn-sm" data-vm-verdict="fp" title="модель помилилася">${icons.x(12).value}<span>FP</span></button>
    <button class="btn ${cls('fn')} btn-sm" data-vm-verdict="fn" title="модель пропустила (treat-as-positive)">${icons.alert(12).value}<span>FN</span></button>
  `;
}

function renderStanceButtons(e: LabelEntry): string {
  const active = e.userVerdict;
  const cls = (v: string) => active === v ? 'btn-primary' : 'btn-secondary';
  return `
    <button class="btn ${cls('support')} btn-sm" data-vm-verdict="support">support</button>
    <button class="btn ${cls('oppose')} btn-sm" data-vm-verdict="oppose">oppose</button>
    <button class="btn ${cls('unrelated')} btn-sm" data-vm-verdict="unrelated">unrelated</button>
  `;
}

function decisionBadge(decision: string): string {
  if (decision === 'matched' || decision === 'support') return 'badge-success';
  if (decision === 'oppose') return 'badge-warning';
  return '';
}

// ───────────────────────────  COUNTS  ───────────────────────────────────
async function renderCounts(root: HTMLElement): Promise<void> {
  const wrap = root.querySelector<HTMLElement>('[data-vm-counts]')!;
  const { total, labelled } = await countEntries();
  wrap.innerHTML = `
    <span class="badge">${total} <span class="text-muted">всього</span></span>
    <span class="badge badge-accent">${labelled} <span class="text-muted">мічено</span></span>
  `;
}

// ───────────────────────────  utils  ────────────────────────────────────
function downloadFile(name: string, content: string, mime: string): void {
  const blob = new Blob([content], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch] as string));
}

// ───────────────────────────  styles  ───────────────────────────────────
let stylesInjected = false;
function injectStyles(): void {
  if (stylesInjected) return;
  stylesInjected = true;
  const s = document.createElement('style');
  s.textContent = `
    .vm-cal-filters {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: var(--space-3);
    }
    @media (max-width: 700px) { .vm-cal-filters { grid-template-columns: 1fr 1fr; } }
    .vm-cal-filter {
      display: flex; flex-direction: column; gap: 4px;
      font-size: var(--fs-xs);
      color: var(--fg-muted);
      text-transform: uppercase;
      letter-spacing: var(--tracking-wide);
    }
    .vm-cal-filter select { width: 100%; }

    .vm-cal-entry {
      background: var(--bg-elevated);
      border: 1px solid var(--border-subtle);
      border-left: 3px solid var(--border-subtle);
      border-radius: var(--radius-sm);
      padding: var(--space-3) var(--space-4);
      margin-bottom: var(--space-3);
    }
    .vm-cal-entry.is-labelled { border-left-color: var(--accent); }
    .vm-cal-head {
      display: flex; align-items: center; gap: var(--space-2);
      flex-wrap: wrap;
    }
    .vm-cal-snippet {
      margin-top: 6px;
      font-size: var(--fs-sm);
      line-height: var(--lh-relaxed);
      color: var(--fg-primary);
      white-space: pre-wrap;
      word-break: break-word;
      max-height: 6em;
      overflow: auto;
      padding: 4px 8px;
      background: var(--bg-base);
      border-radius: var(--radius-xs);
    }
    .vm-cal-snippet b { color: var(--fg-muted); }

    .vm-sweep-out {
      font-family: var(--font-mono);
      font-size: var(--fs-xs);
      background: var(--bg-base);
      padding: var(--space-3);
      border-radius: var(--radius-xs);
      max-height: 400px; overflow: auto;
      white-space: pre;
    }

    .select-sm { height: 28px; padding: 0 8px; font-size: var(--fs-xs); }
  `;
  document.head.appendChild(s);
}
