/**
 * Labelling store — для калібровки точності AI.
 *
 * Логуємо КОЖНЕ рішення моделі (matched / not matched, навіть пропущені),
 * щоб користувач міг проставити ground-truth мітки (TP / FP / FN),
 * а потім програмний sweep по порогах знайшов F1-оптимум для кожного режиму.
 *
 * Зберігається в окремій IndexedDB `veles-labels` (не в vault) —
 * це калібровочні дані, не секрети, і їх потрібно експортувати в JSONL.
 *
 * Логування активне лише коли settings.labelling.enabled = true,
 * щоб у нормальному моніторингу не накопичувалися мегабайти.
 */

import { openDB as openIdb, type IDBPDatabase, type DBSchema } from 'idb';

export type LabelTask = 'topic' | 'words' | 'stance';

export type UserVerdict =
  | 'tp'          // справді про тему / справді матч слова / правильний стенс
  | 'fp'          // модель сказала так, але це не воно
  | 'fn'          // модель сказала ні, а насправді воно (ставиться при ручному додаванні з відсіяних)
  | 'support'     // ground-truth стенс
  | 'oppose'
  | 'unrelated'
  | null;

export interface LabelEntry {
  /** stable id для дедупу */
  id: string;
  ts: number;

  task: LabelTask;

  // Конфігурація запуску
  mode: 'hybrid' | 'qwen';
  accuracy: 1 | 2 | 3;
  threshold: number;

  // Вхід (тримаємо обрізаним — для UI)
  text: string;          // перші 800 символів rawText (або коментаря для stance)
  topic?: string;
  keywords?: string[];
  postText?: string;     // лише для stance — перші 400 символів

  // Сирий вихід моделі
  score: number;                    // для topic/words — головний score
  chunkScores?: number[];           // для topic — по чанках
  perKeyword?: { keyword: string; score: number; matchedWord?: string }[];
  scores?: { support: number; oppose: number; unrelated: number };  // stance

  modelDecision: 'matched' | 'unmatched' | 'support' | 'oppose' | 'unrelated';

  // Ground truth (заповнюється пізніше юзером)
  userVerdict: UserVerdict;

  // Посилання — щоб юзер міг перейти і подивитися
  channelId?: string;
  channelTitle?: string;
  messageId?: number;
  url?: string;
}

interface LabelsDB extends DBSchema {
  entries: {
    key: string;
    value: LabelEntry;
    indexes: {
      'by-ts':   number;
      'by-task': LabelTask;
    };
  };
  meta: {
    key: string;
    value: unknown;
  };
}

const DB_NAME = 'veles-labels';
const DB_VERSION = 1;
const MAX_ENTRIES = 5000;

let dbPromise: Promise<IDBPDatabase<LabelsDB>> | null = null;

function openLabelsDB(): Promise<IDBPDatabase<LabelsDB>> {
  if (dbPromise) return dbPromise;
  dbPromise = openIdb<LabelsDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('entries')) {
        const store = db.createObjectStore('entries', { keyPath: 'id' });
        store.createIndex('by-ts',   'ts');
        store.createIndex('by-task', 'task');
      }
      if (!db.objectStoreNames.contains('meta')) {
        db.createObjectStore('meta');
      }
    }
  });
  return dbPromise;
}

// ────────────────────────────  RUNTIME FLAG  ──────────────────────────────
// Глобальний перемикач — швидкий і не вимагає звернення до vault з гарячого
// шляху моніторингу. Виставляється з UI Settings, читається з handleMessage.
let labellingEnabled = false;

export function setLabellingEnabled(on: boolean): void {
  labellingEnabled = on;
}

export function isLabellingEnabled(): boolean {
  return labellingEnabled;
}

// ────────────────────────────  CRUD  ──────────────────────────────────────
export async function addEntry(entry: Omit<LabelEntry, 'id' | 'ts' | 'userVerdict'> & { id?: string }): Promise<string> {
  const id = entry.id ?? makeId(entry);
  const full: LabelEntry = {
    ...entry,
    id,
    ts: Date.now(),
    userVerdict: null
  } as LabelEntry;

  const db = await openLabelsDB();
  await db.put('entries', full);
  await enforceLimit(db);
  return id;
}

export async function setVerdict(id: string, verdict: UserVerdict): Promise<void> {
  const db = await openLabelsDB();
  const cur = await db.get('entries', id);
  if (!cur) return;
  cur.userVerdict = verdict;
  await db.put('entries', cur);
}

export async function getEntry(id: string): Promise<LabelEntry | undefined> {
  const db = await openLabelsDB();
  return db.get('entries', id);
}

export async function listEntries(opts: { task?: LabelTask; onlyLabelled?: boolean; limit?: number } = {}): Promise<LabelEntry[]> {
  const db = await openLabelsDB();
  let entries: LabelEntry[];
  if (opts.task) {
    entries = await db.getAllFromIndex('entries', 'by-task', opts.task);
  } else {
    entries = await db.getAll('entries');
  }
  entries.sort((a, b) => b.ts - a.ts);
  if (opts.onlyLabelled) entries = entries.filter(e => e.userVerdict);
  if (opts.limit && entries.length > opts.limit) entries = entries.slice(0, opts.limit);
  return entries;
}

export async function clearAll(): Promise<void> {
  const db = await openLabelsDB();
  const tx = db.transaction('entries', 'readwrite');
  await tx.store.clear();
  await tx.done;
}

export async function deleteEntry(id: string): Promise<void> {
  const db = await openLabelsDB();
  await db.delete('entries', id);
}

export async function countEntries(): Promise<{ total: number; labelled: number }> {
  const db = await openLabelsDB();
  const all = await db.getAll('entries');
  return {
    total: all.length,
    labelled: all.filter(e => e.userVerdict).length
  };
}

// ────────────────────────────  EXPORT  ────────────────────────────────────
/**
 * JSON Lines export — один entry на рядок. Підходить для grid-sweep.
 */
export async function exportJsonl(opts: { onlyLabelled?: boolean; task?: LabelTask } = {}): Promise<string> {
  const entries = await listEntries({ task: opts.task, onlyLabelled: opts.onlyLabelled });
  return entries.map(e => JSON.stringify(e)).join('\n');
}

/**
 * Сирий JSON-масив — корисно для імпорту назад / для дебагу.
 */
export async function exportJson(opts: { onlyLabelled?: boolean; task?: LabelTask } = {}): Promise<string> {
  const entries = await listEntries({ task: opts.task, onlyLabelled: opts.onlyLabelled });
  return JSON.stringify(entries, null, 2);
}

// ────────────────────────────  HELPERS  ───────────────────────────────────
function makeId(entry: Pick<LabelEntry, 'task' | 'mode' | 'accuracy' | 'channelId' | 'messageId' | 'topic' | 'text'>): string {
  // Якщо є channelId+messageId — використовуємо їх (стабільний id одного й того ж поста при повторному скані).
  if (entry.channelId && typeof entry.messageId === 'number') {
    return `${entry.task}_${entry.mode}_a${entry.accuracy}_${entry.channelId}_${entry.messageId}`;
  }
  // Fallback: хеш від тексту + теми.
  const seed = `${entry.task}|${entry.mode}|${entry.accuracy}|${entry.topic ?? ''}|${entry.text.slice(0, 200)}`;
  return `${entry.task}_${entry.mode}_a${entry.accuracy}_${djb2(seed).toString(36)}`;
}

function djb2(str: string): number {
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
  return h;
}

async function enforceLimit(db: IDBPDatabase<LabelsDB>): Promise<void> {
  const count = await db.count('entries');
  if (count <= MAX_ENTRIES) return;
  // Видаляємо найстаріші непомічені (помічені залишаємо — це цінні дані)
  const all = await db.getAll('entries');
  const candidates = all
    .filter(e => !e.userVerdict)
    .sort((a, b) => a.ts - b.ts);
  const toDelete = candidates.slice(0, count - MAX_ENTRIES);
  const tx = db.transaction('entries', 'readwrite');
  for (const e of toDelete) await tx.store.delete(e.id);
  await tx.done;
}
