/**
 * Авторизаційний флоу для gram.js.
 *
 * Кроки:
 *   1. setApiCredentials({apiId, apiHash})       — зберегти в vault, створити клієнт
 *   2. sendLoginCode(phone)                      — Telegram пришле SMS/in-app код
 *   3. submitLoginCode(code)                     — підтвердити; може кинути TwoFactor
 *   4. submitTwoFactorPassword(password)         — якщо потрібен 2FA
 *   5. logout()                                  — вийти з акаунту, очистити сесію
 *
 * Стан "що йде далі" живе в AuthFlow — простий state-machine,
 * щоб onboarding-UI міг показувати правильний крок.
 */

import { requireVault } from '../storage/current-vault';
import { getTelegramClient, getGramJs, disconnectTelegram } from './client';

export interface TgUser {
  id: number;
  phone: string;
  firstName?: string;
  lastName?: string;
  username?: string;
}

export interface SentCodeInfo {
  /** className типу надісланого коду (напр. SentCodeTypeApp) */
  codeType: string;
  /** Людиночитаний опис, куди надіслано код */
  destination: string;
  /** className наступного каналу доставки, або null якщо повтор недоступний */
  nextType: string | null;
  /** Чи можливе повторне надсилання (Telegram запропонував наступний канал) */
  canResend: boolean;
}

export class AuthFlow {
  private phone: string | null = null;
  private phoneCodeHash: string | null = null;
  private nextCodeType: string | null = null;

  /**
   * Зберегти api_id/api_hash і підключитися (ще без логіну).
   */
  async setApiCredentials(apiId: number, apiHash: string): Promise<void> {
    if (!Number.isInteger(apiId) || apiId <= 0) {
      throw new Error('api_id має бути цілим числом');
    }
    if (!/^[a-f0-9]{32}$/i.test(apiHash)) {
      throw new Error('api_hash має бути 32-символьним hex-рядком');
    }
    const vault = requireVault();
    await vault.secure.setApiCreds({ apiId, apiHash });

    // Створимо клієнт, щоб переконатися що підключення працює
    const client = await getTelegramClient({ apiId, apiHash, sessionString: '' });
    if (!client.connected) {
      await client.connect();
    }
  }

  /**
   * Надіслати код підтвердження на телефон. Telegram сам обере канал доставки:
   *  - якщо у вас є активна Telegram-сесія на іншому пристрої → код приходить як in-app
   *    повідомлення від @Telegram (НЕ SMS!)
   *  - якщо інших сесій немає → SMS
   */
  async sendLoginCode(phone: string): Promise<SentCodeInfo> {
    const normalized = phone.trim().replace(/\s+/g, '');
    if (!/^\+?\d{8,15}$/.test(normalized)) {
      throw new Error('Невірний формат телефону (приклад: +380501234567)');
    }
    this.phone = normalized.startsWith('+') ? normalized : `+${normalized}`;

    const client = await getTelegramClient();
    const vault = requireVault();
    const creds = await vault.secure.getApiCreds();
    if (!creds) throw new Error('api_id/api_hash ще не задано');

    const { Api } = await getGramJs();
    const result = await client.invoke(
      new Api.auth.SendCode({
        phoneNumber: this.phone,
        apiId: creds.apiId,
        apiHash: creds.apiHash,
        settings: new Api.CodeSettings({
          allowFlashcall: false,
          // currentNumber: false — браузер ≠ той самий телефон. true примушує Telegram
          // надсилати код виключно в існуючу сесію, що часто = "користувач не бачить код".
          currentNumber: false,
          allowAppHash: true,
          allowMissedCall: false
        })
      })
    );
    this.phoneCodeHash = result.phoneCodeHash;
    this.nextCodeType = result.nextType?.className ?? null;
    const codeType = result.type?.className ?? 'unknown';
    // Діагностика доставки коду (видно в DevTools → Console).
    console.info('[VM][auth] sendCode:', {
      type: codeType,
      nextType: this.nextCodeType,
      timeout: (result as any).timeout
    });
    return {
      codeType,
      destination: describeCodeDestination(codeType),
      nextType: this.nextCodeType,
      canResend: this.nextCodeType != null
    };
  }

  /**
   * Запит на повторне надсилання коду (наприклад, перейти з in-app на SMS).
   * Telegram сам визначає наступний канал — зазвичай альтернативний до попереднього.
   */
  async resendCode(): Promise<SentCodeInfo> {
    if (!this.phone || !this.phoneCodeHash) {
      throw new Error('Спочатку викличте sendLoginCode()');
    }
    // Telegram дозволяє повтор лише якщо попередній sendCode повернув наступний
    // канал (nextType). Якщо його немає — auth.resendCode відповість
    // 406 SEND_CODE_UNAVAILABLE. Тому не смикаємо сервер даремно, а пояснюємо.
    if (!this.nextCodeType) {
      throw new Error(
        'Повторне надсилання недоступне. Telegram надіслав код у застосунок Telegram — ' +
        'відкрий службовий чат «Telegram» на пристрої, де ти вже залогінений (також глянь ' +
        '«Збережені повідомлення»). SMS у цьому випадку Telegram не надсилає.'
      );
    }
    const client = await getTelegramClient();
    const { Api } = await getGramJs();
    try {
      const result = await client.invoke(
        new Api.auth.ResendCode({
          phoneNumber: this.phone,
          phoneCodeHash: this.phoneCodeHash
        })
      );
      this.phoneCodeHash = result.phoneCodeHash;
      this.nextCodeType = result.nextType?.className ?? null;
      const codeType = result.type?.className ?? 'unknown';
      return {
        codeType,
        destination: describeCodeDestination(codeType),
        nextType: this.nextCodeType,
        canResend: this.nextCodeType != null
      };
    } catch (err: any) {
      const m = err?.errorMessage ?? err?.message ?? String(err);
      if (/SEND_CODE_UNAVAILABLE/i.test(m)) {
        this.nextCodeType = null;
        throw new Error(
          'Telegram не може надіслати код іншим каналом. Код уже у застосунку Telegram ' +
          '(службовий чат «Telegram») на пристрої, де ти залогінений.'
        );
      }
      const flood = m.match(/FLOOD_WAIT_(\d+)/i);
      if (flood) {
        throw new Error(`Забагато спроб. Зачекай ${flood[1]} с і спробуй знову.`);
      }
      throw err;
    }
  }

  /**
   * Підтвердити код. Може кинути SessionPasswordNeededError → треба submitTwoFactorPassword.
   */
  async submitLoginCode(code: string): Promise<TgUser | 'two-factor-needed'> {
    if (!this.phone || !this.phoneCodeHash) {
      throw new Error('Спочатку викличте sendLoginCode()');
    }
    const cleanCode = code.trim().replace(/\s+/g, '');
    if (!/^\d{5,7}$/.test(cleanCode)) {
      throw new Error('Невірний формат коду');
    }

    const client = await getTelegramClient();
    const { Api } = await getGramJs();

    try {
      const result: any = await client.invoke(
        new Api.auth.SignIn({
          phoneNumber: this.phone,
          phoneCodeHash: this.phoneCodeHash,
          phoneCode: cleanCode
        })
      );
      const user = result?.user;
      await persistSession();
      return mapUser(user, this.phone);
    } catch (err: any) {
      // Не використовуємо instanceof, бо клас errors.SessionPasswordNeededError
      // в браузері може існувати в кількох копіях через bundling — instanceof не спрацює.
      // String-based check надійніший.
      const className = err?.className ?? err?.constructor?.name ?? '';
      const errMsg = err?.errorMessage ?? err?.message ?? '';
      if (className === 'SessionPasswordNeededError' ||
          className === 'RPCError' && /SESSION_PASSWORD_NEEDED/i.test(errMsg) ||
          /SESSION_PASSWORD_NEEDED/i.test(errMsg) ||
          /Two-steps verification is enabled/i.test(errMsg)) {
        return 'two-factor-needed';
      }
      throw err;
    }
  }

  /**
   * Якщо акаунт із cloud-password (2FA) — підтвердити пароль.
   *
   * Імплементовано вручну через Web Crypto API (див. ./srp2.ts).
   * Уникає gram.js telegram/Password.computeCheck, бо в мінімізованому
   * браузерному бандлі вона ламалася на bytes-typecheck-ах ("Bytes or str
   * expected, not e").
   */
  async submitTwoFactorPassword(password: string): Promise<TgUser> {
    const cleanPassword = String(password ?? '');
    if (!cleanPassword) throw new Error('Пароль не може бути порожнім');
    const phone = this.phone ?? '';

    const client = await getTelegramClient();
    const { Api } = await getGramJs();
    const { computeSrp2, toUint8 } = await import('./srp2');

    // 1. Параметри SRP-2 з сервера
    const pwInfo: any = await client.invoke(new Api.account.GetPassword());

    // gram.js версії можуть по-різному називати поля — пробуємо обидва варіанти
    const algo = pwInfo.currentAlgo ?? pwInfo.current_algo;
    const srpB = pwInfo.srpB ?? pwInfo.srp_B ?? pwInfo.srp_b;
    const srpId = pwInfo.srpId ?? pwInfo.srp_id;

    const missing: string[] = [];
    if (!algo)  missing.push('currentAlgo (algo об\'єкт PBKDF2)');
    if (!srpB)  missing.push('srpB (server ephemeral)');
    if (!srpId) missing.push('srpId');
    if (missing.length > 0) {
      const dump = {
        pwInfoType: pwInfo?.constructor?.name,
        keys: Object.keys(pwInfo || {}),
        hasPassword: pwInfo?.hasPassword,
        algoClassName: pwInfo?.currentAlgo?.className
      };
      throw new Error(`2FA: відсутні поля [${missing.join(', ')}]. Dump: ${JSON.stringify(dump)}`);
    }

    const salt1 = algo.salt1 ?? algo.salt_1;
    const salt2 = algo.salt2 ?? algo.salt_2;
    const g     = algo.g;
    const p     = algo.p;
    const algoMissing: string[] = [];
    if (!salt1) algoMissing.push('salt1');
    if (!salt2) algoMissing.push('salt2');
    if (g == null) algoMissing.push('g');
    if (!p)     algoMissing.push('p');
    if (algoMissing.length > 0) {
      throw new Error(`2FA algo: відсутні [${algoMissing.join(', ')}]. Algo keys: ${Object.keys(algo).join(', ')}, className: ${algo.className ?? 'n/a'}`);
    }

    // 2. Обчислюємо SRP-2
    const srp = await computeSrp2({
      srpId,
      srpB:  toUint8(srpB),
      algo: {
        salt1: toUint8(salt1),
        salt2: toUint8(salt2),
        g:     Number(g),
        p:     toUint8(p)
      }
    }, cleanPassword);

    // 3. auth.CheckPassword. InputCheckPasswordSRP вимагає:
    //    - srpId як big-integer (gram.js власний bigint)
    //    - A і M1 як Buffer (НЕ Uint8Array — gram.js TL-серіалізатор
    //      робить instanceof Buffer і фейлить чистий Uint8Array)
    const bigInt = (await import('big-integer')).default;
    const { Buffer } = await import('buffer');
    const result: any = await client.invoke(
      new Api.auth.CheckPassword({
        password: new Api.InputCheckPasswordSRP({
          srpId: bigInt(srp.srpId),
          A:  Buffer.from(srp.A)  as any,
          M1: Buffer.from(srp.M1) as any
        })
      })
    );
    const user = result?.user;
    if (!user) throw new Error('Telegram повернув порожнього user — невдала авторизація');

    await persistSession();
    return mapUser(user, phone);
  }
}

/**
 * Logout з повним очищенням сесії і api-кредів.
 */
export async function logout(): Promise<void> {
  const vault = requireVault();
  try {
    const client = await getTelegramClient();
    const { Api } = await getGramJs();
    await client.invoke(new Api.auth.LogOut()).catch(() => {});
  } catch {
    // вже могло бути disconnected
  }
  await disconnectTelegram();
  await vault.logout();
}

/**
 * Дістати поточного користувача (якщо авторизовано).
 */
export async function getMe(): Promise<TgUser | null> {
  try {
    const client = await getTelegramClient();
    const me = await client.getMe();
    if (!me) return null;
    return mapUser(me, me.phone ? `+${me.phone}` : '');
  } catch {
    return null;
  }
}

// ──────────────────  helpers  ──────────────────
async function persistSession(): Promise<void> {
  const client = await getTelegramClient();
  const session = client.session.save();
  const vault = requireVault();
  await vault.secure.setSession(session);
}

/**
 * Людино-читана назва каналу доставки коду.
 */
function describeCodeDestination(codeTypeClass: string): string {
  // gram.js повертає className з префіксом простору імен (напр. "auth.SentCodeTypeApp"),
  // тому відрізаємо все до останньої крапки перед пошуком у мапі.
  const key = codeTypeClass.replace(/^.*\./, '');
  const map: Record<string, string> = {
    SentCodeTypeApp:        'у застосунку Telegram (службовий чат «Telegram»)',
    SentCodeTypeSms:        'у SMS',
    SentCodeTypeCall:       'вхідним дзвінком (диктують код)',
    SentCodeTypeFlashCall:  'flash-call (останні цифри номера = код)',
    SentCodeTypeMissedCall: 'пропущеним дзвінком (останні цифри = код)',
    SentCodeTypeEmailCode:  'на email',
    SentCodeTypeSetUpEmailRequired: 'потрібно спершу налаштувати email-логін у застосунку Telegram',
    SentCodeTypeFragmentSms:'у Fragment (анонімний номер)'
  };
  return map[key] ?? `(тип: ${codeTypeClass})`;
}

function mapUser(u: any, phone: string): TgUser {
  return {
    id: Number(u?.id?.toString() ?? u?.id ?? 0),
    phone,
    firstName: u?.firstName,
    lastName:  u?.lastName,
    username:  u?.username
  };
}
