/**
 * File System Access API — обрати папку, зберігати медіа-файли.
 *
 * Підтримка: Chrome / Edge / Opera (стабільна), Firefox/Safari — fallback на завантаження.
 * Handle папки зберігається в IndexedDB (FileSystemDirectoryHandle структурно клонується).
 */

import { openDB } from './idb';

const STORE = 'meta';
const KEY   = 'mediaFolderHandle';

export type DirectoryHandle = any;   // FileSystemDirectoryHandle, тип може бути недоступний в TS lib

export function isSupported(): boolean {
  return typeof (window as any).showDirectoryPicker === 'function';
}

export async function pickFolder(): Promise<DirectoryHandle | null> {
  if (!isSupported()) return null;
  try {
    const handle = await (window as any).showDirectoryPicker({
      id: 'veles-media',
      mode: 'readwrite',
      startIn: 'documents'
    });
    const db = await openDB();
    await db.put(STORE, handle, KEY);
    return handle;
  } catch (err) {
    if ((err as Error).name === 'AbortError') return null;
    throw err;
  }
}

export async function getSavedFolder(): Promise<DirectoryHandle | null> {
  const db = await openDB();
  const handle = await db.get(STORE, KEY);
  if (!handle) return null;
  // Перевіряємо дозвіл
  try {
    const perm: PermissionState = await (handle as any).queryPermission({ mode: 'readwrite' });
    if (perm === 'granted') return handle;
    if (perm === 'prompt') {
      const newPerm: PermissionState = await (handle as any).requestPermission({ mode: 'readwrite' });
      if (newPerm === 'granted') return handle;
    }
  } catch { /* ignore */ }
  return null;
}

export async function forgetFolder(): Promise<void> {
  const db = await openDB();
  await db.delete(STORE, KEY);
}

/**
 * Зберегти Blob у вибрану папку (можливо, у підпапку YYYY-MM-DD).
 * Якщо File System Access недоступний — fallback на browser-download.
 */
export async function saveMediaBlob(
  filename: string,
  blob: Blob,
  opts?: { subfolder?: string }
): Promise<{ savedTo: 'folder' | 'download'; path?: string }> {
  const handle = await getSavedFolder();

  if (handle) {
    try {
      let target = handle;
      if (opts?.subfolder) {
        target = await (handle as any).getDirectoryHandle(opts.subfolder, { create: true });
      }
      const fileHandle = await (target as any).getFileHandle(filename, { create: true });
      const writable = await (fileHandle as any).createWritable();
      await writable.write(blob);
      await writable.close();
      return { savedTo: 'folder', path: `${opts?.subfolder ? opts.subfolder + '/' : ''}${filename}` };
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn('[fs] save to folder failed, fallback to download:', err);
    }
  }

  // Fallback: звичайне завантаження браузера
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
  return { savedTo: 'download' };
}
