/**
 * Real-time моніторинг нових повідомлень в обраних каналах.
 *
 * Використання:
 *   const sub = await startMonitoring(channels, async (msg) => { ... });
 *   ...
 *   sub.stop();
 */

import { getTelegramClient, getGramJs } from './client';
import type { MonitoredChannel } from '../../types';

export interface IncomingMessage {
  channelId: string;
  channelTitle: string;
  channelUsername?: string;
  messageId: number;
  postedAt: number;          // unix ms
  rawText: string;
  hasMedia: boolean;
  /** raw gram.js message — для подальшого fetch медіа */
  raw: any;
}

export interface MonitorSubscription {
  stop(): Promise<void>;
}

export async function startMonitoring(
  channels: MonitoredChannel[],
  onMessage: (msg: IncomingMessage) => void | Promise<void>
): Promise<MonitorSubscription> {
  const client = await getTelegramClient();
  const { events } = await getGramJs();

  // Заводимо мапу id→title для швидкого пошуку
  const channelMeta = new Map<string, MonitoredChannel>();
  for (const ch of channels) channelMeta.set(ch.id, ch);

  // gram.js не дає фільтру одразу по списку peer-ів — підписуємось на всі нові
  // повідомлення і фільтруємо за peerId всередині handler.
  const handler = async (event: any) => {
    try {
      const msg = event?.message;
      if (!msg) return;
      const peerId = extractPeerId(msg.peerId);
      if (!peerId) return;

      const meta = channelMeta.get(peerId);
      if (!meta) return;          // повідомлення поза нашим списком — ігноруємо

      const out: IncomingMessage = {
        channelId: peerId,
        channelTitle: meta.title,
        channelUsername: meta.username,
        messageId: msg.id,
        postedAt: (msg.date ?? Math.floor(Date.now() / 1000)) * 1000,
        rawText: msg.message ?? msg.text ?? '',
        hasMedia: !!msg.media,
        raw: msg
      };
      await onMessage(out);
    } catch (err) {
      // eslint-disable-next-line no-console
      console.error('[monitor] handler error:', err);
    }
  };

  client.addEventHandler(handler, new events.NewMessage({ incoming: true }));

  return {
    async stop() {
      try { client.removeEventHandler(handler, new events.NewMessage({ incoming: true })); }
      catch { /* ignore */ }
    }
  };
}

/**
 * Сканування історії за останні N годин (для режиму "часовий діапазон").
 */
export async function scanRecentHistory(
  channels: MonitoredChannel[],
  hoursBack: number,
  onMessage: (msg: IncomingMessage) => void | Promise<void>,
  abortSignal?: AbortSignal
): Promise<void> {
  const client = await getTelegramClient();
  const sinceMs = Date.now() - hoursBack * 3600 * 1000;
  const sinceSec = Math.floor(sinceMs / 1000);

  // Прогріваємо кеш сутностей gram.js. У свіжій сесії (після перезавантаження)
  // getEntity(id) падає з "Could not find the input entity", бо невідомий
  // access_hash. getDialogs() підвантажує діалоги й кешує канали — беремо entity звідти.
  const entityById = new Map<string, any>();
  try {
    const dialogs = await client.getDialogs({ limit: 200, archived: false });
    for (const d of dialogs) {
      const ent = d.entity;
      if (ent && ent.id != null) {
        entityById.set(String(ent.id.toString?.() ?? ent.id), ent);
      }
    }
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn('[monitor] getDialogs prime failed:', err);
  }

  for (const ch of channels) {
    if (abortSignal?.aborted) return;
    try {
      const entity = entityById.get(ch.id) ?? await client.getEntity(ch.id);
      for await (const msg of client.iterMessages(entity, { limit: 500 })) {
        if (abortSignal?.aborted) return;
        if ((msg.date ?? 0) < sinceSec) break;     // вийшли за діапазон — далі ще давніші
        if (!msg.message && !msg.text) continue;
        await onMessage({
          channelId: ch.id,
          channelTitle: ch.title,
          channelUsername: ch.username,
          messageId: msg.id,
          postedAt: (msg.date ?? sinceSec) * 1000,
          rawText: msg.message ?? msg.text ?? '',
          hasMedia: !!msg.media,
          raw: msg
        });
      }
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn(`[monitor] history scan failed for ${ch.title}:`, err);
    }
  }
}

function extractPeerId(peer: any): string | null {
  if (!peer) return null;
  // gram.js peerId: PeerChannel{channelId}, PeerChat{chatId}, PeerUser{userId}
  const id = peer.channelId ?? peer.chatId ?? peer.userId;
  return id != null ? String(id.toString?.() ?? id) : null;
}
