/**
 * Лічильник нових знахідок у favicon + заголовку вкладки.
 *
 * Малюємо лічильник поверх SVG-favicon через canvas → toDataURL.
 * Title оновлюємо префіксом «(N) Veles…».
 */

const FAVICON_BASE_SRC = './favicon.svg';
const DEFAULT_TITLE = document.title;
const FAVICON_SIZE = 64;

let baseImage: HTMLImageElement | null = null;
let currentCount = 0;

async function loadBaseImage(): Promise<HTMLImageElement> {
  if (baseImage) return baseImage;
  const img = new Image();
  img.src = FAVICON_BASE_SRC;
  await new Promise<void>((resolve, reject) => {
    img.onload  = () => resolve();
    img.onerror = () => reject(new Error('Не вдалося завантажити favicon'));
  });
  baseImage = img;
  return img;
}

function findOrCreateLink(): HTMLLinkElement {
  let link = document.querySelector<HTMLLinkElement>('link[rel="icon"]');
  if (!link) {
    link = document.createElement('link');
    link.rel = 'icon';
    document.head.appendChild(link);
  }
  return link;
}

/**
 * Оновити favicon + title для нової кількості.
 * count = 0 → повертає базові значення.
 */
export async function setBadgeCount(count: number, enabled = true): Promise<void> {
  currentCount = count;

  // Title завжди можемо
  document.title = (enabled && count > 0)
    ? `(${count > 99 ? '99+' : count}) ${DEFAULT_TITLE}`
    : DEFAULT_TITLE;

  if (!enabled || count === 0) {
    findOrCreateLink().href = FAVICON_BASE_SRC;
    return;
  }

  try {
    const img = await loadBaseImage();
    const canvas = document.createElement('canvas');
    canvas.width = FAVICON_SIZE;
    canvas.height = FAVICON_SIZE;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.drawImage(img, 0, 0, FAVICON_SIZE, FAVICON_SIZE);

    // Бейдж у нижньому правому куті
    const radius = 20;
    const cx = FAVICON_SIZE - radius - 2;
    const cy = FAVICON_SIZE - radius - 2;
    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, Math.PI * 2);
    ctx.fillStyle = '#F87171';
    ctx.fill();
    ctx.strokeStyle = '#0A1628';
    ctx.lineWidth = 3;
    ctx.stroke();

    ctx.fillStyle = '#FFFFFF';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const label = count > 99 ? '99+' : String(count);
    ctx.font = `bold ${label.length > 2 ? 16 : 22}px Inter, system-ui, sans-serif`;
    ctx.fillText(label, cx, cy + 1);

    findOrCreateLink().href = canvas.toDataURL('image/png');
  } catch (err) {
    // eslint-disable-next-line no-console
    console.warn('[favicon] update failed:', err);
  }
}

export function incrementBadge(enabled = true): void {
  void setBadgeCount(currentCount + 1, enabled);
}

export function resetBadge(): void {
  void setBadgeCount(0, true);
}

export function getBadgeCount(): number {
  return currentCount;
}
