/**
 * Універсальний модал.
 *
 * Використання:
 *   const close = openModal({
 *     title: 'Підтвердження',
 *     body: html`<p>Видалити сесію?</p>`,
 *     actions: [
 *       { label: 'Скасувати', kind: 'ghost' },
 *       { label: 'Видалити',  kind: 'danger', onClick: () => { ... } }
 *     ]
 *   });
 */

import { html, raw, mount } from './dom';
import { icons } from './icons';

export interface ModalAction {
  label: string;
  kind?: 'primary' | 'secondary' | 'ghost' | 'danger';
  onClick?: () => void | Promise<void>;
  closeOnClick?: boolean;   // default true
}

export interface ModalOptions {
  title: string;
  body: HTMLElement | string;
  actions?: ModalAction[];
  closable?: boolean;       // default true (X кнопка + ESC + scrim)
  width?: number;
}

export function openModal(opts: ModalOptions): () => void {
  const scrim = html`<div class="modal-scrim" role="dialog" aria-modal="true"></div>`;
  const modal = html`
    <div class="modal" style="${opts.width ? `width: ${opts.width}px;` : ''}">
      <div class="modal-header">
        <div class="modal-title">${opts.title}</div>
        ${opts.closable !== false
          ? raw(`<button class="btn-ghost btn-sm" data-vm-modal-close aria-label="Закрити">${icons.x(14).value}</button>`)
          : ''
        }
      </div>
      <div class="modal-body" data-vm-modal-body></div>
      <div class="modal-footer" data-vm-modal-footer></div>
    </div>
  `;
  scrim.appendChild(modal);

  // Body
  const bodyEl = modal.querySelector<HTMLElement>('[data-vm-modal-body]')!;
  if (typeof opts.body === 'string') {
    bodyEl.textContent = opts.body;
  } else {
    mount(bodyEl, opts.body);
  }

  // Actions
  const footerEl = modal.querySelector<HTMLElement>('[data-vm-modal-footer]')!;
  if (opts.actions && opts.actions.length > 0) {
    for (const a of opts.actions) {
      const btn = document.createElement('button');
      btn.className = `btn btn-${a.kind ?? 'secondary'}`;
      btn.textContent = a.label;
      btn.addEventListener('click', async () => {
        try {
          await a.onClick?.();
        } finally {
          if (a.closeOnClick !== false) close();
        }
      });
      footerEl.appendChild(btn);
    }
  } else {
    footerEl.remove();
  }

  document.body.appendChild(scrim);
  document.body.style.overflow = 'hidden';

  const close = (): void => {
    if (!scrim.isConnected) return;
    scrim.remove();
    document.body.style.overflow = '';
    document.removeEventListener('keydown', onKey);
  };

  const onKey = (e: KeyboardEvent): void => {
    if (e.key === 'Escape' && opts.closable !== false) close();
  };
  document.addEventListener('keydown', onKey);

  scrim.addEventListener('click', (e) => {
    if (e.target === scrim && opts.closable !== false) close();
  });

  modal.querySelector('[data-vm-modal-close]')?.addEventListener('click', close);

  return close;
}

/**
 * Шорткат-підтвердження.
 *   const ok = await confirm({ title: 'Видалити?', body: '...' });
 */
export function confirm(opts: {
  title: string;
  body: string;
  confirmLabel?: string;
  cancelLabel?: string;
  danger?: boolean;
}): Promise<boolean> {
  return new Promise((resolve) => {
    openModal({
      title: opts.title,
      body: opts.body,
      actions: [
        { label: opts.cancelLabel ?? 'Скасувати', kind: 'ghost', onClick: () => resolve(false) },
        {
          label: opts.confirmLabel ?? 'Підтвердити',
          kind: opts.danger ? 'danger' : 'primary',
          onClick: () => resolve(true)
        }
      ]
    });
  });
}
