/**
 * Stance-класифікація через Qwen.
 * Виводимо одне з трьох слів і мапаємо на Stance.
 */

import { cleanText, chunkText } from '../text-utils';
import { loadQwen, type QwenEngineApi } from './engine';
import type { Stance } from '../../../types';

// Few-shot з прикладами сарказму, риторичних запитань та індиректної критики —
// це найскладніша частина для малих LLM. Збільшено покриття типових патернів,
// які трапляються в українському Telegram (іронія, "ну дякуємо", риторика).
const SYSTEM = `Класифікуй позицію коментаря щодо думки публікації ОДНИМ словом: ПІДТРИМУЄ, СПРОСТОВУЄ або НЕ_СТОСУЄТЬСЯ.

Правила:
ПІДТРИМУЄ — щиро погоджується, хвалить, дякує по суті, або підтверджує думку.
СПРОСТОВУЄ — не згоден, критикує, висміює, іронізує, саркастично "погоджується", або наводить контрприклад. Іронія = СПРОСТОВУЄ.
НЕ_СТОСУЄТЬСЯ — коментар не оцінює думку публікації: питання, побут, спам, реклама, побажання, привітання.

Приклади (вивчи патерни):
Публікація: «Новий парк дуже гарний» Коментар: «Супер, давно чекали!» => ПІДТРИМУЄ
Публікація: «Влада робить багато для людей» Коментар: «Та яка там влада, одна брехня» => СПРОСТОВУЄ
Публікація: «У місті відкрили парк» Коментар: «А коли вже дощ закінчиться?» => НЕ_СТОСУЄТЬСЯ
Публікація: «Президент великий лідер» Коментар: «Ну да, спаситель, ага, дякую за ціни» => СПРОСТОВУЄ
Публікація: «Дорогу відремонтували за рекордні строки» Коментар: «Через місяць знов розіб'ється» => СПРОСТОВУЄ
Публікація: «Закон підтримує бізнес» Коментар: «Чий бізнес? Своїх друзів?» => СПРОСТОВУЄ
Публікація: «Гарна ініціатива міськради» Коментар: «Так, нарешті щось корисне зробили» => ПІДТРИМУЄ
Публікація: «Президент відвідав фронт» Коментар: «Будь обережним, дякуємо за відвагу» => ПІДТРИМУЄ
Публікація: «Влада обіцяє підвищення зарплат» Коментар: «Скільки можна обіцяти? Покажіть результат» => СПРОСТОВУЄ
Публікація: «У парку відкрилось кафе» Коментар: «Хто власник?» => НЕ_СТОСУЄТЬСЯ
Публікація: «Цей чиновник зробив багато для міста» Коментар: «Ага, для свого міста — Дубаю» => СПРОСТОВУЄ
Публікація: «Підтримуємо армію» Коментар: «Слава ЗСУ, тримаймося!» => ПІДТРИМУЄ`;

export interface QwenStanceResult {
  stance: Stance;
  /** Qwen дає бінарне рішення, тому ці scores наближені 1/0 */
  scores: { support: number; oppose: number; unrelated: number };
  /** Сире слово, повернуте моделлю — корисно для дебагу */
  raw: string;
}

export async function qwenClassifyStance(
  postText: string,
  commentText: string,
  engine?: QwenEngineApi
): Promise<QwenStanceResult> {
  const post = chunkText(cleanText(postText), 200)[0] ?? '';
  const comment = cleanText(commentText);
  const llm = engine ?? await loadQwen();

  const reply = await llm.chat({
    system: SYSTEM,
    user: `Публікація: «${post}» Коментар: «${comment}» =>`,
    temperature: 0,
    maxTokens: 10,
    stop: ['\n']
  });
  return parseStanceReply(reply);
}

function parseStanceReply(raw: string): QwenStanceResult {
  // ВАЖЛИВО: спочатку перевіряємо "НЕ_СТОСУЄТЬСЯ" / "НЕ ПІДТРИМУЄ" —
  // інакше "НЕ ПІДТРИМУЄ" хибно матчить як 'support' через підрядок "ПІДТРИМ".
  const norm = raw.toUpperCase().replace(/[^A-ZА-ЯЇІЄҐ_\s]/giu, '').trim();
  const firstWordSection = norm.split(/[\s_]+/).slice(0, 4).join(' ');

  let stance: Stance = 'unrelated';
  // 1. Сильні негативні маркери — мають пріоритет
  if (/НЕ_СТОСУЄТЬСЯ|НЕСТОСУЄТЬСЯ|НЕ СТОСУЄТЬСЯ|ІНШЕ|СПАМ/i.test(firstWordSection)) {
    stance = 'unrelated';
  }
  // 2. Чітка опозиція
  else if (/^СПРОСТОВУЄ|^СПРОСТОВ|^ПРОТИ|^КРИТИК|ДИСКРЕДИТ|НЕ ПІДТРИМ|НЕ\sПІДТРИМ/i.test(firstWordSection)) {
    stance = 'oppose';
  }
  // 3. Підтримка (тільки якщо НЕ заперечення)
  else if (/^ПІДТРИМУЄ|^ПІДТРИМ|^ЗГОДЕН|^ЗГОДНИ/i.test(firstWordSection)) {
    stance = 'support';
  }
  else if (/СПРОСТОВ|КРИТИК/i.test(norm)) {
    stance = 'oppose';
  }
  else if (/ПІДТРИМ/i.test(norm) && !/НЕ_?\s?ПІДТРИМ/i.test(norm)) {
    stance = 'support';
  }

  const scores = {
    support:   stance === 'support'   ? 1 : 0,
    oppose:    stance === 'oppose'    ? 1 : 0,
    unrelated: stance === 'unrelated' ? 1 : 0
  };
  return { stance, scores, raw };
}
