/**
 * WebLLM engine для Qwen2.5-1.5B-Instruct (q4f16_1).
 *
 * Особливості:
 *  - lazy import @mlc-ai/web-llm (~1 МБ JS + 1 ГБ ваги моделі)
 *  - вимагає WebGPU (перевіряється викликачем перед start)
 *  - моделі MLC кешуються у Cache Storage / IndexedDB браузера автоматично
 */

import type { ProgressCallback } from '../progress';

const MODEL_ID = 'Qwen2.5-1.5B-Instruct-q4f16_1-MLC';

let enginePromise: Promise<any> | null = null;
let engineInstance: any | null = null;

export interface QwenChatOptions {
  system?: string;
  user: string;
  temperature?: number;
  maxTokens?: number;
  stop?: string[];
}

export interface QwenEngineApi {
  readonly modelId: string;
  chat(opts: QwenChatOptions): Promise<string>;
  unload(): Promise<void>;
}

export async function loadQwen(onProgress?: ProgressCallback): Promise<QwenEngineApi> {
  if (engineInstance) return wrap(engineInstance);
  if (enginePromise) return wrap(await enginePromise);

  enginePromise = (async () => {
    const webllm = await import('@mlc-ai/web-llm');
    const CreateMLCEngine = (webllm as any).CreateMLCEngine;
    if (!CreateMLCEngine) {
      throw new Error('WebLLM API не знайдено — оновіть @mlc-ai/web-llm');
    }
    const engine = await CreateMLCEngine(MODEL_ID, {
      initProgressCallback: (report: any) => {
        onProgress?.({
          model: MODEL_ID,
          status: report?.progress >= 1 ? 'done' : 'progress',
          progress: typeof report?.progress === 'number' ? Math.round(report.progress * 100) : undefined,
          file: report?.text
        });
      }
    });
    engineInstance = engine;
    onProgress?.({ model: MODEL_ID, status: 'ready' });
    return engine;
  })();

  return wrap(await enginePromise);
}

function wrap(engine: any): QwenEngineApi {
  return {
    modelId: MODEL_ID,
    async chat({ system, user, temperature = 0, maxTokens = 60, stop }): Promise<string> {
      const messages: { role: string; content: string }[] = [];
      if (system) messages.push({ role: 'system', content: system });
      messages.push({ role: 'user', content: user });

      const reply = await engine.chat.completions.create({
        messages,
        temperature,
        max_tokens: maxTokens,
        stop
      });
      const text = reply?.choices?.[0]?.message?.content ?? '';
      return String(text).trim();
    },
    async unload() {
      try { await engine.unload?.(); } catch { /* ignore */ }
      engineInstance = null;
      enginePromise = null;
    }
  };
}

export const QWEN_MODEL_ID = MODEL_ID;
