/**
 * Робота зі списком діалогів і вибраних для моніторингу каналів.
 *
 * - listDialogs() — отримати усі канали/мегагрупи з акаунту користувача
 * - resolveByUsername() — додати канал вручну за @username
 * - resolvePostPeer() — за TelegramPostRef повернути peer (для fetch коментарів)
 */

import { getTelegramClient } from './client';
import type { MonitoredChannel } from '../../types';
import type { TelegramPostRef } from './url-parser';

export interface DialogItem extends MonitoredChannel {
  /** Чи приватний (без @username) */
  isPrivate: boolean;
}

/**
 * Отримати список діалогів акаунту, відфільтрований лише до каналів і мегагруп.
 */
export async function listDialogs(opts?: { includePrivateChats?: boolean }): Promise<DialogItem[]> {
  const includePrivate = opts?.includePrivateChats ?? false;
  const client = await getTelegramClient();
  const raw = await client.getDialogs({ limit: 300, archived: false });

  const out: DialogItem[] = [];
  for (const d of raw) {
    const entity = d.entity;
    if (!entity) continue;
    const cls = entity.className ?? '';
    const isChannel = cls === 'Channel';            // Канал або мегагрупа
    const isChat    = cls === 'Chat';                // Звичайна група
    const isUser    = cls === 'User';

    // Фільтр: за замовчуванням тільки канали + мегагрупи
    if (!isChannel && !(isChat && includePrivate) && !(isUser && includePrivate)) continue;

    const id = String(entity.id?.toString?.() ?? entity.id);
    const accessHash = entity.accessHash ? String(entity.accessHash.toString?.() ?? entity.accessHash) : undefined;

    out.push({
      id,
      accessHash,
      title: entity.title ?? entity.firstName ?? '(без назви)',
      username: entity.username ?? undefined,
      isChannel: isChannel,
      isPrivate: !entity.username,
      participantsCount: entity.participantsCount ?? undefined
    });
  }
  return out;
}

/**
 * Додати канал/групу вручну за @username або посиланням t.me/...
 * Кидає помилку, якщо канал не знайдений або користувач не може його бачити.
 */
export async function resolveByUsername(usernameRaw: string): Promise<DialogItem> {
  const username = usernameRaw.replace(/^@/, '').replace(/^https?:\/\/t\.me\//i, '').split('/')[0];
  if (!username) throw new Error('Невірний username');

  const client = await getTelegramClient();
  const entity = await client.getEntity(username);
  if (!entity) throw new Error('Канал не знайдено');

  const cls = entity.className ?? '';
  const isChannel = cls === 'Channel';
  if (!isChannel && cls !== 'Chat') {
    throw new Error(`Це не канал і не група: ${cls}`);
  }

  return {
    id: String(entity.id?.toString?.() ?? entity.id),
    accessHash: entity.accessHash ? String(entity.accessHash.toString?.()) : undefined,
    title: entity.title ?? username,
    username: entity.username ?? username,
    isChannel,
    isPrivate: !entity.username,
    participantsCount: entity.participantsCount ?? undefined
  };
}

/**
 * За посиланням на пост (TelegramPostRef) повернути peer-entity для подальших операцій
 * (fetch комментаря, навігації тощо).
 */
export async function resolvePostPeer(ref: TelegramPostRef): Promise<any> {
  const client = await getTelegramClient();
  if (ref.username) {
    return client.getEntity(ref.username);
  }
  if (ref.channelInternalId !== undefined) {
    // private channel: формат "c/N" в URL — це абсолютний ID без -100 префіксу
    // gram.js приймає bigint або повний об'єкт через getEntity
    const id = ref.channelInternalId;
    return client.getEntity(id);
  }
  throw new Error('Неможливо визначити канал з ref');
}
