/**
 * Точка входу веб-застосунку.
 * Підключає всі стилі, ловить глобальні помилки і запускає кореневий компонент.
 */

import './styles/theme.css';
import './styles/base.css';
import './styles/components.css';

import { startApp } from './app';
import { toast } from './ui/shared/toast';

// ───────────────  Глобальна обробка помилок  ──────────────
window.addEventListener('error', (ev) => {
  // eslint-disable-next-line no-console
  console.error('[VM] window error:', ev.error ?? ev.message);
  toast.error(`Помилка: ${ev.message}`, { duration: 6000 });
});

window.addEventListener('unhandledrejection', (ev) => {
  // eslint-disable-next-line no-console
  console.error('[VM] unhandled rejection:', ev.reason);
  toast.error(`Помилка: ${String(ev.reason?.message ?? ev.reason)}`, { duration: 6000 });
});

// ───────────────  Запуск  ──────────────
const appRoot = document.getElementById('app');
if (!appRoot) {
  throw new Error('#app root not found in index.html');
}

// Прибираємо pre-bootstrap екран
const preboot = document.getElementById('prebootstrap');
preboot?.remove();

startApp(appRoot);
