/**
 * Web Crypto обгортка для шифрування користувацьких даних.
 *
 * Схема:
 *  1. PBKDF2-HMAC-SHA256, 250 000 ітерацій, 16-байтова сіль → AES-GCM 256 ключ
 *  2. Кожен зашифрований блоб має формат:
 *       [ 1 байт версії = 0x01 | 12 байт IV | N байт ciphertext (включно з GCM-тегом) ]
 *  3. Без пароля сесію не розшифрувати — навіть з фізичним доступом до браузера.
 */

const PBKDF2_ITERATIONS = 250_000;
const PBKDF2_HASH = 'SHA-256';
const AES_KEY_LENGTH = 256;
const SALT_BYTES = 16;
const IV_BYTES = 12;
const BLOB_VERSION = 0x01;

const subtle = (): SubtleCrypto => {
  if (!globalThis.crypto?.subtle) {
    throw new Error('Web Crypto API недоступний — потрібен HTTPS або localhost');
  }
  return globalThis.crypto.subtle;
};

/**
 * Згенерувати випадкову сіль для першого встановлення пароля.
 */
export function generateSalt(): Uint8Array {
  return globalThis.crypto.getRandomValues(new Uint8Array(SALT_BYTES));
}

/**
 * Згенерувати випадковий IV для кожної операції шифрування.
 */
export function generateIv(): Uint8Array {
  return globalThis.crypto.getRandomValues(new Uint8Array(IV_BYTES));
}

/**
 * Похідний AES-GCM ключ з пароля + солі.
 */
export async function deriveKey(password: string, salt: Uint8Array): Promise<CryptoKey> {
  const enc = new TextEncoder();
  const baseKey = await subtle().importKey(
    'raw',
    enc.encode(password),
    'PBKDF2',
    false,
    ['deriveKey']
  );
  return subtle().deriveKey(
    {
      name: 'PBKDF2',
      // TS 5.7+ розрізняє Uint8Array<ArrayBuffer> vs <ArrayBufferLike>; Web Crypto API хоче перший.
      salt: salt as BufferSource,
      iterations: PBKDF2_ITERATIONS,
      hash: PBKDF2_HASH
    },
    baseKey,
    { name: 'AES-GCM', length: AES_KEY_LENGTH },
    false,                  // extractable = false: ключ не можна експортувати
    ['encrypt', 'decrypt']
  );
}

/**
 * Зашифрувати довільні байти.
 */
export async function encrypt(key: CryptoKey, plaintext: Uint8Array): Promise<Uint8Array> {
  const iv = generateIv();
  const cipherBuf = await subtle().encrypt(
    { name: 'AES-GCM', iv: iv as BufferSource },
    key,
    plaintext as BufferSource
  );
  const cipher = new Uint8Array(cipherBuf);
  const out = new Uint8Array(1 + IV_BYTES + cipher.length);
  out[0] = BLOB_VERSION;
  out.set(iv, 1);
  out.set(cipher, 1 + IV_BYTES);
  return out;
}

/**
 * Розшифрувати блоб. Кидає DOMException('OperationError'), якщо пароль/ключ невірні.
 */
export async function decrypt(key: CryptoKey, blob: Uint8Array): Promise<Uint8Array> {
  if (blob.length < 1 + IV_BYTES + 16) {
    throw new Error('Зашифрований блоб занадто короткий');
  }
  if (blob[0] !== BLOB_VERSION) {
    throw new Error(`Непідтримувана версія шифроблоба: ${blob[0]}`);
  }
  const iv = blob.subarray(1, 1 + IV_BYTES);
  const cipher = blob.subarray(1 + IV_BYTES);
  const plainBuf = await subtle().decrypt(
    { name: 'AES-GCM', iv: iv as BufferSource },
    key,
    cipher as BufferSource
  );
  return new Uint8Array(plainBuf);
}

/**
 * Допоміжне: зашифрувати JSON-об'єкт.
 */
export async function encryptJson(key: CryptoKey, value: unknown): Promise<Uint8Array> {
  const json = JSON.stringify(value);
  return encrypt(key, new TextEncoder().encode(json));
}

/**
 * Допоміжне: розшифрувати JSON-об'єкт.
 */
export async function decryptJson<T = unknown>(key: CryptoKey, blob: Uint8Array): Promise<T> {
  const plain = await decrypt(key, blob);
  return JSON.parse(new TextDecoder().decode(plain)) as T;
}

/**
 * Чи помилка є наслідком невірного ключа/пароля? (AES-GCM тег не співпав)
 */
export function isAuthError(err: unknown): boolean {
  if (!(err instanceof Error)) return false;
  const name = (err as DOMException).name;
  return name === 'OperationError' || /OperationError|tag/i.test(err.message);
}

/**
 * Експортовані константи — корисні для тестів і UI-валідації.
 */
export const CRYPTO_INFO = {
  algorithm: 'AES-GCM',
  keyLength: AES_KEY_LENGTH,
  kdf: 'PBKDF2',
  kdfHash: PBKDF2_HASH,
  kdfIterations: PBKDF2_ITERATIONS,
  saltBytes: SALT_BYTES,
  ivBytes: IV_BYTES
} as const;
