/**
 * Парсинг t.me-посилань на пости й коментарі.
 *
 * Підтримувані формати:
 *   https://t.me/channelname/123          → public channel, post 123
 *   https://t.me/channelname/123?comment=456 → той самий post (коментар ігноруємо, аналізуємо весь пост)
 *   https://t.me/c/1234567890/123         → private channel, id у форматі "c/..."
 *   t.me/channelname/123                  → без протоколу
 *   @channelname + msgId окремо           → ручний ввід
 */

export interface TelegramPostRef {
  /** username каналу або undefined для приватних */
  username?: string;
  /** raw chat id для private (т.зв. format "c/N") */
  channelInternalId?: bigint;
  /** ID повідомлення (поста) */
  messageId: number;
}

const HOST_RE = /^(?:https?:\/\/)?(?:www\.)?t\.me\//i;

export function parseTelegramUrl(input: string): TelegramPostRef | null {
  const raw = input.trim();
  if (!raw) return null;

  let path: string;
  if (HOST_RE.test(raw)) {
    path = raw.replace(HOST_RE, '');
  } else if (/^@?[A-Za-z0-9_]{4,32}\/\d+/.test(raw)) {
    // спрощений варіант: channelname/123
    path = raw.replace(/^@/, '');
  } else {
    return null;
  }

  // Прибираємо query/hash
  const cleanPath = path.split(/[?#]/, 1)[0];
  const parts = cleanPath.split('/').filter(Boolean);

  if (parts.length < 2) return null;

  // Private channel form: /c/{internalId}/{msgId}
  if (parts[0] === 'c') {
    if (parts.length < 3) return null;
    const internal = BigInt(parts[1]);
    const msgId = Number(parts[2]);
    if (!Number.isFinite(msgId) || msgId <= 0) return null;
    return { channelInternalId: internal, messageId: msgId };
  }

  // Public form: /{username}/{msgId}
  const username = parts[0];
  if (!/^[A-Za-z][A-Za-z0-9_]{3,31}$/.test(username)) return null;
  const msgId = Number(parts[1]);
  if (!Number.isFinite(msgId) || msgId <= 0) return null;

  return { username, messageId: msgId };
}

/**
 * Зворотне: побудувати посилання на пост за username і id.
 */
export function buildPostUrl(usernameOrInternalId: string | bigint, msgId: number): string {
  if (typeof usernameOrInternalId === 'bigint') {
    return `https://t.me/c/${usernameOrInternalId}/${msgId}`;
  }
  return `https://t.me/${usernameOrInternalId}/${msgId}`;
}
