/**
 * Хедер застосунку: лого, назва, статус-індикатор підключення.
 */

import { html } from './dom';
import { strings } from '../../i18n/uk';

export type ConnectionStatus = 'idle' | 'connecting' | 'online' | 'offline' | 'scanning';

export interface HeaderApi {
  el: HTMLElement;
  setStatus(status: ConnectionStatus): void;
  setUser(user: { name: string; phone?: string } | null): void;
}

export function buildHeader(): HeaderApi {
  const root = html`
    <header class="app-header">
      <a class="app-logo" href="#" data-vm-logo>
        <img src="./icons/logo-wordmark.svg" alt="${strings.app.name}" />
      </a>

      <div class="app-header-spacer"></div>

      <div class="row gap-4">
        <div class="row gap-2" data-vm-user style="display:none;">
          <span style="color: var(--fg-muted)">${/* placeholder for user-icon? */ ''}</span>
          <span class="text-mono" style="font-size: var(--fs-xs); color: var(--fg-secondary);" data-vm-user-name></span>
        </div>

        <div class="app-status" data-vm-status>
          <span class="led led-idle" data-vm-status-led></span>
          <span data-vm-status-label>${strings.status.idle}</span>
        </div>
      </div>
    </header>
  `;

  const led       = root.querySelector<HTMLElement>('[data-vm-status-led]')!;
  const label     = root.querySelector<HTMLElement>('[data-vm-status-label]')!;
  const userBox   = root.querySelector<HTMLElement>('[data-vm-user]')!;
  const userName  = root.querySelector<HTMLElement>('[data-vm-user-name]')!;

  return {
    el: root,
    setStatus(status: ConnectionStatus) {
      led.className = 'led ' + (
        status === 'online'     ? 'led-success' :
        status === 'connecting' ? 'led-warning' :
        status === 'offline'    ? 'led-danger'  :
        status === 'scanning'   ? 'led-warning' :
                                  'led-idle'
      );
      label.textContent =
        status === 'online'     ? strings.status.online :
        status === 'connecting' ? strings.status.connecting :
        status === 'offline'    ? strings.status.offline :
        status === 'scanning'   ? strings.status.scanning :
                                  strings.status.idle;
    },
    setUser(user) {
      if (!user) {
        userBox.style.display = 'none';
        return;
      }
      userBox.style.display = '';
      userName.textContent = user.name + (user.phone ? `  ·  ${user.phone}` : '');
    }
  };
}
