/**
 * Monitoring engine — orchestrator.
 *
 * Зв'язує Telegram-клієнт + AI router + чергу + persistence + UI-події.
 * Singleton, щоб моніторинг продовжувався при перемиканні вкладок.
 */

import {
  startMonitoring,
  scanRecentHistory,
  type MonitorSubscription,
  type IncomingMessage
} from '../telegram';
import { getAiRouter } from '../ai';
import { setActiveAccuracy, getActiveProfile } from '../ai/accuracy';
import { requireVault } from '../storage/current-vault';
import { highlightHtml } from './highlight';
import { AsyncQueue } from './queue';
import { quickTopicPrefilter } from '../ai/hybrid/topic-matcher';
import { addEntry as addLabelEntry, isLabellingEnabled } from '../calibration';
import type {
  FoundPost,
  MonitoringConfig,
  MonitoredChannel,
  SearchMode,
  ThrottleMode,
  AccuracyLevel
} from '../../types';

export interface MonitoringStartOptions {
  channels: MonitoredChannel[];
  mode: SearchMode;
  words?: string;            // через кому
  ignoreWords?: string;
  topic?: string;
  threshold?: number;        // 0..1
  requireAll?: boolean;      // для mode === 'words'
  accuracy?: AccuracyLevel;  // рівень "Точність визначення" (1..5)
  throttleMode: ThrottleMode;
  /** undefined = real-time, число = годин у минуле для scan-режиму */
  historyHours?: number;
}

export type EngineStatus = 'idle' | 'starting' | 'scanning' | 'live' | 'stopping';

export interface EngineSnapshot {
  status: EngineStatus;
  startedAt?: number;
  options?: MonitoringStartOptions;
  matchedCount: number;
  processedCount: number;
  queueSize: number;
}

type EventMap = {
  status: (s: EngineSnapshot) => void;
  post:   (post: FoundPost) => void;
  error:  (err: Error) => void;
};

class MonitoringEngine {
  private subscription: MonitorSubscription | null = null;
  private abortController: AbortController | null = null;
  private queue: AsyncQueue<void> = new AsyncQueue(1);
  private listeners: { [K in keyof EventMap]: Set<EventMap[K]> } = {
    status: new Set(),
    post:   new Set(),
    error:  new Set()
  };

  private status: EngineStatus = 'idle';
  private currentOptions?: MonitoringStartOptions;
  private startedAt?: number;
  private matchedCount = 0;
  private processedCount = 0;

  // ───────────  Public API  ───────────
  isRunning(): boolean {
    return this.status !== 'idle' && this.status !== 'stopping';
  }

  snapshot(): EngineSnapshot {
    return {
      status: this.status,
      startedAt: this.startedAt,
      options: this.currentOptions,
      matchedCount: this.matchedCount,
      processedCount: this.processedCount,
      queueSize: this.queue.size
    };
  }

  on<K extends keyof EventMap>(event: K, handler: EventMap[K]): () => void {
    (this.listeners[event] as Set<EventMap[K]>).add(handler);
    return () => (this.listeners[event] as Set<EventMap[K]>).delete(handler);
  }

  async start(opts: MonitoringStartOptions): Promise<void> {
    if (this.isRunning()) {
      await this.stop();
    }
    this.currentOptions = opts;
    this.matchedCount = 0;
    this.processedCount = 0;
    this.startedAt = Date.now();
    this.setStatus('starting');
    if (opts.accuracy) setActiveAccuracy(opts.accuracy);

    try {
      // Прогрів AI (швидко покажемо progress через сторонній listener у UI)
      const router = await getAiRouter();
      // Гарантуємо завантаження моделей до старту
      await router.preload();

      if (typeof opts.historyHours === 'number') {
        this.setStatus('scanning');
        this.abortController = new AbortController();
        await scanRecentHistory(
          opts.channels,
          opts.historyHours,
          (msg) => this.handleMessage(msg, opts, router),
          this.abortController.signal
        );
        // Дочекатися, поки черга AI-класифікації спорожніє, перш ніж рапортувати idle.
        await this.queue.onIdle();
        this.setStatus('idle');
      } else {
        this.setStatus('live');
        this.subscription = await startMonitoring(opts.channels, (msg) => this.handleMessage(msg, opts, router));
      }
    } catch (err) {
      this.setStatus('idle');
      this.emit('error', err as Error);
      throw err;
    }
  }

  async stop(): Promise<void> {
    if (this.status === 'idle') return;
    this.setStatus('stopping');
    try {
      await this.subscription?.stop();
    } catch { /* ignore */ }
    this.subscription = null;
    this.abortController?.abort();
    this.abortController = null;
    this.queue.clear();
    this.setStatus('idle');
  }

  // ───────────  Internals  ───────────
  private setStatus(s: EngineStatus): void {
    this.status = s;
    this.emit('status', this.snapshot());
  }

  private emit<K extends keyof EventMap>(event: K, payload: Parameters<EventMap[K]>[0]): void {
    for (const l of this.listeners[event]) {
      try { (l as any)(payload); } catch (err) {
        // eslint-disable-next-line no-console
        console.error('[engine] listener error:', err);
      }
    }
  }

  private async handleMessage(
    msg: IncomingMessage,
    opts: MonitoringStartOptions,
    router: Awaited<ReturnType<typeof getAiRouter>>
  ): Promise<void> {
    if (!msg.rawText.trim()) return;

    // Throttle: ставимо в чергу
    const job = async (): Promise<void> => {
      this.processedCount++;
      this.emit('status', this.snapshot());

      // ignore-фільтр (швидкий — до AI)
      if (opts.ignoreWords?.trim()) {
        const ignore = opts.ignoreWords.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
        const lower = msg.rawText.toLowerCase();
        if (ignore.some(w => lower.includes(w))) return;
      }

      // Prefilter (тільки для topic-режиму, якщо вибрано prefilter mode)
      if (opts.mode === 'topic' && opts.throttleMode === 'prefilter' && opts.topic) {
        const pre = await quickTopicPrefilter(msg.rawText, opts.topic, 0.30);
        if (!pre.passes) return;
      }

      // Власне класифікація
      let matched = false;
      let score = 0;
      let highlightedHtml = '';

      // Дані для logging-у в labelling-store
      const profile = getActiveProfile();
      const accuracyLvl = opts.accuracy ?? 2;
      const effectiveMode = router.effectiveMode;
      const url = msg.channelUsername
        ? `https://t.me/${msg.channelUsername}/${msg.messageId}`
        : `tg://openmessage?chat_id=${msg.channelId}&message_id=${msg.messageId}`;

      let labelExtras: {
        chunkScores?: number[];
        perKeyword?: { keyword: string; score: number; matchedWord?: string }[];
        thresholdUsed: number;
        keywordsLogged?: string[];
      } | null = null;

      if (opts.mode === 'words') {
        const keywords = (opts.words ?? '').split(',').map(s => s.trim()).filter(Boolean);
        if (keywords.length === 0) return;
        const r = await router.matchByWords(msg.rawText, keywords, {
          requireAll: opts.requireAll
        });
        matched = r.matched;
        score = r.maxScore;
        labelExtras = {
          perKeyword: r.perKeyword,
          thresholdUsed: profile.wordsThreshold,
          keywordsLogged: keywords
        };
        if (matched) {
          const terms = r.perKeyword.filter(p => p.matchedWord).map(p => p.matchedWord!) as string[];
          highlightedHtml = highlightHtml(msg.rawText, terms.length ? terms : keywords);
        }
      } else {
        if (!opts.topic?.trim()) return;
        const r = await router.matchByTopic(msg.rawText, opts.topic);
        matched = r.matched;
        score = r.score;
        labelExtras = {
          chunkScores: r.chunkScores,
          thresholdUsed: profile.topicThreshold
        };
        if (matched) highlightedHtml = msg.rawText;
      }

      // ── Labelling: логуємо КОЖНЕ рішення моделі (matched та unmatched).
      // Це потрібно для grid-sweep по гіпотетичних порогах. Якщо вимкнено —
      // нічого не пишемо, щоб не накопичувати дані в звичайному моніторингу.
      if (isLabellingEnabled() && labelExtras) {
        try {
          await addLabelEntry({
            task: opts.mode,
            mode: effectiveMode,
            accuracy: accuracyLvl,
            threshold: labelExtras.thresholdUsed,
            text: msg.rawText.slice(0, 800),
            topic: opts.topic,
            keywords: labelExtras.keywordsLogged,
            score,
            chunkScores: labelExtras.chunkScores,
            perKeyword: labelExtras.perKeyword,
            modelDecision: matched ? 'matched' : 'unmatched',
            channelId: msg.channelId,
            channelTitle: msg.channelTitle,
            messageId: msg.messageId,
            url
          });
        } catch (err) {
          // eslint-disable-next-line no-console
          console.warn('[labelling] addEntry failed:', err);
        }
      }

      if (!matched) return;

      this.matchedCount++;
      const post: FoundPost = {
        number: this.matchedCount,
        channelId: msg.channelId,
        channelTitle: msg.channelTitle,
        channelUsername: msg.channelUsername,
        messageId: msg.messageId,
        postedAt: msg.postedAt,
        rawText: msg.rawText,
        highlightedHtml: highlightedHtml || msg.rawText,
        hasMedia: msg.hasMedia,
        url: msg.channelUsername
          ? `https://t.me/${msg.channelUsername}/${msg.messageId}`
          : `tg://openmessage?chat_id=${msg.channelId}&message_id=${msg.messageId}`,
        score
      };
      this.emit('post', post);
      this.emit('status', this.snapshot());

      // Persistence
      try {
        await requireVault().history.append(post);
      } catch (err) {
        // eslint-disable-next-line no-console
        console.warn('[engine] history append failed:', err);
      }
    };

    this.queue.enqueue(job).catch((err) => {
      // eslint-disable-next-line no-console
      console.error('[engine] job error:', err);
      this.emit('error', err);
    });
  }
}

let singleton: MonitoringEngine | null = null;

export function getMonitoringEngine(): MonitoringEngine {
  if (!singleton) singleton = new MonitoringEngine();
  return singleton;
}

/** Поточна конфігурація (для UI — щоб залити форму при поверненні на вкладку). */
export function getActiveConfig(): MonitoringConfig | null {
  const eng = getMonitoringEngine();
  const s = eng.snapshot();
  if (!s.options) return null;
  return {
    id: '__active__',
    name: 'Поточний моніторинг',
    mode: s.options.mode,
    words: s.options.words,
    ignoreWords: s.options.ignoreWords,
    topic: s.options.topic,
    threshold: s.options.threshold ?? 0.5,
    createdAt: s.startedAt ?? Date.now(),
    updatedAt: s.startedAt ?? Date.now()
  };
}
