/**
 * Embedding-модель: Xenova/multilingual-e5-small (~118M, q8 ≈ 120 МБ).
 *
 * Використовується для:
 *   - швидкого topic-prefilter в режимі real-time моніторингу
 *   - Mode A («співпадіння слів з відмінюванням») через word-level cosine
 *
 * Транформери.js v3 → пакет '@huggingface/transformers'.
 */

import type { ProgressCallback } from '../progress';

const MODEL_ID = 'Xenova/multilingual-e5-small';

// e5 модель вимагає префіксу 'query: ' або 'passage: ' для оптимальної якості.
// Для наших цілей (texts as data corpus) — використовуємо 'passage: '.
const E5_PREFIX = 'passage: ';

let extractorPromise: Promise<any> | null = null;
let extractorInstance: any | null = null;

export interface EmbeddingsApi {
  /** Векторна довжина (для e5-small = 384). */
  readonly dimension: number;
  /** Назва моделі. */
  readonly modelId: string;
  /** Перевести один або кілька текстів у вектори. */
  embed(text: string): Promise<Float32Array>;
  embed(texts: string[]): Promise<Float32Array[]>;
}

export async function loadEmbeddings(onProgress?: ProgressCallback): Promise<EmbeddingsApi> {
  if (extractorInstance) return wrap(extractorInstance);
  if (extractorPromise) {
    return wrap(await extractorPromise);
  }

  extractorPromise = (async () => {
    const { pipeline, env } = await import('@huggingface/transformers');
    // Кешуємо моделі в IndexedDB браузера
    env.allowLocalModels = false;
    env.useBrowserCache  = true;

    const extractor = await pipeline('feature-extraction', MODEL_ID, {
      dtype: 'q8' as any,
      progress_callback: (data: any) => {
        onProgress?.({
          model: MODEL_ID,
          file: data?.file,
          status: data?.status,
          progress: data?.progress,
          loaded: data?.loaded,
          total: data?.total
        });
      }
    });
    extractorInstance = extractor;
    onProgress?.({ model: MODEL_ID, status: 'ready' });
    return extractor;
  })();

  return wrap(await extractorPromise);
}

function wrap(extractor: any): EmbeddingsApi {
  return {
    dimension: 384,
    modelId: MODEL_ID,
    async embed(input: string | string[]): Promise<any> {
      const inputs = Array.isArray(input) ? input.map(t => E5_PREFIX + t) : [E5_PREFIX + input];
      const output = await extractor(inputs, { pooling: 'mean', normalize: true });
      // output.data — Float32Array довжиною N*dimension; output.dims — [N, dimension]
      const dims = output.dims as number[];
      const n = dims[0];
      const dim = dims[1];
      const data = output.data as Float32Array;

      if (!Array.isArray(input)) {
        return new Float32Array(data.buffer, data.byteOffset, dim);
      }
      const out: Float32Array[] = [];
      for (let i = 0; i < n; i++) {
        out.push(new Float32Array(data.buffer, data.byteOffset + i * dim * 4, dim));
      }
      return out;
    }
  };
}

// ────────────  Vector math  ────────────
export function cosineSimilarity(a: Float32Array, b: Float32Array): number {
  // e5 вектори вже нормалізовані → cosine = dot product
  let dot = 0;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) dot += a[i] * b[i];
  return dot;
}

export function maxCosine(target: Float32Array, candidates: Float32Array[]): number {
  let max = -1;
  for (const c of candidates) {
    const s = cosineSimilarity(target, c);
    if (s > max) max = s;
  }
  return max;
}
