/**
 * Крок 1: api_id + api_hash з https://my.telegram.org
 */

import { html, raw } from '../../shared/dom';
import { icons } from '../../shared/icons';
import { toast } from '../../shared/toast';
import type { WizardState } from '../wizard';

export interface ApiCredsStepApi {
  el: HTMLElement;
  onNext(handler: (creds: { apiId: number; apiHash: string }) => void): void;
}

export function buildApiCredsStep(state: WizardState): ApiCredsStepApi {
  const root = html`
    <div class="col gap-4">
      <div class="panel">
        <h3 style="margin-bottom: 12px;">Telegram API ключі</h3>
        <p class="text-secondary" style="margin-bottom: 16px;">
          Якщо ще не маєте — авторизуйтесь на
          <a href="https://my.telegram.org" target="_blank" rel="noreferrer">my.telegram.org</a>,
          відкрийте розділ <span class="text-mono">API development tools</span>, створіть application.
          Поля <span class="text-mono">App api_id</span> і <span class="text-mono">App api_hash</span> — введіть нижче.
        </p>
        <form class="col gap-4" data-vm-form>
          <div class="field">
            <label class="field-label" for="vm-api-id">api_id</label>
            <input
              type="text"
              id="vm-api-id"
              class="input input-mono"
              placeholder="напр. 1234567"
              inputmode="numeric"
              autocomplete="off"
              value="${state.apiId ?? ''}"
              required
            />
          </div>
          <div class="field">
            <label class="field-label" for="vm-api-hash">api_hash</label>
            <input
              type="text"
              id="vm-api-hash"
              class="input input-mono"
              placeholder="32 hex-символи"
              autocomplete="off"
              value="${state.apiHash ?? ''}"
              required
            />
            <div class="field-error hidden" data-vm-error></div>
          </div>
          <div class="row end">
            <button type="submit" class="btn btn-primary btn-lg" data-vm-submit>
              <span>Продовжити</span>
              ${raw(icons.chevronRight(16).value)}
            </button>
          </div>
        </form>
      </div>

      <div class="text-muted" style="font-size: var(--fs-xs);">
        api-ключі зберігаються лише в IndexedDB вашого браузера, зашифровані вашим паролем.
      </div>
    </div>
  `;

  const handlers: Array<(c: { apiId: number; apiHash: string }) => void> = [];
  const form = root.querySelector<HTMLFormElement>('[data-vm-form]')!;
  const errEl = root.querySelector<HTMLElement>('[data-vm-error]')!;
  const submitEl = root.querySelector<HTMLButtonElement>('[data-vm-submit]')!;

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    errEl.classList.add('hidden');
    const apiIdRaw  = (form.querySelector<HTMLInputElement>('#vm-api-id')!.value).trim();
    const apiHash   = (form.querySelector<HTMLInputElement>('#vm-api-hash')!.value).trim();
    const apiId = Number(apiIdRaw);
    if (!Number.isInteger(apiId) || apiId <= 0) {
      errEl.textContent = 'api_id має бути цілим числом';
      errEl.classList.remove('hidden');
      return;
    }
    if (!/^[a-f0-9]{32}$/i.test(apiHash)) {
      errEl.textContent = 'api_hash має бути 32-символьним hex-рядком';
      errEl.classList.remove('hidden');
      return;
    }

    submitEl.disabled = true;
    submitEl.querySelector('span')!.textContent = 'Підключаємось…';
    try {
      await state.authFlow.setApiCredentials(apiId, apiHash);
      handlers.forEach(h => h({ apiId, apiHash }));
    } catch (err) {
      toast.error(`Не вдалося підключитися: ${(err as Error).message}`);
    } finally {
      submitEl.disabled = false;
      submitEl.querySelector('span')!.textContent = 'Продовжити';
    }
  });

  return {
    el: root,
    onNext(h) { handlers.push(h); }
  };
}
