/**
 * Topic matching через Qwen.
 *
 * Промпт мінімалістичний, температура 0, очікуємо число 0.00–1.00.
 * Парсимо першим витягом числа з відповіді.
 */

import { cleanText, chunkText } from '../text-utils';
import { loadQwen, type QwenEngineApi } from './engine';
import type { TopicMatchResult } from '../hybrid/topic-matcher';
import { getActiveProfile } from '../accuracy';

// CALIBRATION NOTE (Jun 9): спершу замінили оригінальний мінімалістичний
// промпт на детальний з шкалою + 5 few-shot. Виміряли на реальних даних —
// Qwen-1.5B overfit'нувся на anchor "88" з прикладів і видавав 0.85 на майже
// будь-який короткий чат-меседж ("Спасибо", "Пильмені", "Спать"). FP-рейт ≈ 100%.
// Повертаємось до мінімалістичного промпту з мікс-якорями 92/5/60.
const SYSTEM = `Ти класифікатор тем. Оцінюєш, наскільки текст стосується вказаної теми.
Відповідай ТІЛЬКИ одним цілим числом від 0 до 100, де 100 = текст повністю про цю тему, а 0 = зовсім не про неї. Без пояснень і без інших символів.
Приклади: 92, 5, 60`;

export async function qwenMatchByTopic(
  rawText: string,
  topic: string,
  threshold?: number,
  engine?: QwenEngineApi
): Promise<TopicMatchResult> {
  const text = cleanText(rawText);
  if (!text || !topic.trim()) {
    return { matched: false, score: 0, chunkScores: [] };
  }
  const llm = engine ?? await loadQwen();

  // Qwen тепер враховує AccuracyProfile: чанкінг і кількість фрагментів
  // ідуть від профілю; threshold — або переданий, або з профілю (з невеликим
  // зсувом, бо Qwen-prompt дає інакший розподіл балів, ніж NLI).
  const profile = getActiveProfile();
  const chunks = chunkText(text, profile.topicChunkSize).slice(0, profile.topicMaxChunks);
  // Qwen-шкала після калібровки видає 0-100, де 50+ означає "переважно про тему".
  // Дефолтний поріг 0.55 уже непогано працює, але для рівня 1 послаблюємо до
  // 0.50, для рівня 3 трохи піднімаємо до 0.58 — це дає компроміс speed/precision.
  const qwenDefaults = { 1: 0.50, 2: 0.55, 3: 0.58 } as const;
  const th = threshold ?? qwenDefaults[profile.level] ?? 0.55;

  const chunkScores: number[] = [];
  for (const chunk of chunks) {
    const reply = await llm.chat({
      system: SYSTEM,
      user: `Тема: «${topic}»\nТекст: «${chunk}»\n\nОцінка (0-100):`,
      temperature: 0,
      maxTokens: 8,
      stop: ['\n']
    });
    const score = parseScoreReply(reply);
    chunkScores.push(score);
  }
  const score = chunkScores.length ? Math.max(...chunkScores) : 0;
  return { matched: score >= th, score, chunkScores };
}

function parseScoreReply(raw: string): number {
  const m = raw.replace(',', '.').match(/(\d?\.?\d+)/);
  if (!m) return 0;
  const v = Number(m[1]);
  if (!Number.isFinite(v)) return 0;
  if (v < 0) return 0;
  if (v > 1) return v > 100 ? 0 : v / 100;
  return v;
}
