/**
 * Async queue для серіалізації важких AI-задач.
 *
 * Гарантує, що в один момент часу обробляється не більше {concurrency} задач.
 * Підтримує AbortSignal для зупинки потоку.
 */

export class AsyncQueue<T> {
  private queue: Array<{ task: () => Promise<T>; resolve: (v: T) => void; reject: (e: unknown) => void }> = [];
  private active = 0;
  private idleWaiters: Array<() => void> = [];

  constructor(private readonly concurrency = 1) {}

  enqueue(task: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.queue.push({ task, resolve, reject });
      this.tick();
    });
  }

  get size(): number { return this.queue.length; }
  get inflight(): number { return this.active; }

  clear(): void {
    const dropped = this.queue.splice(0);
    for (const d of dropped) d.reject(new Error('Queue cleared'));
    this.tick();
  }

  /** Резолвиться, коли черга порожня і немає активних задач. */
  onIdle(): Promise<void> {
    if (this.active === 0 && this.queue.length === 0) return Promise.resolve();
    return new Promise<void>(resolve => { this.idleWaiters.push(resolve); });
  }

  private tick(): void {
    while (this.active < this.concurrency && this.queue.length > 0) {
      const job = this.queue.shift()!;
      this.active++;
      job.task()
        .then(v => job.resolve(v))
        .catch(e => job.reject(e))
        .finally(() => {
          this.active--;
          this.tick();
        });
    }
    if (this.active === 0 && this.queue.length === 0 && this.idleWaiters.length > 0) {
      const waiters = this.idleWaiters;
      this.idleWaiters = [];
      for (const resolve of waiters) resolve();
    }
  }
}
