/**
 * Сторінка моніторингу.
 *
 * Лівий блок: форма (тема/слова/ігнор/режим), вибір каналів, контролі;
 * Правий блок: real-time лента знайдених публікацій.
 */

import { html, raw, mount } from '../shared/dom';
import { icons } from '../shared/icons';
import { toast } from '../shared/toast';
import { strings } from '../../i18n/uk';
import { getMonitoringEngine, type EngineSnapshot } from '../../core/monitoring/engine';
import { requireVault } from '../../core/storage/current-vault';
import { getAccuracyProfile, setActiveAccuracy } from '../../core/ai/accuracy';
import type { FoundPost, MonitoredChannel, SearchMode, ThrottleMode, AccuracyLevel } from '../../types';

export function buildMonitoringPage(): HTMLElement {
  injectStyles();
  const root = html`
    <section class="page" id="page-monitoring" role="tabpanel" style="max-width: var(--max-content-w);">
      <header class="page-header">
        <div>
          <div class="page-eyebrow">${strings.monitoring.eyebrow}</div>
          <h1 class="page-title">${strings.monitoring.pageTitle}</h1>
        </div>
        <div class="row gap-2" data-vm-status-badges></div>
      </header>

      <div class="vm-monitor-grid">
        <aside class="vm-monitor-left">
          <div class="panel" data-vm-channels-block></div>
          <div class="panel" data-vm-form-block></div>
          <div class="panel" data-vm-status-block></div>
        </aside>

        <section class="vm-monitor-right">
          <div class="panel" style="height: 100%; display: flex; flex-direction: column; padding: 0;">
            <div class="vm-results-header">
              <div class="text-eyebrow">Знайдені публікації</div>
              <div class="row gap-2">
                <span class="badge" data-vm-results-count>0</span>
                <button class="btn btn-ghost btn-sm" data-vm-clear-results title="Очистити">
                  ${raw(icons.trash(14).value)}
                </button>
              </div>
            </div>
            <div class="vm-results-list" data-vm-results></div>
          </div>
        </section>
      </div>
    </section>
  `;

  const engine = getMonitoringEngine();
  let selectedChannels: MonitoredChannel[] = [];

  // ───────────────  Form state  ───────────────
  const formState = {
    mode: 'topic' as SearchMode,
    words: '',
    ignoreWords: '',
    topic: '',
    accuracy: 2 as AccuracyLevel,
    requireAll: false,
    throttleMode: 'queue' as ThrottleMode,
    historyHours: 0    // 0 = real-time
  };

  // ───────────────  Render channels block  ───────────────
  const channelsBlock = root.querySelector<HTMLElement>('[data-vm-channels-block]')!;
  const renderChannels = async () => {
    try {
      selectedChannels = await requireVault().channels.list();
    } catch {
      selectedChannels = [];
    }
    channelsBlock.replaceChildren(html`
      <div>
        <div class="row between" style="margin-bottom: 8px;">
          <div class="text-eyebrow">Канали моніторингу</div>
          <span class="text-mono text-accent" style="font-size: var(--fs-xs);">${selectedChannels.length}</span>
        </div>
        ${selectedChannels.length === 0
          ? raw(`<div class="text-muted" style="font-size: var(--fs-sm);">Жодного каналу не обрано. Додайте в <strong>Налаштуваннях</strong>.</div>`)
          : raw(`<div class="vm-mini-channels">
              ${selectedChannels.slice(0, 8).map(c => `<span class="vm-mini-channel" title="${c.username ? '@' + c.username : c.title}">${c.title}</span>`).join('')}
              ${selectedChannels.length > 8 ? `<span class="vm-mini-channel" style="background: var(--bg-base);">+${selectedChannels.length - 8}</span>` : ''}
            </div>`)
        }
      </div>
    `);
  };
  void renderChannels();

  // ───────────────  Render form block  ───────────────
  const formBlock = root.querySelector<HTMLElement>('[data-vm-form-block]')!;
  const formEl = html`
    <div class="col gap-4">
      <div class="text-eyebrow">Конфігурація</div>

      <div class="field">
        <label class="field-label">Режим</label>
        <div class="vm-segmented">
          <label class="vm-seg">
            <input type="radio" name="vm-mode" value="topic" ${formState.mode === 'topic' ? 'checked' : ''} />
            <span>За темою (AI)</span>
          </label>
          <label class="vm-seg">
            <input type="radio" name="vm-mode" value="words" ${formState.mode === 'words' ? 'checked' : ''} />
            <span>За словами</span>
          </label>
        </div>
      </div>

      <div class="field" data-vm-topic-field>
        <label class="field-label" for="vm-topic">Тема публікації</label>
        <input
          type="text"
          id="vm-topic"
          class="input"
          placeholder="напр. «дискредитація місцевої влади»"
          value="${formState.topic}"
        />
      </div>

      <div class="field" data-vm-words-field style="display:none;">
        <label class="field-label" for="vm-words">Ключові слова (через кому, фрази у "лапках")</label>
        <input
          type="text"
          id="vm-words"
          class="input"
          placeholder='напр. влада, корупція, "погана дорога"'
          value="${formState.words}"
        />
        <label class="checkbox" style="margin-top: 8px;">
          <input type="checkbox" id="vm-require-all" ${formState.requireAll ? 'checked' : ''} />
          <span class="text-secondary">Тільки якщо ВСІ слова знайдено</span>
        </label>
      </div>

      <div class="field">
        <label class="field-label" for="vm-ignore">Ігнорувати, якщо містить (через кому)</label>
        <input
          type="text"
          id="vm-ignore"
          class="input"
          placeholder="реклама, спам"
          value="${formState.ignoreWords}"
        />
      </div>

      <div class="field">
        <label class="field-label">
          Точність визначення: <span data-vm-acc-name class="text-accent text-mono">${getAccuracyProfile(formState.accuracy).label}</span>
        </label>
        <input type="range" id="vm-accuracy" min="1" max="3" step="1" value="${formState.accuracy}" style="width: 100%;" />
        <div class="text-muted" data-vm-acc-desc style="font-size: var(--fs-xs); margin-top: 4px;">${getAccuracyProfile(formState.accuracy).description}</div>
      </div>

      <div class="field">
        <label class="field-label">Часовий діапазон</label>
        <select class="select" id="vm-history">
          <option value="0">Реальний час (real-time)</option>
          <option value="1">За останню годину</option>
          <option value="3">За останні 3 години</option>
          <option value="6">За останні 6 годин</option>
          <option value="12">За останні 12 годин</option>
          <option value="24">За останні 24 години</option>
        </select>
      </div>

      <div class="field">
        <label class="field-label">Стратегія обробки</label>
        <select class="select" id="vm-throttle">
          <option value="queue">Черга — обробляти всі по черзі</option>
          <option value="prefilter">Префільтр — embedding-скрінінг перед NLI (швидше)</option>
        </select>
      </div>

      <button class="btn btn-primary btn-lg btn-block" data-vm-toggle>
        ${raw(icons.play(16).value)}
        <span>Запустити моніторинг</span>
      </button>
    </div>
  `;
  mount(formBlock, formEl);

  // Form interactions
  const updateModeUi = () => {
    const topicField = formEl.querySelector<HTMLElement>('[data-vm-topic-field]')!;
    const wordsField = formEl.querySelector<HTMLElement>('[data-vm-words-field]')!;
    topicField.style.display = formState.mode === 'topic' ? '' : 'none';
    wordsField.style.display = formState.mode === 'words' ? '' : 'none';
  };
  updateModeUi();

  formEl.querySelectorAll<HTMLInputElement>('input[name="vm-mode"]').forEach(r => {
    r.addEventListener('change', () => {
      if (r.checked) {
        formState.mode = r.value as SearchMode;
        updateModeUi();
      }
    });
  });
  formEl.querySelector<HTMLInputElement>('#vm-topic')!.addEventListener('input', (e) => {
    formState.topic = (e.target as HTMLInputElement).value;
  });
  formEl.querySelector<HTMLInputElement>('#vm-words')!.addEventListener('input', (e) => {
    formState.words = (e.target as HTMLInputElement).value;
  });
  formEl.querySelector<HTMLInputElement>('#vm-ignore')!.addEventListener('input', (e) => {
    formState.ignoreWords = (e.target as HTMLInputElement).value;
  });
  formEl.querySelector<HTMLInputElement>('#vm-require-all')!.addEventListener('change', (e) => {
    formState.requireAll = (e.target as HTMLInputElement).checked;
  });
  const accSlider = formEl.querySelector<HTMLInputElement>('#vm-accuracy')!;
  const accNameEl = formEl.querySelector<HTMLElement>('[data-vm-acc-name]')!;
  const accDescEl = formEl.querySelector<HTMLElement>('[data-vm-acc-desc]')!;
  const applyAccuracy = (lvl: AccuracyLevel) => {
    const p = getAccuracyProfile(lvl);
    accNameEl.textContent = p.label;
    accDescEl.textContent = p.description;
  };
  accSlider.addEventListener('input', () => {
    const lvl = Math.min(3, Math.max(1, parseInt(accSlider.value, 10))) as AccuracyLevel;
    formState.accuracy = lvl;
    applyAccuracy(lvl);
    setActiveAccuracy(lvl);
    void requireVault().settings.update({ accuracy: lvl }).catch(() => {});
  });
  // Ініціалізація з збережених налаштувань
  void requireVault().settings.get().then((s) => {
    const lvl = Math.min(3, Math.max(1, s.accuracy ?? 2)) as AccuracyLevel;
    formState.accuracy = lvl;
    accSlider.value = String(lvl);
    applyAccuracy(lvl);
    setActiveAccuracy(lvl);
  }).catch(() => {});
  formEl.querySelector<HTMLSelectElement>('#vm-history')!.addEventListener('change', (e) => {
    formState.historyHours = parseInt((e.target as HTMLSelectElement).value, 10);
  });
  formEl.querySelector<HTMLSelectElement>('#vm-throttle')!.addEventListener('change', (e) => {
    formState.throttleMode = (e.target as HTMLSelectElement).value as ThrottleMode;
  });

  // ───────────────  Toggle  ───────────────
  const toggleBtn = formEl.querySelector<HTMLButtonElement>('[data-vm-toggle]')!;
  toggleBtn.addEventListener('click', async () => {
    if (engine.isRunning()) {
      await engine.stop();
      return;
    }
    if (selectedChannels.length === 0) {
      toast.warning('Спочатку оберіть канали в Налаштуваннях');
      return;
    }
    if (formState.mode === 'topic' && !formState.topic.trim()) {
      toast.warning('Введіть тему для моніторингу');
      return;
    }
    if (formState.mode === 'words' && !formState.words.trim()) {
      toast.warning('Введіть ключові слова');
      return;
    }

    try {
      toast.info('Завантаження AI-моделей може зайняти кілька хвилин при першому запуску');
      await engine.start({
        channels: selectedChannels,
        mode: formState.mode,
        words: formState.words,
        ignoreWords: formState.ignoreWords,
        topic: formState.topic,
        accuracy: formState.accuracy,
        requireAll: formState.requireAll,
        throttleMode: formState.throttleMode,
        historyHours: formState.historyHours > 0 ? formState.historyHours : undefined
      });
    } catch (err) {
      toast.error(`Не вдалося запустити: ${(err as Error).message}`);
    }
  });

  // ───────────────  Status block + badges  ───────────────
  const statusBlock = root.querySelector<HTMLElement>('[data-vm-status-block]')!;
  const badgesEl = root.querySelector<HTMLElement>('[data-vm-status-badges]')!;
  const updateStatus = (snap: EngineSnapshot) => {
    const ledClass =
      snap.status === 'live'     ? 'led-success' :
      snap.status === 'scanning' ? 'led-warning' :
      snap.status === 'starting' ? 'led-warning' :
      snap.status === 'stopping' ? 'led-warning' :
                                   'led-idle';
    const statusLabel =
      snap.status === 'live'     ? 'real-time' :
      snap.status === 'scanning' ? 'скан історії' :
      snap.status === 'starting' ? 'старт…' :
      snap.status === 'stopping' ? 'зупинка…' :
                                   'очікування';

    statusBlock.replaceChildren(html`
      <div class="col gap-3">
        <div class="text-eyebrow">Статус</div>
        <div class="row gap-3">
          <span class="led ${ledClass}" style="width: 12px; height: 12px;"></span>
          <span class="text-mono" style="font-size: var(--fs-sm); letter-spacing: var(--tracking-wide); text-transform: uppercase;">${statusLabel}</span>
        </div>
        <div class="vm-status-grid">
          <div>
            <div class="text-muted text-mono" style="font-size: var(--fs-xs); letter-spacing: var(--tracking-widest); text-transform: uppercase;">Оброблено</div>
            <div class="text-mono" style="font-size: var(--fs-xl);">${snap.processedCount}</div>
          </div>
          <div>
            <div class="text-muted text-mono" style="font-size: var(--fs-xs); letter-spacing: var(--tracking-widest); text-transform: uppercase;">Збігів</div>
            <div class="text-mono text-accent" style="font-size: var(--fs-xl);">${snap.matchedCount}</div>
          </div>
          <div>
            <div class="text-muted text-mono" style="font-size: var(--fs-xs); letter-spacing: var(--tracking-widest); text-transform: uppercase;">У черзі</div>
            <div class="text-mono" style="font-size: var(--fs-xl);">${snap.queueSize}</div>
          </div>
        </div>
      </div>
    `);

    badgesEl.replaceChildren(html`
      <span class="badge ${snap.status === 'live' ? 'badge-success' : ''}">
        ${raw(icons.radar(12).value)}
        <span>${statusLabel}</span>
      </span>
      ${snap.matchedCount > 0 ? raw(`<span class="badge badge-accent"><strong>${snap.matchedCount}</strong></span>`) : ''}
    `);

    toggleBtn.innerHTML = snap.status === 'idle' || snap.status === 'stopping'
      ? `${icons.play(16).value}<span>Запустити моніторинг</span>`
      : `${icons.stop(16).value}<span>Зупинити</span>`;
    toggleBtn.classList.toggle('btn-danger', snap.status !== 'idle' && snap.status !== 'stopping');
    toggleBtn.classList.toggle('btn-primary', snap.status === 'idle' || snap.status === 'stopping');
  };
  updateStatus(engine.snapshot());

  // ───────────────  Results list  ───────────────
  const resultsEl    = root.querySelector<HTMLElement>('[data-vm-results]')!;
  const resultsCount = root.querySelector<HTMLElement>('[data-vm-results-count]')!;
  const clearBtn     = root.querySelector<HTMLButtonElement>('[data-vm-clear-results]')!;

  const posts: FoundPost[] = [];
  const renderPosts = () => {
    resultsCount.textContent = String(posts.length);
    if (posts.length === 0) {
      resultsEl.replaceChildren(html`
        <div class="text-muted center" style="height: 100%; padding: 40px; text-align: center;">
          Поки що нічого не знайдено. Налаштуйте конфігурацію зліва й натисніть «Запустити моніторинг».
        </div>
      `);
      return;
    }
    resultsEl.replaceChildren();
    for (const p of posts) {
      resultsEl.appendChild(renderPostCard(p));
    }
  };
  renderPosts();

  clearBtn.addEventListener('click', () => {
    posts.length = 0;
    renderPosts();
  });

  // ───────────────  Subscriptions to engine  ───────────────
  const unsubStatus = engine.on('status', updateStatus);
  const unsubPost   = engine.on('post',   (post) => {
    posts.unshift(post);     // нові згори
    if (posts.length > 200) posts.length = 200;
    renderPosts();
  });
  const unsubError  = engine.on('error',  (err) => toast.error(`Engine: ${err.message}`));

  // Підвантажуємо ostatni відомі знахідки з історії (якщо є)
  void (async () => {
    try {
      const history = await requireVault().history.list();
      const recent = history.slice(0, 20);
      if (recent.length && posts.length === 0) {
        posts.push(...recent);
        renderPosts();
      }
    } catch { /* ignore */ }
  })();

  // Cleanup коли вкладка міняється — слухачі не залишаться повзти
  root.addEventListener('vm-unmount', () => {
    unsubStatus();
    unsubPost();
    unsubError();
  });

  return root;
}

// ───────────────  Post card  ───────────────
function renderPostCard(p: FoundPost): HTMLElement {
  const time = new Date(p.postedAt).toLocaleTimeString('uk-UA', { hour: '2-digit', minute: '2-digit' });
  const date = new Date(p.postedAt).toLocaleDateString('uk-UA');
  return html`
    <article class="vm-post">
      <header class="vm-post-head">
        <span class="vm-post-num">#${p.number}</span>
        <span class="vm-post-channel">${p.channelTitle}</span>
        ${p.hasMedia ? raw(`<span class="badge badge-info">${icons.folder(10).value}<span>media</span></span>`) : ''}
        ${typeof p.score === 'number' ? raw(`<span class="badge"><span class="text-mono">${p.score.toFixed(2)}</span></span>`) : ''}
        <span class="vm-post-time text-mono">${date} ${time}</span>
      </header>
      <div class="vm-post-body">${raw(p.highlightedHtml)}</div>
      <footer class="vm-post-foot">
        <a href="${p.url}" target="_blank" rel="noreferrer" class="text-accent" style="font-family: var(--font-mono); font-size: var(--fs-xs);">
          ${p.url}
        </a>
      </footer>
    </article>
  `;
}

// ───────────────  Inline styles  ───────────────
let stylesInjected = false;
function injectStyles(): void {
  if (stylesInjected) return;
  stylesInjected = true;
  const s = document.createElement('style');
  s.textContent = `
    .vm-monitor-grid {
      display: grid;
      grid-template-columns: 380px 1fr;
      gap: var(--space-6);
      flex: 1;
      min-height: 0;
    }
    .vm-monitor-left, .vm-monitor-right {
      display: flex; flex-direction: column;
      gap: var(--space-4);
      min-height: 0;
    }
    .vm-monitor-right { min-height: 600px; }

    .vm-segmented {
      display: flex; gap: 2px;
      background: var(--bg-base);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-sm);
      padding: 3px;
    }
    .vm-seg {
      flex: 1; display: flex;
      align-items: center; justify-content: center;
      height: 32px; padding: 0 12px;
      cursor: pointer;
      font-size: var(--fs-sm);
      color: var(--fg-secondary);
      border-radius: var(--radius-xs);
      transition: background var(--t-fast);
    }
    .vm-seg input { position: absolute; opacity: 0; pointer-events: none; }
    .vm-seg:hover { color: var(--fg-primary); }
    .vm-seg:has(input:checked) {
      background: var(--accent-soft);
      color: var(--accent);
    }

    .vm-mini-channels {
      display: flex; flex-wrap: wrap; gap: 4px;
    }
    .vm-mini-channel {
      font-family: var(--font-mono);
      font-size: var(--fs-xs);
      padding: 4px 8px;
      background: var(--bg-elevated);
      border: 1px solid var(--border-subtle);
      border-radius: var(--radius-xs);
      color: var(--fg-secondary);
      white-space: nowrap;
      overflow: hidden; text-overflow: ellipsis;
      max-width: 140px;
    }

    .vm-status-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: var(--space-3);
    }

    .vm-results-header {
      display: flex; align-items: center; justify-content: space-between;
      padding: var(--space-4) var(--space-5);
      border-bottom: 1px solid var(--border-subtle);
    }
    .vm-results-list {
      flex: 1;
      overflow-y: auto;
      padding: var(--space-3);
      display: flex; flex-direction: column; gap: var(--space-3);
    }

    .vm-post {
      background: var(--bg-elevated);
      border: 1px solid var(--border-subtle);
      border-left: 3px solid var(--accent);
      border-radius: var(--radius-sm);
      padding: var(--space-3) var(--space-4);
      animation: vm-fade-in var(--t-base);
    }
    .vm-post-head {
      display: flex; align-items: center; gap: var(--space-2);
      flex-wrap: wrap;
      margin-bottom: var(--space-2);
    }
    .vm-post-num {
      font-family: var(--font-mono);
      font-size: var(--fs-xs);
      color: var(--fg-muted);
    }
    .vm-post-channel {
      font-size: var(--fs-sm);
      font-weight: 600;
      color: var(--fg-primary);
    }
    .vm-post-time {
      margin-left: auto;
      font-size: var(--fs-xs);
      color: var(--fg-muted);
    }
    .vm-post-body {
      font-size: var(--fs-base);
      color: var(--fg-primary);
      line-height: var(--lh-relaxed);
      white-space: pre-wrap;
      word-break: break-word;
    }
    .vm-post-foot {
      margin-top: var(--space-2);
      padding-top: var(--space-2);
      border-top: 1px dashed var(--border-subtle);
    }
    .vm-mark {
      background: var(--accent-soft);
      color: var(--accent);
      padding: 0 4px;
      border-radius: 2px;
      font-weight: 600;
    }

    @media (max-width: 1100px) {
      .vm-monitor-grid { grid-template-columns: 1fr; }
      .vm-monitor-right { min-height: 400px; }
    }
  `;
  document.head.appendChild(s);
}
