/**
 * Тонка обгортка над gram.js TelegramClient для veles-monitor-web.
 *
 * Особливості:
 *  - lazy-import gram.js (важка бібліотека) — підвантажується лише коли потрібно
 *  - persistent connection після першого підключення; закриваємо лише на logout
 *  - StringSession зберігається у зашифрованому vault
 *  - api_id/api_hash беремо з vault.secure.getApiCreds()
 *
 * Замість прямого імпорту 'telegram' — використовуйте loadTelegramClient().
 */

import { requireVault } from '../storage/current-vault';

// ───────────────  Типи для gram.js (мінімальний інтерфейс)  ───────────────
// Повний тип TelegramClient з gram.js дуже широкий; нам потрібна лише підмножина.
// Тримаємо `any` лише на межі імпорту, а назовні — типобезпечні методи.
type GramJsModules = {
  TelegramClient: any;
  StringSession: any;
  Api: any;
  errors: any;
  events: any;
};

let modulesPromise: Promise<GramJsModules> | null = null;

async function loadGramJs(): Promise<GramJsModules> {
  if (modulesPromise) return modulesPromise;
  modulesPromise = (async (): Promise<GramJsModules> => {
    // gram.js експортує:
    //   'telegram'           → TelegramClient
    //   'telegram/sessions'  → StringSession
    //   'telegram/tl'        → Api
    //   'telegram/events'    → NewMessage etc.
    //   'telegram/errors'    → SessionPasswordNeededError, PhoneCodeInvalidError, ...
    const [tg, sess, tl, events, errors] = await Promise.all([
      import('telegram'),
      import('telegram/sessions'),
      import('telegram/tl'),
      import('telegram/events'),
      import('telegram/errors')
    ]);
    return {
      TelegramClient: (tg as any).TelegramClient,
      StringSession:  (sess as any).StringSession,
      Api:            (tl as any).Api,
      errors:         errors,
      events:         events
    };
  })();
  return modulesPromise;
}

// ───────────────  Глобальний клієнт  ───────────────────────────────────
let clientPromise: Promise<any> | null = null;
let clientInstance: any | null = null;
let sessionPersistTimer: ReturnType<typeof setInterval> | null = null;

export interface TgConnectionInfo {
  apiId: number;
  apiHash: string;
  sessionString: string;
}

/**
 * Гарантує наявність живого підключеного клієнта.
 * Якщо вперше — створює, конектиться, повертає; інакше повертає кешований.
 */
export async function getTelegramClient(opts?: TgConnectionInfo): Promise<any> {
  if (clientInstance) return clientInstance;
  if (clientPromise) return clientPromise;

  clientPromise = (async () => {
    const vault = requireVault();
    const creds = opts ?? await loadCredsFromVault();
    if (!creds) {
      throw new Error('Telegram-облікові дані відсутні у vault — потрібен onboarding');
    }

    const { TelegramClient, StringSession } = await loadGramJs();
    const session = new StringSession(creds.sessionString);
    const client = new TelegramClient(session, creds.apiId, creds.apiHash, {
      connectionRetries: 5,
      useWSS: true,
      autoReconnect: true,
      requestRetries: 2,
      // Явні параметри пристрою — інакше gram.js у браузері підставляє "Unknown",
      // що Telegram гірше обробляє при видачі коду авторизації.
      deviceModel: 'Veles Monitor Web',
      systemVersion: (typeof navigator !== 'undefined' && navigator.platform) ? navigator.platform : 'Web',
      appVersion: '0.1.0',
      langCode: 'uk',
      systemLangCode: 'uk',
      // gram.js пише дуже багато логів — приглушуємо до warn
      baseLogger: makeLogger('warn')
    });

    await client.connect();
    clientInstance = client;

    // Автозбереження сесії при змінах
    void persistSessionIfChanged(vault, creds.sessionString, () => client.session.save());

    return client;
  })();

  return clientPromise;
}

async function loadCredsFromVault(): Promise<TgConnectionInfo | null> {
  const vault = requireVault();
  const [creds, session] = await Promise.all([
    vault.secure.getApiCreds(),
    vault.secure.getSession()
  ]);
  if (!creds) return null;
  return {
    apiId: creds.apiId,
    apiHash: creds.apiHash,
    sessionString: session ?? ''
  };
}

async function persistSessionIfChanged(
  vault: ReturnType<typeof requireVault>,
  initial: string,
  getCurrent: () => string
): Promise<void> {
  let last = initial;
  // Перевіряємо кожні 5 секунд протягом життя клієнта.
  // Це найпростіша стратегія; gram.js не дає прямого "onSessionChange".
  // Зберігаємо handle і чистимо попередній таймер, щоб уникнути витоку
  // інтервалів при reconnect/logout.
  if (sessionPersistTimer) clearInterval(sessionPersistTimer);
  sessionPersistTimer = setInterval(async () => {
    try {
      const cur = getCurrent();
      if (cur && cur !== last) {
        await vault.secure.setSession(cur);
        last = cur;
      }
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn('[tg] session persist failed:', err);
    }
  }, 5_000);
}

export async function disconnectTelegram(): Promise<void> {
  if (sessionPersistTimer) {
    clearInterval(sessionPersistTimer);
    sessionPersistTimer = null;
  }
  if (!clientInstance) return;
  try {
    await clientInstance.disconnect();
  } catch {
    // ignore
  }
  clientInstance = null;
  clientPromise = null;
}

/**
 * Чи зараз клієнт підключений?
 */
export async function isConnected(): Promise<boolean> {
  if (!clientInstance) return false;
  try {
    return !!clientInstance.connected;
  } catch {
    return false;
  }
}

/**
 * Чи авторизована поточна сесія?
 */
export async function isAuthorized(): Promise<boolean> {
  const client = clientInstance;
  if (!client) return false;
  try {
    return !!(await client.isUserAuthorized());
  } catch {
    return false;
  }
}

/**
 * Експорт лоадерів — щоб інші модулі (auth, channels, monitor) могли
 * без повторного import-у дістати потрібні класи.
 */
export async function getGramJs(): Promise<GramJsModules> {
  return loadGramJs();
}

// ────────────────────  Логер  ────────────────────
function makeLogger(level: 'error' | 'warn' | 'info' | 'debug'): any {
  const order = { error: 0, warn: 1, info: 2, debug: 3 } as const;
  const min = order[level];
  return {
    log: (lvl: keyof typeof order, msg: string) => {
      if ((order[lvl] ?? 4) <= min) {
        // eslint-disable-next-line no-console
        console.log(`[gram.js ${lvl}]`, msg);
      }
    },
    error: (msg: string) => makeLogger('error').log('error', msg),
    warn:  (msg: string) => makeLogger('warn').log('warn', msg),
    info:  (msg: string) => makeLogger('info').log('info', msg),
    debug: (msg: string) => makeLogger('debug').log('debug', msg),
    canSend: (lvl: keyof typeof order) => (order[lvl] ?? 4) <= min,
    setLevel: () => {},
    getDateTime: () => new Date().toISOString()
  };
}
